import {CrystalSealSlot,SEAL_ID,SEAL_FULL} from './CrystalSealSlot';
/** Actual source before-call snapshots from continuous paid-spin prefixes;
 * see find-seal-playback-seeds.ts. Offline QA only, not production RNG selection. */
export const SEAL_AUDIT_CASES:Record<string,{seed:number;mask:number}>={empty:{seed:10955961,mask:SEAL_FULL},break:{seed:1424613447,mask:SEAL_FULL},clear:{seed:3021800199,mask:512},prize5:{seed:3021800199,mask:512},prize1:{seed:2391367697,mask:16},prize2:{seed:1571898795,mask:12288},multi:{seed:723946008,mask:16384}};
export function crystalSealAudit(params:URLSearchParams){const slot=new CrystalSealSlot(),outcome=params.get('audit-seal-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','single-win':'break','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,saved=SEAL_AUDIT_CASES[kind];
 if(saved){const spin=(bet:number)=>{let seed=saved.seed;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};slot.setProgress({[SEAL_ID+':'+bet]:[saved.mask]});const result=slot.spin(bet,rng);if(kind==='clear'||kind.startsWith('prize')){if(!result.featureChoices||kind.startsWith('prize')&&result.featureChoices.results[0].rounds?.[1].sealFeature?.multiplier!==Number(kind.slice(5)))throw Error('Stale seal audit seed');}else if(kind==='empty'?result.wins.length!==0:kind==='multi'?new Set(result.wins.map(w=>w.symbol)).size<2:!result.sealFeature?.removed.length)throw Error('Stale seal audit seed');return result;};slot.demoSpin=spin;if(kind==='clear'||kind.startsWith('prize'))slot.bonusDemoSpin=spin;}
 return slot;
}
