import {CellDrop,Win} from './SlotMain';
import {ROSE_INPUTS} from './RoseOrbitMath';
import {createRoseClusterEvaluator} from './RoseOrbitCluster';
import {TumbleGame,TumbleFrame,TumbleTile,indices,adjacent,randomIndex} from './TumbleCore';

export const roseRotation=(c:number)=> (4-c%5)*5+Math.floor(c/5);
export class RoseOrbitSlot extends TumbleGame {
 private readonly baseWild=ROSE_INPUTS.baseWild;private readonly freeWild=ROSE_INPUTS.freeWild;private readonly purchaseWild=ROSE_INPUTS.purchaseWild;private readonly baseGate=ROSE_INPUTS.baseGate;private readonly freeGate=ROSE_INPUTS.freeGate;private feature=false;private purchasing=false;private entrance=false;
 private clusterEvaluator?:ReturnType<typeof createRoseClusterEvaluator>;
 clusters(board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=5):Win[]{if(neighbors||minimum!==5)return super.clusters(board,bet,multiplier,neighbors,minimum);this.clusterEvaluator??=createRoseClusterEvaluator(Array.from({length:6},(_,j)=>this.id(j)),this.wild!, (j,n)=>this.unit(j,n));return this.clusterEvaluator(board,bet,multiplier);}
 private uniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Rose RNG');return u;}
 draw(rng:()=>number){if(!this.entrance)return super.draw(rng);this.entrance=false;
  const p=this.baseGate,weights:number[]=[];let comb=1;for(let k=0;k<=25;k++){if(k>=3)weights.push(comb*p**k*(1-p)**(25-k));comb=comb*(25-k)/(k+1);}
  let roll=this.uniform(rng)*weights.reduce((a,b)=>a+b,0),k=25;for(let j=0;j<weights.length;j++){roll-=weights[j];if(roll<0){k=j+3;break;}}const pos=Array.from({length:25},(_,i)=>i);for(let i=0;i<k;i++){const j=i+Math.floor(this.uniform(rng)*(25-i));[pos[i],pos[j]]=[pos[j],pos[i]];}const marked=new Set(pos.slice(0,k));return pos.map((_,c)=>marked.has(c)?this.id('scatter'):this.plain(rng,false));
 }
 private plain(rng:()=>number,free:boolean){const w=free?(this.purchasing?this.purchaseWild:this.freeWild):this.baseWild,weights=[12,12,12,12,12,12,w];let roll=this.uniform(rng)*(72+w);for(let j=0;j<7;j++){roll-=weights[j];if(roll<0)return this.id(j===6?'wild':j);}return this.wild!;}
 protected pick(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Rose RNG');const p=this.feature?this.freeGate:this.baseGate;if(u<p)return this.id('scatter');const w=this.feature?(this.purchasing?this.purchaseWild:this.freeWild):this.baseWild;let roll=(u-p)/(1-p)*(72+w);for(let j=0;j<7;j++){roll-=j===6?w:12;if(roll<0)return this.id(j===6?'wild':j);}return this.wild!;}
 prepareBonusPurchase(bet:number,rng:()=>number){const saved=this.purchasing;this.purchasing=true;this.entrance=true;try{return super.prepareBonusPurchase(bet,rng);}finally{this.purchasing=saved;this.entrance=false;this.feature=false;}}
 readonly columns=5;readonly rows=5;readonly hasBonus=true;
 readonly config=this.configFor('rose-orbit-voyage','장미 궤도 항해','ROSE ORBIT VOYAGE',['붉은 장미','금빛 망원경','초록 행성','청색 나침반','보라 운석','흰 달','여우 WILD','궤도 문'],['0','1','2','3','4','5','wild','scatter'],'5×5 · 연결5개. 당첨마다 판을 반시계90도 회전 후 중력 낙하. 2×2 장미가 아래2칸을 누르면 배수 +2. 문3개: 무료6회, 문3개 재발동 +2(총24회).');
 private roll(bet:number,rng:()=>number,free:boolean){const saved=this.feature;this.feature=free;try{let board=this.draw(rng),multi=1,raw=0;const frames:TumbleFrame[]=[];this.frame(frames,board,'land','장미 궤도 착지');const scatter=indices(board,this.bonusSymbol!).length;let giant:number[]=[];
  if(randomIndex(rng,free?3:7)===0){const x=randomIndex(rng,4),y=randomIndex(rng,3);giant=[y*5+x,y*5+x+1,(y+1)*5+x,(y+1)*5+x+1];giant.forEach(c=>board[c]=this.id(0));const crushed=[(y+2)*5+x,(y+2)*5+x+1];multi+=2;const tiles=board.map((_,cell)=>({cell,x:cell%5+.5,y:Math.floor(cell/5)+.5,w:1,h:1})).filter(t=>!giant.slice(1).includes(t.cell));tiles.find(t=>t.cell===giant[0])!.w=2;tiles.find(t=>t.cell===giant[0])!.h=2;tiles.find(t=>t.cell===giant[0])!.x+=.5;tiles.find(t=>t.cell===giant[0])!.y+=.5;
   this.frame(frames,board,'transform','거대 장미 · 아래 두 심볼 압축 ×'+multi,{cells:crushed,tiles});const n=this.gravity(board,new Set(crushed),rng,new Set(giant));board=n.board;this.frame(frames,board,'drop','압축 빈자리 보충',{moves:n.moves,tiles});this.frame(frames,board,'transform','압축 완료 · 장미 네 칸으로 분리',{cells:giant});}
  for(let step=0;;step++){const wins=this.clusters(board,bet,multi);if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells));this.frame(frames,board,'win','궤도 클러스터 ×'+multi,{wins,cells:Array.from(remove)});raw+=wins.reduce((n,w)=>n+w.amount,0);if(raw>=bet*this.maxWin)break;
   // Rotate tokens AND holes before applying gravity in the new direction.
   const before=[...board],moves:CellDrop[]=[],rotated=new Set<number>();for(let from=0;from<25;from++){const to=roseRotation(from);board[to]=before[from];moves.push({from,to,symbol:before[from]});if(remove.has(from))rotated.add(to);}
   this.frame(frames,board,'move','판 전체 반시계90도 회전',{moves,cells:Array.from(rotated)});const next=this.gravity(board,rotated,rng);board=next.board;this.frame(frames,board,'drop','새 중력 방향 낙하',{moves:next.moves});}
  return{round:this.round(bet,frames),scatter};}finally{this.feature=saved;}
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.roll(bet,rng,false);if(base.scatter<3)return this.finish([base.round]);const rounds=[base.round];let left=6,awarded=6;while(left>0){left--;const next=this.roll(bet,rng,true),extra=next.scatter>=3?Math.min(2,24-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:6});}
}
