import {ExpansionSlot,ExpansionFrame,Geometry} from './ExpansionCore';
import {CellDrop,SpinResult,Win} from './SlotMain';
import {COSMIC_INPUTS as M,cosmicUniform} from './CosmicNativeMath';
const cosmicCodes=new Map([...Array.from({length:8},(_,n)=>['cosmic-herd-cascade-'+n,n] as const),['cosmic-herd-cascade-wild',8] as const,['cosmic-herd-cascade-scatter',9] as const]);
const pools=new Map<string,{id:string;weight:number}[]>();
const numericPools=new WeakMap<{id:string;weight:number}[],{code:number;weight:number}[]>();
export class CosmicNativeSlot extends ExpansionSlot {
 get bonusSymbol(){return undefined;}
 unit(symbol:number,count:number){return M.paytable[symbol]?.[Math.min(5,Math.max(3,count))-3]||0;}
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(g.columns!==5||g.rows!==3||Object.keys(opts).length||this.config.id!=='cosmic-herd-cascade')return super.evaluate(board,bet,g,opts);
  if(!this.bets.includes(bet)||board.length!==15)throw Error('Invalid expansion board or wager');
  const codes=board.map(id=>{const n=cosmicCodes.get(id);if(n===undefined)throw Error('Invalid expansion board or wager');return n;}),wins:Win[]=[];
  // Only the first non-WILD symbol and the highest all-WILD prefix can win.
  // Keep symbol0 first, strict greater-than ties and the original round order.
  for(let line=0;line<this.paylines.length;line++){
   const path=this.paylines[line];let lead=9;for(const c of path)if(codes[c]!==8){lead=codes[c];break;}
   let best:Win|undefined;
   for(const symbol of lead>0&&lead<8?[0,lead]:[0]){
    let count=0;for(const c of path){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}
    if(count<3)continue;const mult=this.unit(symbol,count),amount=Math.round(bet*mult);
    if(!best||amount>best.amount)best={line,symbol:this.id(symbol),cells:path.slice(0,count),amount,multiplier:mult};
   }
   if(best&&best.amount>0)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }

 private pool(free:boolean,hasScatter:boolean){
  const high=free?M.freeHigh:M.paidHigh,key=[high,M.wild,M.scatter,hasScatter].join('/'),prior=pools.get(key);if(prior)return prior;
  const regular=1-M.wild-M.scatter,pool=[{id:this.id(0),weight:regular*high},...Array.from({length:7},(_,n)=>({id:this.id(n+1),weight:regular*(1-high)/7})),{id:this.id('wild'),weight:M.wild},{id:this.id('scatter'),weight:hasScatter?0:M.scatter}].filter(v=>v.weight>0);pools.set(key,pool);return pool;
 }
 private grid(bet:number,rng:()=>number,free:boolean){if(!this.bets.includes(bet))throw Error('Invalid bet');const board:string[]=[],seen=Array(5).fill(false);for(let c=0;c<15;c++){const pool=this.pool(free,seen[c%5]);let roll=cosmicUniform(rng)*(seen[c%5]?1-M.scatter:1),id=pool[pool.length-1].id;for(const v of pool){roll-=v.weight;if(roll<0){id=v.id;break;}}board.push(id);if(id===this.id('scatter'))seen[c%5]=true;}return board;}
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng,false);}
 private freeAward(chain:number){return chain>=8?50:chain>=7?25:chain>=6?15:chain>=5?10:chain>=4?7:0;}
 private cascadeRound(input:string[],bet:number,rng:()=>number,free:boolean,budget:{remaining:number},left?:number){
  this.validate(input,bet);const frames=[this.frame(input,'reels','심볼 착지')];let board=[...input],chain=0;
  for(let stage=0;budget.remaining>0;stage++){
   const win=this.hit(board,bet,'연쇄 '+(stage+1)+' · 당첨 먼저 표시');frames.push(win);budget.remaining-=win.wins.reduce((n,w)=>n+w.amount,0);if(budget.remaining<=0){frames.push(this.frame(board,'state','최대 지급 한도 도달'));break;}
   const removed=Array.from(new Set(win.wins.flatMap(w=>w.cells)));if(!removed.length)break;
   const empty=[...board];removed.forEach(c=>empty[c]='');frames.push(this.frame(empty,'remove','당첨 확인 후 제거 · 빈칸',removed));chain++;
   const next=[...board],moves:CellDrop[]=[],refill=this.grid(bet,rng,free);
   for(let col=0;col<5;col++){const available=[col+10,col+5,col],survivors=available.filter(c=>!removed.includes(c));available.forEach((to,i)=>{const from=survivors[i]??(col-5*(i-survivors.length+1)),symbol=from>=0?board[from]:refill[to];next[to]=symbol;moves.push({to,from,symbol});});}frames.push(this.frame(next,'drop','신규 심볼 낙하',removed,{moves,held:[]}));board=next;
  }
  let shown=0;for(const frame of frames){if(frame.action==='remove')shown++;frame.panel={label:left===undefined?'CASCADE / FREE':'CASCADE / LEFT',values:[shown,left??this.freeAward(shown)],columns:2};}
  return{round:this.round(bet,frames),chain};
 }
 private package(base:SpinResult,chain:number,bet:number,rng:()=>number,budget:{remaining:number}){
  const count=this.freeAward(chain);if(!count)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(base.board,'trigger',chain+'연쇄 · 무료 '+count+'회 확정',[],{panel:{label:'CASCADE / FREE',values:[chain,count],columns:2}}));
  const rounds=[base];for(let left=count-1;left>=0;left--)rounds.push({...this.cascadeRound(this.grid(bet,rng,true),bet,rng,true,budget,left).round,freeSpinsRemaining:left});return this.finish(rounds,{freeSpinsAwarded:count,featureOnly:false});
 }
 play(board:string[],bet:number,rng:()=>number){const budget={remaining:bet*this.maxWin},item=this.cascadeRound(board,bet,rng,false,budget);return this.package(item.round,item.chain,bet,rng,budget);}
 private screenPaid(bet:number,rng:()=>number){
  // Exact original draw/drop/rounded line law, without display frames.
  // Only the four-cascade structural gate selects an entrance.
  const grid=()=>{const board:number[]=[],seen=Array(5).fill(false);for(let c=0;c<15;c++){const source=this.pool(false,seen[c%5]);let pool=numericPools.get(source);if(!pool){pool=source.map(v=>({code:cosmicCodes.get(v.id)!,weight:v.weight}));numericPools.set(source,pool);}let u=cosmicUniform(rng)*(seen[c%5]?1-M.scatter:1),code=pool[pool.length-1].code;for(const v of pool){u-=v.weight;if(u<0){code=v.code;break;}}board.push(code);if(code===9)seen[c%5]=true;}return board;};
  let board=grid(),chain=0,budget=bet*this.maxWin;
  for(;;){let payout=0,removed=0;
   for(const path of this.paylines){let lead=9;for(const c of path)if(board[c]!==8){lead=board[c];break;}let best=0,length=0;for(const symbol of lead>0&&lead<8?[0,lead]:[0]){let count=0;for(const c of path){if(board[c]!==symbol&&board[c]!==8)break;count++;}if(count<3)continue;const amount=Math.round(bet*this.unit(symbol,count));if(amount>best){best=amount;length=count;}}if(best){payout+=best;for(let i=0;i<length;i++)removed|=1<<path[i];}}
   budget-=payout;if(budget<=0||!removed)return chain;
   chain++;const next=[...board],refill=grid();for(let col=0;col<5;col++){const available=[col+10,col+5,col],survivors=available.filter(c=>!(removed&(1<<c)));available.forEach((to,i)=>{const from=survivors[i]??(col-5*(i-survivors.length+1));next[to]=from>=0?board[from]:refill[to];});}board=next;
  }
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  // Condition solely on the actual paid cascade gate. No sampled money,
  // winning board or previous loss controls the entrance law.
  if(!this.bets.includes(bet))throw Error('Invalid bet');for(;;){const samples:number[]=[],chain=this.screenPaid(bet,()=>{const u=rng();samples.push(u);return u;});if(chain<4)continue;let cursor=0;const replay=()=>{if(cursor>=samples.length)throw Error('Cosmic entrance replay exhausted');return samples[cursor++];},item=this.cascadeRound(this.grid(bet,replay,false),bet,replay,false,{remaining:bet*this.maxWin});if(cursor!==samples.length||item.chain!==chain)throw Error('Cosmic entrance replay differs');item.round.wins=[];item.round.payout=0;for(const f of item.round.expansionFeature!.frames)f.wins=[];return this.purchaseFromResult(this.package(item.round,item.chain,bet,rng,{remaining:bet*this.maxWin}));}
 }
}
