import {Win} from './SlotMain';

/** Rose's fixed 5×5 graph. Numeric membership replaces repeated Set/string
 * lookups, retaining the original up/down/left/right LIFO traversal order.
 * Unit awards are cached from the actual native table; no RNG is consumed. */
export function createRoseClusterEvaluator(ids:string[],wild:string,unit:(symbol:number,count:number)=>number){
 if(ids.length!==6)throw Error('Invalid Rose symbol table');
 const units=ids.map((_,symbol)=>Array.from({length:26},(_,count)=>unit(symbol,count)));
 return (board:string[],bet:number,multiplier=1):Win[]=>{
  if(board.length!==25)throw Error('Invalid Rose graph');
  const masks=[0,0,0,0,0,0];let wildMask=0;
  for(let cell=0;cell<25;cell++){
   const value=board[cell];if(value===wild)wildMask|=1<<cell;
   else{const symbol=ids.indexOf(value);if(symbol>=0)masks[symbol]|=1<<cell;}
  }
  const wins:Win[]=[];
  for(let symbol=0;symbol<6;symbol++){
   let remaining=masks[symbol]|wildMask;
   while(remaining){
    const first=remaining&-remaining,stack=[31-Math.clz32(first)],cells:number[]=[];
    let component=first;remaining^=first;
    while(stack.length){
     const cell=stack.pop()!;cells.push(cell);
     const push=(neighbor:number)=>{const bit=1<<neighbor;if(remaining&bit){remaining^=bit;component|=bit;stack.push(neighbor);}};
     if(cell>=5)push(cell-5);if(cell<20)push(cell+5);
     if(cell%5)push(cell-1);if(cell%5<4)push(cell+1);
    }
    if((component&masks[symbol])&&cells.length>=5)wins.push({line:-1,symbol:ids[symbol],cells,amount:bet*units[symbol][cells.length]*multiplier,multiplier});
   }
  }
  return wins;
 };
}
