import type {Win} from './SlotMain';
// Signal has no substitute symbols: each cell belongs to exactly one component.
// Precompute native up/down/left/right adjacency; DFS push/pop order stays exact.
const neighbors=Array.from({length:35},(_,c)=>[c-5,c+5,...(c%5?[c-1]:[]),...(c%5<4?[c+1]:[])].filter(n=>n>=0&&n<35));
const nativeSymbols=Array.from({length:6},(_,n)=>'signal-stack-ruins-'+n);
export function signalClusters(slot:{id:(n:number)=>string;unit:(symbol:number,count:number)=>number},board:string[],bet:number,multiplier:number):Win[]{
 const symbols=Uint8Array.from(board,id=>{const n=id.charCodeAt(id.length-1)-48;return n>=0&&n<6&&id===nativeSymbols[n]?n+1:0;}),seen=new Uint8Array(35),stack=new Int8Array(35),wins:Win[][]=Array.from({length:6},()=>[]);
 for(let start=0;start<35;start++){
  if(seen[start]||symbols[start]<1||symbols[start]>6)continue;
  const symbol=symbols[start],cells:number[]=[];let size=1;stack[0]=start;seen[start]=1;
  while(size){const cell=stack[--size];cells.push(cell);for(const n of neighbors[cell])if(!seen[n]&&symbols[n]===symbol){seen[n]=1;stack[size++]=n;}}
  if(cells.length>=5)wins[symbol-1].push({line:-1,symbol:slot.id(symbol-1),cells,amount:bet*slot.unit(symbol-1,cells.length)*multiplier,multiplier});
 }
 return wins.flat();
}
