import {nativeClusterWins} from './NativeClusterEvaluator';
import {cloneSlotData,SpinResult,Win,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,TumbleTile,indices,adjacent,randomIndex} from './TumbleCore';
import {ORBITAL_INPUTS as M,orbitalUniform,OrbitalInput} from './OrbitalNativeMath';
export const HEX_CELLS=Array.from({length:49},(_,c)=>c).filter(c=>{const q=c%7-3,r=Math.floor(c/7)-3;return Math.max(Math.abs(q),Math.abs(r),Math.abs(q+r))<=3;});
export const HEX_RINGS=[1,2,3].map(radius=>HEX_CELLS.filter(c=>{const q=c%7-3,r=Math.floor(c/7)-3;return Math.max(Math.abs(q),Math.abs(r),Math.abs(q+r))===radius;}).sort((a,b)=>Math.atan2(Math.floor(a/7)-3,a%7-3+(Math.floor(a/7)-3)/2)-Math.atan2(Math.floor(b/7)-3,b%7-3+(Math.floor(b/7)-3)/2)));
export const hexNeighbors=(c:number)=>[c-1,c+1,c-7,c+7,c-6,c+6].filter(n=>HEX_CELLS.includes(n)&&Math.abs(n%7-c%7)<=1&&Math.abs(Math.floor(n/7)-Math.floor(c/7))<=1);
export const HEX_TILES:TumbleTile[]=HEX_CELLS.map(cell=>({cell,x:cell%7+.5+(Math.floor(cell/7)-3)/2,y:Math.floor(cell/7)+.5,w:.9,h:.9}));
const orbitalPools=new WeakMap<OrbitalInput,OrbitalInput&{id:string;ids:string[];weights:number[]}>();
export class OrbitalNativeSlot extends TumbleGame {
 readonly columns=7;readonly rows=7;readonly hasBonus=true;
 clusters(board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=this.threshold):Win[]{return nativeClusterWins(this,board,bet,multiplier,neighbors,minimum);}
 private nativeFree=false;
 pick(rng:()=>number=Math.random){const p=this.nativeFree?M.free:M.paid,id=this.config.id;let pool=orbitalPools.get(p);if(!pool||pool.id!==id||pool.high!==p.high||pool.wild!==p.wild||pool.scatter!==p.scatter){const rest=1-p.wild-p.scatter,weights=[rest*p.high,...Array(5).fill(rest*(1-p.high)/5),p.wild,p.scatter],ids=weights.map((_,i)=>this.id(i===6?'wild':i===7?'scatter':i));pool={...p,id,ids,weights};orbitalPools.set(p,pool);}let u=orbitalUniform(rng);for(let i=0;i<pool.weights.length;i++){u-=pool.weights[i];if(u<0)return pool.ids[i];}return pool.ids[pool.weights.findLastIndex(v=>v>0)];}
 private phaseDraw(rng:()=>number,free:boolean){const old=this.nativeFree;this.nativeFree=free;try{return this.draw(rng);}finally{this.nativeFree=old;}}
 readonly config=this.configFor('orbital-crystal-core','궤도 수정핵','ORBITAL CRYSTAL CORE',['붉은 운석','황색 운석','초록 운석','청색 운석','보라 운석','흰 운석','중력 WILD','궤도 신호'],['0','1','2','3','4','5','wild','scatter'],'육각3링 · 연결6개. 당첨 뒤 링 회전. WILD는 중심으로 이동·흡수되어 배수 +1. 회전 Spot이 고정 Zone과 만나면 링 변환, Zone의 신호는 무료5회(총30회 상한). 자연 진입은 중심 배수·Spot 유지. 구매는 독립 무료5회·중심×1·Spot1/2/3에서 시작.');
 readonly threshold=6;
 idleFrame(){
  const board=Array.from({length:this.columns*this.rows},(_,cell)=>HEX_CELLS.includes(cell)?this.id(cell%this.regularCount):this.id('void'));board[24]=this.wild!;
  return{action:'state' as const,board,caption:'육각 궤도 · 수정 착지 대기',wins:[],cells:[],moves:[],badges:{24:'×1'},marks:HEX_RINGS.map(ring=>ring[0]),tiles:HEX_TILES,stationary:[24]};
 }
 private roll(input:string[],bet:number,rng:()=>number,bank:{multi:number;spots:number[]},free:boolean){const old=this.nativeFree;this.nativeFree=free;try{return this.nativeRoll(input,bet,rng,bank,free);}finally{this.nativeFree=old;}}
 private nativeRoll(input:string[],bet:number,rng:()=>number,bank:{multi:number;spots:number[]},free:boolean){
  let board=[...input];for(let c=0;c<49;c++)if(!HEX_CELLS.includes(c))board[c]=this.id('void');board[24]=this.wild!;
  const frames:TumbleFrame[]=[],options=()=>({tiles:HEX_TILES,badges:{24:'×'+bank.multi},marks:HEX_RINGS.map(r=>r[0])});let bonus=0;
  this.frame(frames,board,'land',free?'궤도 무료 · 중심 배수 유지':'궤도 수정 착지',{...options(),stationary:[24]});
  let spent=0;for(let step=0;spent<bet*this.maxWin;step++){if(step>=100000)throw Error('Orbital cascade did not settle');
   const wins=this.clusters(board,bet,bank.multi,hexNeighbors,6);if(!wins.length)break;spent+=wins.reduce((a,w)=>a+w.amount,0);
   const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>board[c]!==this.wild));this.frame(frames,board,'win','수정 클러스터 ×'+bank.multi,{...options(),wins,cells:Array.from(remove)});
   const next=this.gravity(board,remove,rng,new Set(indices(board,this.wild!)));board=next.board;this.frame(frames,board,'drop','육각 궤도 보충',{...options(),moves:next.moves});
   const before=[...board],moves:CellDrop[]=[];
   HEX_RINGS.forEach((ring,i)=>{ring.forEach((from,j)=>{const to=ring[(j+1)%ring.length];board[to]=before[from];moves.push({from,to,symbol:before[from]});});bank.spots[i]=(bank.spots[i]+1)%ring.length;});
   this.frame(frames,board,'move','세 링 회전',{...options(),moves});
   // Nearest first; a token moves at most one ring each cascade.
   const tokens=indices(board,this.wild!).filter(c=>c!==24).sort((a,b)=>HEX_RINGS.findIndex(r=>r.includes(a))-HEX_RINGS.findIndex(r=>r.includes(b)));
   for(const from of tokens){if(board[from]!==this.wild)continue;const ring=HEX_RINGS.findIndex(r=>r.includes(from));
    if(ring===0){board[from]=this.pick(rng);bank.multi++;this.frame(frames,board,'collect','중심이 WILD 흡수 · ×'+bank.multi,{...options(),cells:[from,24],moves:[{from,to:24,symbol:this.wild!}]});}
    else{const targets=hexNeighbors(from).filter(c=>HEX_RINGS[ring-1].includes(c)&&board[c]!==this.wild),to=targets[0];if(to!==undefined){const other=board[to];board[to]=this.wild!;board[from]=other;this.frame(frames,board,'move','WILD 한 궤도 안쪽으로',{...options(),moves:[{from,to,symbol:this.wild!},{from:to,to:from,symbol:other}]});}}
   }
   HEX_RINGS.forEach((ring,i)=>{if(bank.spots[i]!==0)return;const symbol=this.id(randomIndex(rng,6)),cells=ring.filter(c=>board[c]!==this.wild);cells.forEach(c=>board[c]=symbol);this.frame(frames,board,'transform','Spot·Zone 정렬 · 링 변환',{...options(),cells});});if(spent>=bet*this.maxWin)this.frame(frames,board,'state','최대 지급 한도 도달',options());
  }
  for(const ring of HEX_RINGS)if(board[ring[0]]===this.bonusSymbol)bonus+=5;
  if(bonus)this.frame(frames,board,'state','Zone 신호 · 무료 +'+bonus,options());return{round:this.round(bet,frames),bonus};
 }
 private freeRounds(initial:number,bet:number,rng:()=>number,bank:{multi:number;spots:number[]}){
  const rounds:SpinResult[]=[];let left=initial,awarded=left;
  while(left>0){left--;const next=this.roll(this.phaseDraw(rng,true),bet,rng,bank,true),extra=Math.min(next.bonus,30-awarded);awarded+=extra;left+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return rounds;
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const bank={multi:1,spots:[1,2,3]},base=this.roll(this.draw(rng),bet,rng,bank,false);if(!base.bonus)return this.finish([base.round]);return this.finish([base.round,...this.freeRounds(base.bonus,bet,rng,bank)],{freeSpinsAwarded:base.bonus});}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // The explicit bought feature starts fresh:5free, centre x1 and spots1/2/3.
  // Natural entry still carries its actually accumulated multiplier/spots.
  const intro=this.draw(rng).map((id,c)=>HEX_CELLS.includes(c)?id:this.id('void'));intro[24]=this.wild!;
  const frames:TumbleFrame[]=[];this.frame(frames,intro,'state','독립 구매 · 궤도 무료5회 · 중심 ×1',{tiles:HEX_TILES,badges:{24:'×1'},marks:HEX_RINGS.map(r=>r[0]),stationary:[24]});
  const trigger=this.round(bet,frames),rounds=this.freeRounds(5,bet,rng,{multi:1,spots:[1,2,3]});return {...this.finish(rounds,{freeSpinsAwarded:5,bonusTriggerRound:trigger}),rounds};
 }
}
