import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {WOLF_LINES} from './WolfRules';
import {awardLines,SOCIAL_2230_PAYS,packRounds,socialPresentation} from './Social2230Rules';
import {drawReelBoard} from './ReelScatter';
/** Local adaptations of published social-slot features. Each engine owns its
 * state transitions; lobby exposure is gated by individual art and playback QA. */
export type GapKind='mask'|'spark'|'storm'|'express'|'fuse'|'basket'|'lock';
export interface GapCollection {before:number;after:number;items:{cell:number;value:number}[];}
export interface GapWheel {tier:number;offset:number;pointer:number;wedge:number;advance:boolean;}
export interface GapFrame {collection?:GapCollection;region?:number[];path?:number[];wheel?:GapWheel;charged?:number[];rotation?:number;caption:string;board:string[];cells:number[];values:number[];wins:Win[];}
export interface GapPlayback {kind:GapKind;frames:GapFrame[];reelSpin:boolean;}
export const GAP_PAYOUT_FACTORS:Record<GapKind,number>={mask:1,spark:1,storm:1,express:1,fuse:1,basket:1,lock:1};
const sum=(wins:Win[])=>wins.reduce((n,w)=>n+w.amount,0);
export const gapCellsOf=(board:string[],symbol:string)=>board.flatMap((s,i)=>s===symbol?[i]:[]);
export const gapInteger=(rng:()=>number,n:number)=>{const r=rng();if(!Number.isFinite(r)||r<0||r>=1)throw Error('Invalid random value');return Math.floor(r*n);};
export function gapRng(seed:number){return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
export const LOCK_LINES=[[0,1,2],[3,4,5],[6,7,8],[0,4,8],[6,4,2],[0,4,2],[6,4,8],[3,1,5],[3,7,5]];
export abstract class GapSlot extends SlotMain {
 readonly columns:number=5;readonly rows=3;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;readonly hasBonus=true;
 abstract readonly kind:GapKind;abstract readonly config:SlotConfig;
 readonly paylines:number[][]=WOLF_LINES;
 get linePays(){return SOCIAL_2230_PAYS.map(row=>(this.columns===3?[row[0]]:row).map(value=>value*GAP_PAYOUT_FACTORS[this.kind]/(this.columns===3?3:1)));}
 get presentation(){return socialPresentation(this.config.title+' 전용 피처',this.config.tag);}
 get bonusSymbol(){return this.id('scatter');}
 get bonusCalibrationKey(){return this.config.id+':gap-v1';}
 protected id(n:string|number){return this.config.id+'-'+n;}
 protected makeConfig(id:string,title:string,tag:string,names:string[],description:string,weights?:number[]):SlotConfig{return{id,title,subtitle:tag,tag,color:'#263140',accent:'#e7c87d',description,symbols:names.map((name,n)=>({id:id+'-'+(n===8?'wild':n===9?'scatter':n),name,color:'#e7c87d',weight:(weights||[5,6,7,8,10,12,14,16,2,3])[n],payout:n<8?SOCIAL_2230_PAYS[n][2]*GAP_PAYOUT_FACTORS[this.kind]:0}))};}
 protected board(rng:()=>number){return drawReelBoard(this.columns,3,this.config.symbols,this.bonusSymbol,rng);}
 evaluate(board:string[],bet:number):SpinResult{
  if(!this.bets.includes(bet)||board.length!==this.columns*3||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid draft spin');
  const wins=this.columns===5?awardLines(this.config,board,bet,this.linePays):LOCK_LINES.flatMap((cells,line)=>{let best:Win|undefined;for(let n=0;n<8;n++)if(cells.every(c=>board[c]===this.id(n)||board[c]===this.id('wild'))){const amount=Math.round(bet*this.linePays[n][0]);if(!best||amount>best.amount)best={line,symbol:this.id(n),amount,cells:[...cells]};}return best?[best]:[];});
  return{board:[...board],bet,wins,payout:sum(wins),presentation:this.presentation};
 }
 protected frame(board:string[],caption:string,cells:number[]=[],values:number[]=[],wins:Win[]=[]):GapFrame{return{board:[...board],caption,cells:[...cells],values:[...values],wins};}
 protected round(bet:number,frames:GapFrame[],reelSpin=true):SpinResult{const wins=frames.flatMap(f=>f.wins);return{bet,board:[...frames[frames.length-1].board],openingBoard:[...frames[0].board],wins,payout:sum(wins),gapFeature:{kind:this.kind,frames,reelSpin},presentation:this.presentation};}
 protected prize(bet:number,multiplier:number,cells:number[],symbol='wild'):Win{return{line:-1,symbol:this.id(symbol),cells:[...cells],amount:Math.round(bet*multiplier*GAP_PAYOUT_FACTORS[this.kind]),multiplier:multiplier*GAP_PAYOUT_FACTORS[this.kind]};}
 protected finish(rounds:SpinResult[],extra:Partial<SpinResult>={}):SpinResult{
  let budget=rounds[0].bet*this.maxWin;for(const r of rounds){for(const w of r.wins){w.amount=Math.min(budget,w.amount);budget-=w.amount;}r.payout=sum(r.wins);}
  return rounds.length===1?{...rounds[0],...extra}:packRounds(rounds,{featureName:this.config.title,presentation:this.presentation,featureOnly:true,...extra});
 }
 abstract play(board:string[],bet:number,rng:()=>number):SpinResult;
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.play(this.board(rng),bet,rng);}
 demoSpin(bet:number){return this.find(bet,false);}bonusDemoSpin(bet:number){return this.find(bet,true);}
 private find(bet:number,bonus:boolean){const rng=gapRng(20260928);for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.payout>0)return r;}throw Error('Natural draft outcome unavailable');}
 protected purchaseSource():GapSlot{return this;}
 prepareBonusPurchase(bet:number,rng:()=>number){const source=this.purchaseSource();for(let n=0;n<100000;n++){const r=source.spin(bet,rng);if(!r.rounds)continue;const trigger=r.rounds[0];return packRounds(r.rounds.slice(1),{featureOnly:r.featureOnly,freeSpinsAwarded:r.freeSpinsAwarded,featureName:r.featureName,presentation:this.presentation,bonusTriggerRound:{bet,board:[...trigger.board],wins:[],payout:0}});}throw Error('Conditional bonus unavailable');}
}
