import {RabbitBingoSlot} from './RabbitBingoSlot';import {Geometry,expansionCells as cells} from './ExpansionCore';import {SpinResult} from './SlotMain';import {rabbitNativeBoard,rabbitUniform} from './RabbitNativeMath';
/** Same packed wager-specific bingo, overlaps, doubles and ten free rounds.
 * Purchases use a native qualifying gate law instead of a fixed trigger. */
export class RabbitNativeSlot extends RabbitBingoSlot {
 private nativeFree=false;
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(g.columns!==5||g.rows!==5)throw Error('Invalid Rabbit geometry');return rabbitNativeBoard(this.config.id,bet,rng,this.nativeFree);}
 play(board:string[],bet:number,rng:()=>number){const input=rng;rng=()=>rabbitUniform(input);const values=this.decode(this.state(bet,[0])),base=(this as any).bingoRound(board,bet,rng,values) as SpinResult,gates=cells(board,this.id('scatter'));if(gates.length<3)return this.progressResult(this.finish([base]),bet,this.encode(values));
  base.expansionFeature!.frames.push(this.frame(board,'trigger','황금 알 3개 · 무료 10회',gates,{panel:(this as any).panel(values,bet)}));const rounds=[base];this.nativeFree=true;
  try{for(let left=9;left>=0;left--){const r=(this as any).bingoRound(this.draw(bet,rng),bet,rng,values) as SpinResult;r.freeSpinsRemaining=left;rounds.push(r);}return this.progressResult(this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false}),bet,this.encode(values));}finally{this.nativeFree=false;}
 }
 prepareBonusPurchase(bet:number,rng:()=>number){const input=rng;rng=()=>rabbitUniform(input);const board=rabbitNativeBoard(this.config.id,bet,rng,false,true),values=Array(25).fill(0),gates=cells(board,this.id('scatter')),base=this.round(bet,[this.frame(board,'reels','새 빙고판 · 황금 알 착지',[],{panel:(this as any).panel(values,bet)}),this.frame(board,'trigger','새 빙고판 · 독립 무료 10회',gates,{panel:(this as any).panel(values,bet)})]),rounds=[base];this.nativeFree=true;
  try{for(let left=9;left>=0;left--){const r=(this as any).bingoRound(this.draw(bet,rng),bet,rng,values) as SpinResult;r.freeSpinsRemaining=left;rounds.push(r);}return this.purchaseFromResult(this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false}));}finally{this.nativeFree=false;}
 }
}
