export function peakOrdinary(high:number,rng:()=>number){let value=peakUniform(rng)*(73+5*high);const weights=[5*high,6,7,8,10,12,14,16];for(let i=0;i<8;i++)if((value-=weights[i])<0)return String(i);return '7';}
