import {gapInteger} from './GapCore';
export type SparkInput={colored:number;blueFraction:number;jewel:number;wild:number;gate:number;high:number};
// Fixed native symbol/reel distributions. Inputs affect draws, never payouts.
const BASE:Omit<SparkInput,"high">={"colored": 0.09181663430371514, "blueFraction": 0.4, "jewel": 0.005, "wild": 0.005, "gate": 0.002};
const FREE:Omit<SparkInput,"high">={"colored": 0.12, "blueFraction": 0.4, "jewel": 0.02, "wild": 0.005, "gate": 0.002};
const HIGH:Record<number,[number,number]>={"20":[1.953293895332429,12.476914365160546],"30":[1.953293895332429,12.476914365160546],"40":[1.953293895332429,12.476914365160546],"50":[1.953293895332429,12.476914365160546],"70":[1.953293895332429,12.476914365160546],"100":[1.953293895332429,12.476914365160546],"150":[1.953293895332429,12.476914365160546],"200":[1.953293895332429,12.476914365160546],"250":[1.953293895332429,12.476914365160546],"300":[1.953293895332429,12.476914365160546],"350":[1.953293895332429,12.476914365160546],"400":[1.953293895332429,12.476914365160546],"450":[1.953293895332429,12.476914365160546],"500":[1.953293895332429,12.476914365160546],"600":[1.953293895332429,12.476914365160546],"700":[1.953293895332429,12.476914365160546],"800":[1.953293895332429,12.476914365160546],"900":[1.953293895332429,12.476914365160546],"1000":[1.953293895332429,12.476914365160546],"2000":[1.953293895332429,12.476914365160546],"3000":[1.953293895332429,12.476914365160546],"4000":[1.953293895332429,12.476914365160546],"5000":[1.953293895332429,12.476914365160546],"6000":[1.953293895332429,12.476914365160546],"7000":[1.953293895332429,12.476914365160546],"8000":[1.953293895332429,12.476914365160546],"9000":[1.953293895332429,12.476914365160546],"10000":[1.953293895332429,12.476914365160546]};
export function sparkInput(bet:number,free=false):SparkInput{const h=HIGH[bet];if(!h)throw Error('Invalid spark wager');return{...(free?FREE:BASE),high:h[free?1:0]};}
export function sparkInputProbabilities(m:SparkInput){const rest=1-m.colored-m.jewel-m.wild,w=[8*m.high,10,12,14,16],sum=w.reduce((s,v)=>s+v,0);return[m.colored*(1-m.blueFraction),m.colored*m.blueFraction,m.jewel,...w.map(v=>rest*v/sum),m.wild];}
function draw(p:number[],rng:()=>number){let r=rng();if(!Number.isFinite(r)||r<0||r>=1)throw Error('Invalid spark RNG');for(let i=0;i<p.length;i++){r-=p[i];if(r<0)return i;}return p.length-1;}
function symbol(id:string,n:number){return id+'-'+(n===8?'wild':n===9?'scatter':n);}
export function sparkInputBoard(id:string,m:SparkInput,rng:()=>number){const b=Array<string>(15),p=sparkInputProbabilities(m);for(let col=0;col<5;col++){const scatter=rng()<m.gate?gapInteger(rng,3):-1;for(let row=0;row<3;row++)b[row*5+col]=symbol(id,row===scatter?9:draw(p,rng));}return b;}
const f=[1,1,2,6];
export function sparkInputColumnLaw(m:SparkInput){const rows:{g:number;b:number;j:number;s:number;p:number}[]=[],p=[m.colored*(1-m.blueFraction),m.colored*m.blueFraction,m.jewel,1-m.colored-m.jewel];for(let s=0;s<=1;s++){const n=3-s;for(let g=0;g<=n;g++)for(let b=0;b<=n-g;b++)for(let j=0;j<=n-g-b;j++){const o=n-g-b-j;rows.push({g,b,j,s,p:(s?m.gate:1-m.gate)*f[n]/f[g]/f[b]/f[j]/f[o]*p[0]**g*p[1]**b*p[2]**j*p[3]**o});}}return rows;}
type EntryModel={law:ReturnType<typeof sparkInputColumnLaw>;tail:(col:number,n:number,active:boolean)=>number};
const models=new Map<number,EntryModel>();
export function sparkEntryModel(bet:number){let model=models.get(bet);if(model)return model;const law=sparkInputColumnLaw(sparkInput(bet)),memo=new Map<number,number>();const tail=(col:number,n:number,active:boolean):number=>{if(!active||col===5)return n>=5?1:0;const k=col*32+n,old=memo.get(k);if(old!==undefined)return old;let p=0;for(const row of law){const occupied=row.g+row.b>0;p+=row.p*tail(col+1,n+(occupied?row.g+row.b:0),occupied);}memo.set(k,p);return p;};model={law,tail};models.set(bet,model);return model;}
/** Exact native board law conditional only on the consecutive-color gate.
 * Column counts and uniform positions include every qualifying topology.
 * No evaluator, payout, prior loss or accepted/rejected result is consulted. */
export function sparkPurchaseBoard(id:string,bet:number,rng:()=>number){const m=sparkInput(bet),{law,tail}=sparkEntryModel(bet),b=Array<string>(15),p=sparkInputProbabilities(m),other=p.slice(3),sum=other.reduce((s,v)=>s+v,0),op=other.map(v=>v/sum);let n=0,active=true;for(let col=0;col<5;col++){const weights=law.map(row=>{const a=active&&row.g+row.b>0;return row.p*tail(col+1,n+(a?row.g+row.b:0),a);}),total=weights.reduce((s,v)=>s+v,0);if(!(total>0))throw Error('Spark conditional gate has no native support');const row=law[draw(weights.map(v=>v/total),rng)],items=[...Array(row.g).fill(0),...Array(row.b).fill(1),...Array(row.j).fill(2),...Array(row.s).fill(9)];while(items.length<3)items.push(3+draw(op,rng));for(let i=2;i>0;i--){const j=gapInteger(rng,i+1);[items[i],items[j]]=[items[j],items[i]];}for(let rowIndex=0;rowIndex<3;rowIndex++)b[rowIndex*5+col]=symbol(id,items[rowIndex]);active=active&&row.g+row.b>0;if(active)n+=row.g+row.b;}return b;}
