import {ExpansionSlot,randomIndex as ri} from './ExpansionCore';
import {twinNativeBoard} from './TwinNativeMath';
export class TwinNativeSlot extends ExpansionSlot {
 draw(bet:number,rng:()=>number){return twinNativeBoard(this.config.id,bet,rng);}
 play(board:string[],bet:number,rng:()=>number){
  let count=2;while(count<5&&rng()<.15)count++;const start=ri(rng,6-count),linked=Array.from({length:count},(_,i)=>start+i),after=[...board];
  for(const col of linked)for(let row=0;row<3;row++)after[row*5+col]=board[row*5+start];
  return this.finish([this.round(bet,[this.frame(after,'reels','두 릴 동기화'+(count>2?' · 옆 릴로 연결 확장':''),[],{linkReels:linked}),{...this.hit(after,bet,'243 WAYS · 동기화 결과 당첨'),linkReels:linked}])]);
 }
}

