/** Same native highest line award; skip symbols that cannot match the first non-WILD. */
export function jewelLineAwards(board:string[],bet:number,lines:readonly (readonly number[])[]=WOLF_LINES):Win[]{
 const ids=Array.from({length:8},(_,n)=>JEWEL_ID+'-'+n),wild=JEWEL_ID+'-wild',wins:Win[]=[];
 for(let index=0;index<lines.length;index++){
  const line=lines[index];let prefix=0;while(prefix<line.length&&board[line[prefix]]===wild)prefix++;
  const regular=prefix<line.length?ids.indexOf(board[line[prefix]]):-1;
  const candidates=prefix>=3?(regular>0?[0,regular]:[0]):regular>=0?[regular]:[];let best:Win|undefined;
  for(const n of candidates){const cells:number[]=[];for(const c of line){if(board[c]!==ids[n]&&board[c]!==wild)break;cells.push(c);}if(cells.length<3)continue;const multiplier=JEWEL_PAYS[n][cells.length-3],amount=Math.round(bet*multiplier);if(!best||amount>best.amount)best={line:index,symbol:ids[n],cells,amount,multiplier};}
  if(best)wins.push(best);
 }
 return wins;
}
export interface JewelEvent {cell:number;jewel:number;before:number[];after:number[];matched:boolean;award?:Win;}
