import {cloneSlotData} from './SlotMain';
import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {LOBSTER_MODELS} from './LobsterMath';
// Immutable input-only gate law shared by fresh independent purchase instances.
const conditionalMaskCache=new Map<string,{mask:number;cumulative:number}[]>();
/** Local strips and awards; the operator's 40-line/60-credit feature structure. */
export class LobsterChoiceSlot extends ExpansionSlot {
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-free';}
 private get inputs(){return LOBSTER_MODELS[this.config.id as keyof typeof LOBSTER_MODELS];}
 private harborPool(col:number,free=false){return this.config.symbols.filter(s=>s.weight>0&&(col<3||s.id!==this.id('scatter'))).map(s=>({...s,weight:s.id===this.id('wild')?(free?this.inputs.freeWild:2):s.id===this.id('scatter')?(free?this.inputs.freeScatter:this.inputs.baseScatter):s.id===this.id(0)&&!free?s.weight*this.inputs.baseHigh:s.weight}));}
 private harborDraw(bet:number,rng:()=>number,free=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');return Array.from({length:20},(_,c)=>{
   const pool=this.harborPool(c%5,free);let roll=rng()*pool.reduce((n,s)=>n+s.weight,0),id=pool[pool.length-1].id;for(const s of pool){roll-=s.weight;if(roll<0){id=s.id;break;}}return id;
  });
 }
 draw(bet:number,rng:()=>number){return this.harborDraw(bet,rng);}
 protected gatePaths(){return this.paylines.map(line=>line.slice(0,3));}
 private gates(b:string[]){return this.gatePaths().filter(path=>path.every(c=>b[c]===this.id('scatter')));}
 private get pathLabel(){return this.spec.mode==='ways'?'보너스 WAYS':'보너스 라인';}
 private credits(b:string[],bet:number,value:number,lineCount:number,caption:string){return this.prize(b,bet,value/60*lineCount,[],caption);}
 private entryAward(b:string[],bet:number,entry:number,lines:number,mode:'free'|'buoy',region?:number){
  const award=this.credits(b,bet,entry,lines,'선택 진입 상금');
  award.lobsterEntry={credits:entry,lines,mode,...(region===undefined?{}:{region})};
  return this.round(bet,[award]);
 }
 private freeBonus(b:string[],bet:number,rng:()=>number,base:SpinResult,lines:number,entry:number){
  const rounds=[base,this.entryAward(b,bet,entry,lines,'free')];let left=5,awarded=5;
  while(left>0){left--;const raw=this.harborDraw(bet,rng,true),fs=[this.frame(raw,'reels','풍부한 WILD · 무료 회전'),this.hit(raw,bet,this.spec.mode==='ways'?'무료 1024 WAYS 당첨':'무료 라인 당첨',this.geometry,{awardMultiplier:lines})],added=this.gates(raw).length?Math.min(5,240-awarded):0;if(added){left+=added;awarded+=added;fs.push(this.frame(raw,'trigger',this.pathLabel+' · 무료 +5회',cells(raw,this.id('scatter'))));}rounds.push(this.round(bet,fs,{freeSpinsRemaining:left,freeSpinsAdded:added||undefined}));}
  return this.finish(rounds,{freeSpinsAwarded:5,featureOnly:false});
 }
 private buoyBonus(b:string[],bet:number,rng:()=>number,base:SpinResult,lines:number,entry:number,region:number){
  const valuesTable=[10,15,20,30,50,75,100,150,250,575],topWeight=this.inputs.buoyTop[region],value=()=>{const sample=rng()*(9+topWeight);return sample<9?valuesTable[Math.floor(sample)]:575;};
  const picks=2+ri(rng,3),values:number[]=[],lobsters:number[]=[];let goldAt=-1;
  for(let i=0;i<picks;i++){const count=2+ri(rng,3);lobsters.push(count);let amount=0;for(let j=0;j<count;j++){if(goldAt<0&&rng()<.06)goldAt=i;else amount+=value();}values.push(amount);}
  const pay=this.credits(b,bet,values.reduce((a,v)=>a+v,0),lines,'부표 속 랍스터 상금');pay.action='reveal';pay.lobsterPick={kind:'buoy',values,goldAt,lobsters,cardCount:6,label:['브라질','호주','메인'][region]+' · 부표 '+picks+'개 선택'};
  const prefix=[base,this.entryAward(b,bet,entry,lines,'buoy',region),this.round(bet,[pay])];
  if(goldAt<0){const done=this.finish(prefix,{featureOnly:true});return [done,done,done];}
  prefix.push(this.round(bet,[this.frame(b,'trigger','황금 랍스터 · 지역 후속 보너스',[],{actor:{symbol:this.id('wild'),cells:[]}})]));
  if(region===0){const stop=ri(rng,6),multipliers=Array.from({length:stop},()=>1+ri(rng,5)),factor=multipliers[multipliers.length-1]||1,award=this.credits(b,bet,200*factor,lines,'문어 상자 · 마지막 배수 상금');award.action='reveal';award.lobsterPick={kind:'octopus',values:[...multipliers,0],goldAt:stop,cardCount:6,label:'문어 상자 · 황금 랍스터 전 마지막 배수'};return [this.finish([...prefix,this.round(bet,[award])],{featureOnly:true})];}
  if(region===1){const stop=ri(rng,6),values=[...Array.from({length:stop},()=>[50,75,100,150,200,250][ri(rng,6)]),200],award=this.credits(b,bet,values.reduce((a,v)=>a+v,0),lines,'캥거루 · 선택 상금 합계');award.action='reveal';award.lobsterPick={kind:'kangaroo',values,goldAt:stop,cardCount:6,label:'캥거루 · 황금 랍스터까지 수집'};return [this.finish([...prefix,this.round(bet,[award])],{featureOnly:true})];}
  const offers=Array.from({length:3},()=>[160,250,400,625][ri(rng,4)]),variants:SpinResult[]=[];
  for(let end=0;end<3;end++){
   const stop=offers.indexOf(625),actual=stop>=0?Math.min(stop,end):end,award=this.credits(b,bet,offers[actual],lines,'펠리컨 · 수락한 상금'),rounds=[...prefix];
   for(let i=0;i<=actual;i++){
    const displayWin=this.credits(b,bet,offers[i],lines,'펠리컨 제안').wins[0],frame=this.frame(b,'reveal','펠리컨 제안 '+(i+1)+'/3',[],{lobsterPick:{kind:'pelican',values:[offers[i]],goldAt:-1,cardCount:3,label:'펠리컨 '+(i+1)+'번째 선택'}});frame.lobsterPick!.offer=displayWin;
    rounds.push(this.round(bet,[frame],{lobsterOffer:{win:displayWin,acceptBranch:3+i,continueBranch:i<2?5:undefined,forced:offers[i]===625||i===2,defaultAccept:offers[i]>=(i===0?435.625:358.75)}}));
   }
   rounds.push(this.round(bet,[award]));variants.push(this.finish(rounds,{featureOnly:true}));
  }
  // Four visible entry choices; Maine sampling follows the declared stopping policy.
  const optimal=offers[0]>=435.625?0:offers[1]>=358.75?1:2;variants.forEach(v=>v.lobsterPolicyBranch=3+optimal);return variants;
 }
 play(b:string[],bet:number,rng:()=>number){
  const gates=this.gates(b),values=Array(20).fill(0),jackpots:number[]=[];
  for(let c=0;c<20;c++){if(b[c]!==this.id('scatter')&&rng()<.025)jackpots.push(c);if(c%5===2&&[1,2,3,4].some(n=>b[c]===this.id(n))&&rng()<.06)values[c]=b[c]===this.id(1)?5:rng()<.5?3:5;}
  const base=this.ordinary(b,bet,this.spec.mode==='ways'?'5×4 · 1024 WAYS + 피처':'5×4 · 40라인 + 피처',this.geometry,{values});const hit=base.expansionFeature!.frames[1];for(const win of hit.wins){
   let factor=win.cells.reduce((n,c)=>n*(values[c]||1),1);
   if(this.spec.mode==='ways'){
    const groups=Array.from({length:Math.max(...win.cells.map(c=>c%5))+1},(_,col)=>win.cells.filter(c=>c%5===col));
    const product=(weighted:boolean,wildOnly:boolean)=>groups.reduce((n,group)=>n*group.filter(c=>!wildOnly||this.isWild(b[c])).reduce((sum,c)=>sum+(weighted?(values[c]||1):1),0),1);
    const exclude=win.symbol!==this.id(0),paths=product(false,false)-(exclude?product(false,true):0),weighted=product(true,false)-(exclude?product(true,true):0);
    factor=paths?weighted/paths:1;win.amount=Math.round(bet*(win.multiplier||0)*factor);
   }else win.amount=Math.round(win.amount*factor);
   win.multiplier=(win.multiplier||0)*factor;
  }base.expansionFeature!.frames.forEach(f=>{f.values=[...values];f.jackpotCells=[...jackpots];});
  const reels=new Set(jackpots.map(c=>c%5));let longest=0;for(let c=0;c<5;c++){let count=0;for(let k=c;k<5&&reels.has(k);k++)count++;longest=Math.max(longest,count);}if(longest>=3)base.expansionFeature!.frames.push(this.credits(b,bet,[0,0,0,200,1000,10000][longest],1,'연속 릴 JACKPOT · 한 번 지급'));
  if(!gates.length)return this.finish([base]);const triggered=Array.from(new Set(gates.flatMap(line=>line.slice(0,3))));base.expansionFeature!.frames.push(this.frame(b,'trigger',gates.length+'개 '+this.pathLabel+' · 무료 또는 부표 선택',triggered));const entry=40+ri(rng,56),clone=()=>cloneSlotData(base),free=this.freeBonus(b,bet,rng,clone(),gates.length,entry),brazil=this.buoyBonus(b,bet,rng,clone(),gates.length,entry,0)[0],australia=this.buoyBonus(b,bet,rng,clone(),gates.length,entry,1)[0],maine=this.buoyBonus(b,bet,rng,clone(),gates.length,entry,2),result=this.choices('무료 회전 또는 부표 탐험',['무료 5회','브라질','호주','메인 1','메인 2','메인 3'],[free,brazil,australia,...maine]);result.featureChoices!.sampleIndices=[0,1,2,maine[0].lobsterPolicyBranch??5];return result;
 }
 private conditionalGate(bet:number,rng:()=>number){
  const key=JSON.stringify([this.config.id,this.harborPool(0).map(s=>[s.id,s.weight]),this.gatePaths()]);let masks=conditionalMaskCache.get(key);
  if(!masks){
   const pool=this.harborPool(0),total=pool.reduce((sum,s)=>sum+s.weight,0),p=this.inputs.baseScatter/total,valid:{mask:number;cumulative:number}[]=[];let cumulative=0;
   const gates=this.gatePaths().map(path=>path.reduce((mask,c)=>mask|(1<<(Math.floor(c/5)*3+c%5)),0));
   for(let mask=0;mask<4096;mask++){if(!gates.some(g=>(mask&g)===g))continue;let count=0;for(let bits=mask;bits;bits&=bits-1)count++;cumulative+=Math.pow(p,count)*Math.pow(1-p,12-count);valid.push({mask,cumulative});}masks=valid;conditionalMaskCache.set(key,masks);
  }
  const roll=rng()*masks[masks.length-1].cumulative,mask=masks.find(v=>v.cumulative>roll)?.mask??masks[masks.length-1].mask;
  return Array.from({length:20},(_,c)=>{if(c%5<3&&mask&(1<<(Math.floor(c/5)*3+c%5)))return this.id('scatter');const pool=this.harborPool(c%5).filter(s=>s.id!==this.id('scatter'));let sample=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){sample-=s.weight;if(sample<0)return s.id;}return pool[pool.length-1].id;});
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  // Exact independent-cell distribution conditioned on at least one bonus line.
  const b=this.conditionalGate(bet,rng),g=this.gates(b),base=this.ordinary(b,bet);base.expansionFeature!.frames.push(this.frame(b,'trigger',g.length+'개 '+this.pathLabel+' · 무료 5회 구매',Array.from(new Set(g.flatMap(line=>line.slice(0,3))))));return this.purchaseFromResult(this.freeBonus(b,bet,rng,base,g.length,40+ri(rng,56)));
 }
}

export class LobsterWaysSlot extends LobsterChoiceSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);this.config.description='5×4 · 1,024 WAYS · 왼쪽 3릴 이상 연결\n처음 3릴에 배가 각각 있으면 모든 배 조합 수만큼 보너스 배수를 적용합니다. 고정 라인이 아닙니다.\n무료 5회 또는 부표 탐험 선택. 무료 중 배 조합 재발동 +5회, 최대 240회.\n부표 2–4개 → 황금 랍스터 → 문어 마지막 배수 / 캥거루 상금 수집 / 펠리컨 수락 또는 계속.\n3번째 릴 배수는 해당 심볼 조합에만 적용합니다. 연속 3–5릴 JACKPOT은 한 번 지급합니다.\n구매는 진행과 별개인 독립 무료 5회입니다. 세부 확률·상금·보너스 WAYS 배수는 로컬 각색입니다.';}
 protected gatePaths(){return Array.from({length:64},(_,i)=>[(i%4)*5,(Math.floor(i/4)%4)*5+1,Math.floor(i/16)*5+2]);}
}
