import {STICKY_RAIL_INPUTS as M} from './StickyRailNativeMath';
function uniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid sticky rail RNG');return u;}
function binomial(n:number,k:number,p:number){let c=1;for(let i=1;i<=k;i++)c=c*(n-i+1)/i;return c*p**k*(1-p)**(n-k);}
/** Every reel independently has one gate with a uniform native row. Purchase
 * samples this exact declared law conditioned only on three-plus gate reels. */
export function stickyRailBoard(id:string,bet:number,rng:()=>number,free=false,purchase=false){
 const table:Record<number,number>=free?M.freeZeroByBet:M.baseZeroByBet,zero=table[bet];if(zero===undefined)throw Error('Invalid sticky rail bet');const q=free?M.freeGate:M.baseGate,flags=Array(6).fill(false);
 if(purchase){const mass=Array.from({length:7},(_,k)=>k<3?0:binomial(6,k,q));let roll=uniform(rng)*mass.reduce((a,b)=>a+b,0),count=6;for(let k=3;k<=6;k++){roll-=mass[k];if(roll<0){count=k;break;}}const reels=[0,1,2,3,4,5];for(let i=0;i<count;i++){const j=i+Math.floor(uniform(rng)*(6-i));[reels[i],reels[j]]=[reels[j],reels[i]];flags[reels[i]]=true;}}
 else for(let col=0;col<6;col++)flags[col]=uniform(rng)<q;
 const gates=flags.map(flag=>flag?Math.floor(uniform(rng)*4):-1),rest=[6,7,8,10,12,14,16];
 return Array.from({length:24},(_,cell)=>{let u=uniform(rng);if(Math.floor(cell/6)===gates[cell%6])return id+'-scatter';if(u<M.wild)return id+'-wild';u=(u-M.wild)/(1-M.wild);if(u<zero)return id+'-0';let roll=(u-zero)/(1-zero)*73;for(let i=0;i<rest.length;i++){roll-=rest[i];if(roll<0)return id+'-'+(i+1);}return id+'-7';});
}
