import {BALLOON_MODEL as M} from './BalloonBundleMath';
type Cell='R'|'B'|'M'|'S'|'T';
export interface BalloonColumnInput {cells:Cell[];scatters:number;alive:boolean;marked:boolean;mass:number;}
function uniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid festival uniform');return u;}
export function balloonPurchaseLaw(){
 const regular=M.baseWeights.reduce((s,w)=>s+w,0),columns=Array.from({length:5},(_,c)=>{
  const ticket=c===2?M.baseTicket:0,total=regular+8+M.baseScatter+ticket;
  const cells:{cell:Cell;mass:number}[]=[{cell:'R',mass:regular/total},{cell:'S',mass:M.baseScatter/total},...(c===4?[{cell:'B' as Cell,mass:8*.82/total},{cell:'M' as Cell,mass:8*.18/total}]:[{cell:'B' as Cell,mass:8/total}]),...(ticket?[{cell:'T' as Cell,mass:ticket/total}]:[])];
  const out:BalloonColumnInput[]=[];for(const a of cells)for(const b of cells)for(const d of cells){const values=[a.cell,b.cell,d.cell];out.push({cells:values,scatters:values.filter(v=>v==='S').length,alive:values.some(v=>v==='B'||v==='M'||v==='T'),marked:values.includes('M'),mass:a.mass*b.mass*d.mass});}return out;
 });
 const cache=new Map<string,number>();
 const suffix=(col:number,scatters:number,alive:boolean):number=>{
  const key=[col,scatters,+alive].join(':');if(cache.has(key))return cache.get(key)!;
  let p=0;for(const v of columns[col]){const s=scatters+v.scatters,a=alive&&v.alive;p+=v.mass*(col===4?Number(s>=6||(a&&v.marked)):suffix(col+1,s,a));}cache.set(key,p);return p;
 };
 const trigger=suffix(0,0,true);return {columns,suffix,trigger};
}
/** Exact native entrance distribution conditional on a free-spin input gate.
 * Every column is sampled once; no payout is calculated or rejected here. */
export function balloonConditionalInput(law:ReturnType<typeof balloonPurchaseLaw>,rng:()=>number){
 const board:string[]=Array(15),counts:number[]=Array(15).fill(0),tickets:number[]=Array(15).fill(0),scatterSpins:number[]=Array(15).fill(0),regular=M.baseWeights.reduce((s,w)=>s+w,0);let scatters=0,alive=true;
 for(let c=0;c<5;c++){
  const options=law.columns[c].map(v=>({v,mass:v.mass*(c===4?Number(scatters+v.scatters>=6||(alive&&v.alive&&v.marked)):law.suffix(c+1,scatters+v.scatters,alive&&v.alive))})).filter(v=>v.mass>0),total=options.reduce((s,o)=>s+o.mass,0);if(!(total>0))throw Error('Festival input gate unavailable');
  let roll=uniform(rng)*total,chosen=options[options.length-1].v;for(const o of options){roll-=o.mass;if(roll<0){chosen=o.v;break;}}scatters+=chosen.scatters;alive&&=chosen.alive;
  chosen.cells.forEach((cell,row)=>{const i=row*5+c;
   if(cell==='R'){let roll=uniform(rng)*regular,n=M.baseWeights.length-1;for(let k=0;k<M.baseWeights.length;k++){roll-=M.baseWeights[k];if(roll<0){n=k;break;}}board[i]=String(n);}
   else if(cell==='T'){board[i]='wild';tickets[i]=2+Math.floor(uniform(rng)*4);}
   else if(cell==='S'){board[i]='scatter';scatterSpins[i]=1+Math.floor(uniform(rng)*3);}
   else {board[i]='balloon';counts[i]=1+Math.floor(uniform(rng)*3);if(cell==='M')scatterSpins[i]=1;}
  });
 }
 return{board,counts,tickets,scatterSpins};
}
