/** Bound optional audio work, including Safari's callback-only decoder failures. */
export const WEB_AUDIO_TIMEOUT_MS=10000;

export async function fetchAudioData(url:string,timeoutMs=WEB_AUDIO_TIMEOUT_MS):Promise<ArrayBuffer>{
 const controller=new AbortController();let timer:ReturnType<typeof setTimeout>|undefined;
 try{
  return await Promise.race([
   fetch(url,{signal:controller.signal}).then(response=>{if(!response.ok)throw Error('Audio HTTP '+response.status);return response.arrayBuffer();}),
   new Promise<never>((_,reject)=>{timer=setTimeout(()=>{reject(Error('Audio download timed out'));controller.abort();},timeoutMs);}),
  ]);
 }finally{clearTimeout(timer);}
}

export async function decodeAudioData(context:AudioContext,raw:ArrayBuffer,timeoutMs=WEB_AUDIO_TIMEOUT_MS):Promise<AudioBuffer>{
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{
  return await new Promise<AudioBuffer>((resolve,reject)=>{
   timer=setTimeout(()=>reject(Error('Audio decode timed out')),timeoutMs);
   // Older WebKit only invokes callbacks; newer engines also return a Promise.
   const pending=context.decodeAudioData(raw,resolve,reject);
   pending?.then(resolve,reject);
  });
 }finally{clearTimeout(timer);}
}
