import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex as ri}from'./ExpansionCore';
import {SpinResult}from'./SlotMain';
import{BUILDER_INPUTS,builderUniform}from'./BuilderNativeMath';
const builderPurchaseConditions=new Map<string,{pools:{id:string;weight:number}[][];probability:(cell:number,h:number,w:number)=>number}>();
// Pure categorical laws, shared independently of player/house state. Every
// weight participates in the key so research and wager changes cannot reuse
// a law from another source input. Sampling order and RNG consumption stay exact.
const builderPools=new Map<string,{id:string;weight:number}[]>();
export class BuilderNativeSlot extends ExpansionSlot {
 get bonusTriggerCount(){return 6;}
 private inputKind='free';
 private nativePool(cell:number,bet:number,free=false){
  const M=BUILDER_INPUTS,hat=free?M.freeHat[this.inputKind]:M.hat,wheel=free?0:M.wheel,wild=cell%5>0&&cell%5<4?M.wild:0,high=free?M.freeHigh:M.highByBet[bet],rest=1-hat-wheel-wild;
  if(!Number.isFinite(high))throw Error('Invalid Builder wager');
  const key=[this.config.id,hat,wheel,wild,high].join('/'),known=builderPools.get(key);if(known)return known;
  const pool=[{id:this.id('scatter'),weight:hat},{id:this.id('wheel'),weight:wheel},{id:this.id('wild'),weight:wild},{id:this.id(0),weight:rest*high},...Array.from({length:7},(_,n)=>({id:this.id(n+1),weight:rest*(1-high)/7}))];builderPools.set(key,pool);return pool;
 }
 private constructionDraw(bet:number,rng:()=>number,free=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');return Array.from({length:15},(_,cell)=>{const pool=this.nativePool(cell,bet,free);let u=builderUniform(rng),id=pool[pool.length-1].id;for(const item of pool){u-=item.weight;if(u<0){id=item.id;break;}}return id;});
 }
 draw(bet:number,rng:()=>number){return this.constructionDraw(bet,rng);}
 private constructionBonus(b:string[],bet:number,rng:()=>number,kind:'free'|'saw'|'mega'|'mansion'){
  const savedKind=this.inputKind;this.inputKind=kind;try{
  const levels=Array(15).fill(0),rounds:SpinResult[]=[],start:ExpansionFrame[]=[],hats=cells(b,this.id('scatter'));let last=[...b];
  const step=(phase:NonNullable<ExpansionFrame['builderHouse']>['phase'],extra:Partial<NonNullable<ExpansionFrame['builderHouse']>>={})=>({mode:kind,phase,...extra});
  // Overflow prioritizes brick upgrades, then wood upgrades, then empty positions.
  const land=(cell:number,board:string[],frames:ExpansionFrame[])=>{
   let target=cell;const beforeLevels=[...levels];
   if(levels[cell]===3){const tier=kind==='mansion'?0:levels.includes(2)?2:levels.includes(1)?1:0,available=levels.flatMap((v,c)=>v===tier?[c]:[]);
    if(!available.length){frames.push({...this.prize(board,bet,10,[cell],'최고 등급 만석 · 추가 상금'),houseLevels:[...levels],builderHouse:step('overflow')});return;}
    target=available[ri(rng,available.length)];
   }
   levels[target]=kind==='mansion'?3:Math.min(3,levels[target]+1);
   frames.push(this.frame(board,'effect',target===cell?'안전모 → 집 프레임 성장':'최고 프레임 → 다른 집 성장',Array.from(new Set([cell,target])),{houseLevels:[...levels],builderHouse:step('grow',{beforeLevels,source:cell,target})}));
  };
  if(kind==='free')hats.forEach(c=>levels[c]=1);
  if(kind==='saw')for(const c of cells(b,this.id('wheel')).sort((a,z)=>z%5-a%5)){
   for(let col=c%5;col<5;col++){const target=Math.floor(c/5)*5+col;land(target,b,start);const landed=start[start.length-1];landed.caption='톱이 오른쪽으로 이동 · 지나간 집 성장';landed.actor={symbol:this.id(5),cells:[target],travel:{from:col===c%5?c:target-1,to:target}};}
  }
  if(kind==='mega'){
   const shape=[[2,2],[3,3],[5,3]][ri(rng,3)],left=ri(rng,6-shape[0]),top=ri(rng,4-shape[1]),covered=Array.from({length:shape[0]*shape[1]},(_,i)=>(top+Math.floor(i/shape[0]))*5+left+i%shape[0]);covered.forEach(c=>levels[c]=1);
   start.push(this.frame(b,'effect','대형 안전모 '+shape[0]+'×'+shape[1]+' · 전체 영역 프레임',covered,{houseLevels:[...levels],builderHouse:step('grow',{beforeLevels:Array(15).fill(0)}),actor:{symbol:this.id('mega'),cells:covered}}));
  }
  start.unshift(this.frame(b,'state',({free:'집 건설',saw:'톱 이동',mega:'대형 안전모',mansion:'저택'}[kind])+' · 무료 6회',[],{houseLevels:kind==='free'?[...levels]:Array(15).fill(0),builderHouse:step('prepare',{remaining:6})}));rounds.push(this.round(bet,start));
  let remaining=6,awarded=6,spin=0;
  while(remaining>0){remaining--;spin++;last=this.constructionDraw(bet,rng,true);const landed=cells(last,this.id('scatter')),fs:ExpansionFrame[]=[this.frame(last,'reels','고정 집 프레임 · 무료 회전',[],{houseLevels:[...levels],builderHouse:step('spin',{spin,remaining})})];
   if(landed.length){fs.push(this.frame(last,'trigger','안전모 착지 위치',landed,{houseLevels:[...levels],builderHouse:step('land',{spin,remaining})}));const growth:ExpansionFrame[]=[];landed.forEach(c=>land(c,last,growth));fs.push(...growth);}
   fs.push({...this.hit(last,bet,'243 WAYS · 집 건설 무료 당첨'),houseLevels:[...levels],builderHouse:step('spin',{spin,remaining})});const added=landed.length>=3&&awarded<120?1:0;
   if(added){remaining++;awarded++;fs.push(this.frame(last,'trigger','안전모 3개 · 무료 +1회',landed,{houseLevels:[...levels],builderHouse:step('retrigger',{spin,remaining})}));}
   rounds.push(this.round(bet,fs,{freeSpinsRemaining:remaining,freeSpinsAdded:added||undefined}));
  }
  const occupied=levels.flatMap((v,c)=>v?[c]:[]),shown=last.map((id,c)=>levels[c]?this.id(levels[c]===3?4:levels[c]):id),fs:ExpansionFrame[]=[this.frame(shown,'reveal','완성 집 공개 · 마지막 한 번 지급',occupied,{houseLevels:[...levels],builderHouse:step('reveal')}),this.frame(shown,'effect','늑대 바람 · 집 상금 확인',occupied,{houseLevels:[...levels],builderHouse:step('wind'),actor:{symbol:this.id('wild'),cells:occupied}})];
  for(let row=0;row<3;row++){const group=occupied.filter(c=>Math.floor(c/5)===row);if(!group.length)continue;
   const wins=group.flatMap(c=>{const pool=levels[c]===1?[1,1,2,3,5]:levels[c]===2?[2,3,5,10,20,40]:[5,10,20,40,100,500];return this.prize(shown,bet,pool[ri(rng,pool.length)],[c],'완성 집 상금').wins;});
   fs.push(this.frame(shown,'win','완성 집 상금 · 한 번 지급',group,{wins,houseLevels:[...levels],builderHouse:step('pay')}));group.forEach(c=>shown[c]='');fs.push(this.frame(shown,'remove','상금 수집 · 집 철거',group,{houseLevels:levels.map((v,c)=>shown[c]?v:0),builderHouse:step('clear')}));
  }
  rounds.push(this.round(bet,fs));return {rounds,awarded:6};}finally{this.inputKind=savedKind;}
 }
 play(b:string[],bet:number,rng:()=>number){
  const hats=cells(b,this.id('scatter')),wheels=cells(b,this.id('wheel')),base=this.ordinary(b,bet,'243 WAYS · 건축가');if(hats.length<6&&wheels.length<3)return this.finish([base]);
  if(hats.length>=6&&wheels.length<3)base.expansionFeature!.frames.push(this.frame(b,'trigger','안전모 6개 · 무료 6회',hats));
  const rounds=[base];let awarded=0;
  if(wheels.length>=3){
   const selected=ri(rng,10),wedge=selected<3?0:selected<6?1:selected<8?2:selected===8?3:ri(rng,4)+3,labels=['톱 이동','저택','대형 안전모','MINI','MINOR','MAJOR','GRAND'];
   base.expansionFeature!.frames.push(this.frame(b,'trigger','휠 표식 3개 · 보너스 휠',wheels));const frames=[this.frame(b,'reveal','건축 보너스 휠',wheels,{wheel:{label:'건축 보너스 휠',values:[1,1,1,2,5,25,100],selected:wedge,unit:'feature',labels,stage:'first'}})];
   if(wedge>=3)frames.push(this.prize(b,bet,[2,5,25,100][wedge-3],wheels,labels[wedge]+' 고정 상금'));rounds.push(this.round(bet,frames));
   if(wedge<3){const feature=this.constructionBonus(b,bet,rng,(['saw','mansion','mega'] as const)[wedge]);rounds.push(...feature.rounds);awarded+=feature.awarded;}
  }
  if(hats.length>=6){if(wheels.length>=3)rounds.push(this.round(bet,[this.frame(b,'trigger','안전모 6개 · 무료 6회',hats)]));const feature=this.constructionBonus(b,bet,rng,'free');rounds.push(...feature.rounds);awarded+=feature.awarded;}
  return this.finish(rounds,{featureOnly:!awarded,...(awarded?{freeSpinsAwarded:awarded}:{})});
 }
 private get purchaseConditions(){return builderPurchaseConditions;}
 private conditionalBoard(rng:()=>number,kind:'free'|'wheel',bet=100){
  const key=[this.config.id,kind,BUILDER_INPUTS.hat,BUILDER_INPUTS.wheel,BUILDER_INPUTS.wild].join('/');let condition=this.purchaseConditions.get(key);
  if(!condition){
   const pools=Array.from({length:15},(_,c)=>this.nativePool(c,100)),memo=new Map<string,number>();
   const probability=(cell:number,h:number,w:number):number=>{
    if(cell===15)return Number(kind==='free'?h>=6&&w<3:w>=3&&h<6);
    const key=cell+','+h+','+w,known=memo.get(key);if(known!==undefined)return known;
    const pool=pools[cell],total=pool.reduce((n,s)=>n+s.weight,0),sum=pool.reduce((n,s)=>n+s.weight/total*probability(cell+1,Math.min(6,h+Number(s.id===this.id('scatter'))),Math.min(3,w+Number(s.id===this.id('wheel')))),0);memo.set(key,sum);return sum;
   };condition={pools,probability};this.purchaseConditions.set(key,condition);
  }
  let h=0,w=0;const board:string[]=[];
  for(let c=0;c<15;c++){
   const pool=this.nativePool(c,bet).map(s=>({...s,conditional:s.weight*condition!.probability(c+1,Math.min(6,h+Number(s.id===this.id('scatter'))),Math.min(3,w+Number(s.id===this.id('wheel'))))})),total=pool.reduce((n,s)=>n+s.conditional,0);if(total<=0)throw Error('Builder conditional branch unreachable');
   const possible=pool.filter(s=>s.conditional>0);let roll=rng()*total,id=possible[possible.length-1].id;for(const s of pool){roll-=s.conditional;if(roll<0){id=s.id;break;}}board.push(id);h=Math.min(6,h+Number(id===this.id('scatter')));w=Math.min(3,w+Number(id===this.id('wheel')));
  }return board;
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const input=rng;rng=()=>builderUniform(input);
  return this.choices('집 건설 또는 보너스 휠',['집 건설 6회','보너스 휠'],['free','wheel'].map(kind=>this.purchaseFromResult(this.play(this.conditionalBoard(rng,kind as 'free'|'wheel',bet),bet,rng))));
 }
}
