/** Absolute time keeps the opening stable across resize, language and sound changes. */
export const POCKET_OPENING_SECONDS=6.5;
export const POCKET_INTRO_ART=[
 ['olympus','intro-art-64-v1/olympus'],
 ['raccoon','intro-art-64-v1/raccoon'],
 ['gem','intro-art-64-v1/gem'],
 ['crown','intro-art-64-v1/crown'],
 ['clover','intro-art-64-v1/clover'],
 ['gold','intro-art-64-v1/gold'],
 ['pot','intro-art-64-v1/pot'],
 ['ruby','intro-art-64-v1/ruby'],
 ['lightning','intro-art-64-v1/lightning'],
] as const;
export const introProgress=(time:number,start:number,duration:number)=>Math.max(0,Math.min(1,(time-start)/duration));
export const introEase=(value:number)=>1-Math.pow(1-value,3);
export const INTRO_BURST_TIME=4.7;
export function pocketIntroState(time:number,loaded:boolean){
 const title=time>=POCKET_OPENING_SECONDS;
 return {title,canStart:title&&loaded,heroes:introEase(introProgress(time,1.3,.65)),logo:introEase(introProgress(time,5.05,.8)),gather:introEase(introProgress(time,3.15,1.15)),release:introEase(introProgress(time,INTRO_BURST_TIME,1.3))};
}
/** Each actor summons one symbol at a time; all eight meet before the burst. */
export function introSymbolMotion(time:number,index:number,targetX:number,targetY:number){
 const born=.95+index*.27,appear=introProgress(time,born,.48),gather=introProgress(time,3.15+index*.045,.78);
 const fromX=index%2===0?-160:160,fromY=-20;
 const hoverX=targetX*.78,hoverY=targetY*.65+40;
 let x=fromX+(hoverX-fromX)*introEase(appear),y=fromY+(hoverY-fromY)*introEase(appear)+Math.sin(appear*Math.PI)*60;
 const pull=gather*gather*gather;
 x=x*(1-pull);y=y*(1-pull)+40*pull;
 let scale=(.4+.6*introEase(appear))*(1-.75*pull),opacity=introProgress(time,born,.16);
 if(time>=INTRO_BURST_TIME){
  const flight=introProgress(time,INTRO_BURST_TIME+index*.012,.36),settle=introProgress(time,5.18,1.02);
  const distance=introEase(flight)*(1.12-.12*introEase(settle));
  x=targetX*distance;y=40+(targetY-40)*distance;
  scale=.25+.75*introEase(flight);opacity=1;
  x+=Math.sin(time*.65+index)*5*settle;y+=Math.cos(time*.75+index)*5*settle;
 }
 return {x,y,scale,opacity,angle:time>=INTRO_BURST_TIME?(1-introProgress(time,5.1,1.1))*(index%2?1:-1)*introProgress(time,INTRO_BURST_TIME,.4)*48:Math.sin(appear*Math.PI)*(index%2?1:-1)*18};
}
