import {SlotMain,SlotConfig,SlotPresentation,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {socialSlotCatalog,SocialSlotSpec} from './SocialSlotCatalog';
import {socialFeatureProfiles,SocialFeatureProfile} from './SocialFeatureProfiles';
import {socialPresentationProfiles,socialPresentationFor} from './SocialPresentationProfiles';
import {mineRound,wagonSequence,FIRE_PAYS,WagonEnhancer} from './FireFeature';
import {DWARF_INPUTS} from './DwarfMath';
/** Dedicated native mine and wagon engine; no payout correction or saved
 * player-dependent inputs. Purchase binds to the fresh cloned engine. */
export class DwarfSlot extends SlotMain {
 readonly bets=[...BET_LEVELS];readonly mode='clusters' as const;readonly hasBonus=true;readonly paylines:number[][]=[];
 readonly columns:number;readonly rows:number;readonly maxWin:number;readonly config:SlotConfig;
 readonly spec:SocialSlotSpec;readonly profile:SocialFeatureProfile;readonly presentation:SlotPresentation;
 readonly pays:Record<string,number[]>={};readonly regularPays:number[][];
 get usesReferencePayouts(){return true;}get unlockPriceTenths(){return 1000;}
 get bonusSymbol(){return this.spec.id+'-scatter';}get wildSymbol(){return this.spec.id+'-wild';}get bonusTriggerCount(){return this.profile.trigger;}
 constructor(){super();this.spec=socialSlotCatalog.find(s=>s.id==='fire-in-dwarf-hole')!;const spec=this.spec;
  this.profile=socialFeatureProfiles[spec.id];this.presentation=socialPresentationProfiles[spec.id]||socialPresentationFor(spec,this.profile);
  this.columns=this.profile.columns;this.rows=this.profile.rows;this.maxWin=this.profile.maxWin;this.regularPays=spec.paytable!.map(row=>[...row]);
  this.config={id:spec.id,title:spec.title,subtitle:spec.subtitle,tag:spec.provider+' · xBOMB',color:spec.colors[0],accent:spec.colors[1],description:[spec.hero,...this.profile.rules].join('\n'),symbols:spec.symbols.map((name,i)=>({id:spec.id+'-'+i,name,art:spec.arts[i],color:i<2?spec.colors[1]:spec.colors[2],weight:i<5?5:12,payout:this.regularPays[i][this.regularPays[i].length-1]}))};
  this.config.symbols.push({id:this.bonusSymbol,name:'SCATTER',art:'star',color:'#fff0a8',weight:1.1,payout:0},{id:this.wildSymbol,name:'WILD',art:'star',color:'#fff4bd',weight:.35,payout:0});
  spec.symbols.forEach((_,i)=>this.pays[spec.id+'-'+i]=[...this.regularPays[i]]);
 }
 symbolPay(symbol:number,count:number){return FIRE_PAYS[symbol]?.[count-3]||0;}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.mineSpin(bet,rng);}
 spinForPurchase(bet:number,rng:()=>number){return this.spin(bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){return this.minePurchase(bet,rng);}
 private mineBase(bet:number,rng:()=>number,opening?:string[]):SpinResult{
  const pick=(column:number)=>{const weights=Array.from({length:12},(_,i)=>i<10?(i===0?DWARF_INPUTS.baseHigh:((i+column*2)%10<2?4:1)):i===10?DWARF_INPUTS.baseScatter:.025);let roll=rng()*weights.reduce((n,v)=>n+v,0);for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0)return this.spec.id+'-'+(i<10?i:i===10?'scatter':'wild');}return this.spec.id+'-9';};
  const r=mineRound({id:this.spec.id,bet,pick,opening});r.presentation=this.presentation;return r;
 }
 private mineSpin(bet:number,rng:()=>number){return this.mineSequence(this.mineBase(bet,rng),bet,rng);}
 private mineSequence(base:SpinResult,bet:number,rng:()=>number,purchase=false){
  const trigger=base.board.filter(s=>s===this.bonusSymbol).length;if(trigger<3||base.payout>=bet*this.maxWin)return base;
  const enhancer=():WagonEnhancer=>{const roll=rng();if(roll<.80)return{kind:'coin',value:[1,1,1,2,2,5,10,15,25][Math.floor(rng()*9)]};if(roll<.89)return{kind:'multiply',value:[2,2,3,5][Math.floor(rng()*4)]};if(roll<.96)return{kind:'dynamite',value:1+Math.floor(rng()*3)};return{kind:roll<.985?'bag':roll<.998?'chest':'miner',value:1};};
  const rounds=[...(purchase?[]:[base]),...wagonSequence({id:this.spec.id,bet,trigger,limit:bet*this.maxWin-(purchase?0:base.payout),rng,enhancer,landChance:DWARF_INPUTS.wagonLandChance})];rounds.forEach(r=>r.presentation=this.presentation);
  return{board:[...rounds[rounds.length-1]!.board],bet,payout:rounds.reduce((n,r)=>n+r.payout,0),wins:rounds.flatMap(r=>r.wins),rounds,freeSpinsAwarded:3,featureName:'LUCKY MINE WAGONS',presentation:this.presentation,bonusTriggerRound:purchase?base:undefined};
 }
 private minePurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const board=Array.from({length:36},(_,cell)=>this.spec.id+'-'+(cell<18?Math.floor(rng()*10):'rock')),positions=Array.from({length:18},(_,cell)=>cell);
  for(let i=0;i<3;i++){const selected=i+Math.floor(rng()*(18-i));[positions[i],positions[selected]]=[positions[selected],positions[i]];board[positions[i]]=this.bonusSymbol;}
  return this.mineSequence({bet,board,wins:[],payout:0,presentation:this.presentation},bet,rng,true);
 }
 demoSpin(bet:number){let seed=99173;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const b=Array.from({length:18},(_,i)=>this.spec.id+'-'+((i*3+Math.floor(i/6))%10));b[17]=this.wildSymbol;b[16]=this.bonusSymbol;return this.mineBase(bet,rng,b);}
}
