import{ACE_TARGET_MODEL}from'./AceTargetMath';
export type AceTargetInputs={ace:number;wild:number;regularWeights:readonly number[];baseZeroByBet:Record<number,number>;freeZeroByBet:Record<number,number>};
const ACE_DRAFT:AceTargetInputs=ACE_TARGET_MODEL;
function check(rng:()=>number){return()=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Ace uniform');return u;};}
function symbol(id:string,bet:number,u:number,free:boolean){const z=(free?ACE_DRAFT.freeZeroByBet:ACE_DRAFT.baseZeroByBet)[bet];if(!Number.isFinite(z))throw Error('Invalid Ace bet');const p=[z,...ACE_DRAFT.regularWeights.map(v=>(1-z-ACE_DRAFT.ace-ACE_DRAFT.wild)*v/ACE_DRAFT.regularWeights.reduce((a,b)=>a+b,0)),ACE_DRAFT.wild];let n=8;for(let i=0;i<p.length;i++){u-=p[i]/(1-ACE_DRAFT.ace);if(u<0){n=i;break;}}return id+'-'+(n===8?'wild':n);}
export function aceInputBoard(id:string,bet:number,rng:()=>number,free=false){if(!Number.isFinite(ACE_DRAFT.baseZeroByBet[bet]))throw Error('Invalid Ace bet');rng=check(rng);return Array.from({length:15},()=>{const sign=rng(),u=rng();return sign<ACE_DRAFT.ace?id+'-ace':symbol(id,bet,u,free);});}
export function aceInputPurchase(id:string,bet:number,rng:()=>number){if(!Number.isFinite(ACE_DRAFT.baseZeroByBet[bet]))throw Error('Invalid Ace bet');rng=check(rng);const a=ACE_DRAFT.ace;let first=-1;for(let row=0;row<3;row++){const hazard=a/(1-(1-a)**(3-row));if(rng()<hazard){first=row;break;}}if(first<0)throw Error('Invalid Ace conditional gate');const board=[];for(let c=0;c<15;c++){const sign=rng(),u=rng(),col=c%5,row=Math.floor(c/5),gate=col===4?(row===first||row>first&&sign<a):sign<a;board.push(gate?id+'-ace':symbol(id,bet,u,false));}return board;}
