import{DRAGON_MODEL as M}from'./DragonEmberMath';
import{dragonInputBoard}from'./DragonInputBoard';
import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
/** Observed Double/White Dragon respin structures; trigger, odds and awards are local. */
export class DragonEmberSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['lock','portrait','reel'])this.config.symbols.push({id:this.id(name),name,color:'#f2c46b',weight:0,payout:0});this.config.description='5×3 · 25라인 · 왼쪽부터 연결\n용의 알 BONUS 3개 이상: 쌍룡 또는 백룡 금고를 선택합니다.\n쌍룡: 독립 금고 2개. 백룡: 금고 1개이며 새 알은 티어 상금입니다.\n각 금고는 알 5개와 리스핀 3회로 시작하며 새 알이 착지한 금고만 3회로 복구합니다.\n12칸을 채우면 잠긴 보상 릴이 열립니다. 각 알과 추가 릴 상금은 마지막에 한 번씩 수집합니다.\n진입 조건·확률·티어 금액은 로컬 규칙이며 공유 잭팟 적립은 없습니다.';}
 private input(bet:number,rng:()=>number,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid Dragon bet');return dragonInputBoard(this.config.id,M.zeroByBet[bet],M.wild,M.gate,rng,conditional);}
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.input(bet,rng);}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-dragon';}
 private bonus(bet:number,rng:()=>number,base:SpinResult,white:boolean){
  const count=white?1:2,g={columns:5,rows:3*count},boards=Array.from({length:count},()=>new Map<number,number>()),left=Array(count).fill(3),opened=Array(count).fill(false),extras=new Map<number,number>(),rounds=[base],snapshots:ExpansionFrame[]=[];
  const positions=Array.from({length:12},(_,c)=>Math.floor(c/4)*5+c%4);for(let i=11;i>0;i--){const j=ri(rng,i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
  const initial=positions.slice(0,5).map(c=>[c,[1,2,5][ri(rng,3)]] as const);for(const board of boards)for(const [c,v]of initial)board.set(c,v);
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],held?:number[])=>{const board=Array(count*15).fill(''),fixed:number[]=[];for(let p=0;p<count;p++){for(const [c]of boards[p]){board[p*15+c]=this.id('coin');fixed.push(p*15+c);}for(let row=0;row<3;row++){const c=p*15+row*5+4;board[c]=this.id(opened[p]?'reel':'lock');fixed.push(c);}}
   const f=this.frame(board,action,caption,focus,{held:held||fixed,boardGroups:count===2?{count:2,rows:3,columns:5}:undefined,dragonVault:{white,left:[...left],filled:boards.map(b=>b.size),opened:[...opened]},panel:{label:white?'WHITE DRAGON':'DOUBLE DRAGON',values:[...left],columns:count}},g);snapshots.push(f);return f;};
  const entry=frame('reveal',white?'백룡 금고 · 새 알은 티어 상금':'쌍룡 · 독립 금고 2개 · 각각 3회');
  entry.dragonVault!.entryCells=entry.board.flatMap((id,cell)=>id===this.id('coin')?[cell]:[]);
  rounds.push(this.round(bet,[entry]));
  while(left.some(n=>n>0)){
   const active=left.map(n=>n>0);for(let p=0;p<count;p++)if(active[p])left[p]--;const prior=frame('reels','고정 알 유지 · 진행 중 금고만 빈칸 회전'),fs=[prior],landed:number[]=[];for(let p=0;p<count;p++)if(!active[p])for(let c=0;c<15;c++)if(!prior.held!.includes(p*15+c))prior.held!.push(p*15+c);
   for(let p=0;p<count;p++)if(active[p]&&!opened[p]&&boards[p].size<12){
    const found:number[]=[];for(const c of positions)if(!boards[p].has(c)&&rng()<M.landing[white?1:0]){boards[p].set(c,white?[7,12,20,50][ri(rng,4)]:[1,2,3,5,10][ri(rng,5)]);found.push(p*15+c);}
    if(found.length){left[p]=3;landed.push(...found);}if(boards[p].size===12)left[p]=0;
   }
   if(landed.length){
    const landing=frame('effect',white?'백룡의 티어 알 착지 · 3회 복구':'새 알 착지 · 해당 금고만 3회 복구',landed);
    // Spin toward the actual landing, retaining only the pre-spin held cells.
    prior.board=[...landing.board];fs.push(landing);
   }
   for(let p=0;p<count;p++)if(boards[p].size===12&&!opened[p]){
    fs.push(frame('trigger',(p+1)+'번 금고 12칸 완성 · 보상 릴 해금',[p*15+4,p*15+9,p*15+14]));opened[p]=true;
    const values=[7,12,20,50,200],selected=ri(rng,values.length),value=values[selected];extras.set(p,value);
    const stopped=frame('reveal',(p+1)+'번 보상 릴 정지 · 추가 상금',[p*15+9]);
    stopped.rewardReel={cell:p*15+9,values:values.map(n=>Math.round(bet*n*this.payoutFactor)),selected:Math.round(bet*value*this.payoutFactor),unit:'amount'};fs.push(stopped);
   }
   fs.push(frame('state','각 금고의 남은 리스핀'));rounds.push(this.round(bet,fs));
  }
  const awards=new Map<number,Win>();for(let p=0;p<count;p++){for(const [c,v]of boards[p])awards.set(p*15+c,{line:-1,symbol:this.id('coin'),cells:[p*15+c],amount:Math.round(bet*v*this.payoutFactor),multiplier:v*this.payoutFactor});if(extras.has(p)){const v=extras.get(p)!;awards.set(p*15+9,{line:-1,symbol:this.id('reel'),cells:[p*15+9],amount:Math.round(bet*v*this.payoutFactor),multiplier:v*this.payoutFactor});}}
  const paid=frame('collect','용 금고 → 알과 보상 릴 상금 한 번씩 수집',Array.from(awards.keys()));paid.wins=Array.from(awards.values());for(const f of snapshots)f.coinAwards=f.board.flatMap((symbol,c)=>symbol===this.id('coin')||symbol===this.id('reel')&&c%15===9?[{cell:c,win:awards.get(c)!}]:[]);rounds.push(this.round(bet,[paid]));return this.finish(rounds,{featureOnly:true});
 }
 private branches(board:string[],bet:number,rng:()=>number,base:SpinResult){return this.choices('용 금고를 선택하세요',['쌍룡 · 독립 금고 2개','백룡 · 새 알은 티어 상금'],[false,true].map(white=>this.bonus(bet,rng,JSON.parse(JSON.stringify(base)),white)));}
 play(board:string[],bet:number,rng:()=>number){this.validate(board,bet,{columns:5,rows:3});const base=this.ordinary(board,bet),found=cells(board,this.id('scatter'));if(found.length<3)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','용의 알 BONUS 3개 이상 · 두 보너스 선택',found));return this.branches(board,bet,rng,base);}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.input(bet,rng,true),found=cells(board,this.id('scatter'));return this.purchaseFromResult(this.branches(board,bet,rng,this.round(bet,[this.frame(board,'trigger','독립 용 금고 보너스 구매',found)])));}
}
