export function twinNativeBoard(id:string,bet:number,rng:()=>number){
 const zero=TWIN_ZERO_BY_BET[bet];if(zero===undefined)throw Error("Invalid Twin wager");
 const rest=[6,7,8,10,12,14,16];return Array.from({length:15},(_,cell)=>{
  let u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error("Invalid Twin uniform");
  const wild=cell%5===0?0:TWIN_WILD;if(u<wild)return id+"-wild";u=(u-wild)/(1-wild);if(u<zero)return id+"-0";
  let roll=(u-zero)/(1-zero)*73;for(let i=0;i<rest.length;i++){roll-=rest[i];if(roll<0)return id+"-"+(i+1);}return id+"-7";
 });
}
