import {legacyRound,legacyAddSelection} from './LegacyFeature';
import {legacyResult} from './LegacyResult';
import type {SpinResult} from './SlotMain';
import {LEGACY_MODEL} from './LegacyMath';

/** Original sampling weights for our version, not the provider's private strips.
 * Base/free inputs are explicit and independent; results are never normalized. */
export const LEGACY_WEIGHTS=[4,5,7,7,14,14,17,17,17] as const;
export const LEGACY_ALTAR_CHANCE=.103;
export function legacySampler(rng:()=>number,altarChance=LEGACY_MODEL.baseAltar,high=LEGACY_MODEL.baseHigh,top=LEGACY_MODEL.baseTop){
 if(!Number.isFinite(altarChance)||altarChance<0||altarChance>1)throw Error('Invalid Legacy altar chance');
 const roll=()=>{const n=rng();if(!Number.isFinite(n)||n<0||n>=1)throw Error('Invalid Legacy RNG');return n;};
 const weights=LEGACY_WEIGHTS.map((w,i)=>w*(i<4?high:1)*(i===0?top:1));
 const pick=()=>{let n=roll()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<9;i++){n-=weights[i];if(n<0)return i;}return 8;};
 return{roll,pick,board:()=>{const board=Array.from({length:15},pick);for(let col=0;col<5;col++)if(roll()<altarChance)board[Math.floor(roll()*3)*5+col]=9;return board;}};
}
export interface LegacyGameOptions {
 /** Deterministic fixture source for tests/isolated playback. */
 board?:(round:number)=>number[];
 /** Offline sampler calibration only; live calls use the exported fixed value. */
 altarChance?:number;
 opening?:number[];
 purchase?:boolean;
}
export function legacyGame(bet:number,rng:()=>number=Math.random,options:LegacyGameOptions={}):SpinResult{
 const sample=legacySampler(rng,options.altarChance),free=legacySampler(rng,LEGACY_MODEL.freeAltar,LEGACY_MODEL.freeHigh,1),board=(index:number)=>options.board?options.board(index):index===0?options.opening||sample.board():free.board(),id='legacy-of-wildead',maximum=bet*5000;
 const base=legacyRound(board(0),bet,[],maximum);
 if(options.purchase){base.baseAwards=[];base.awards=[];base.payout=0;}
 const first=legacyResult(id,bet,base);
 if(!base.freeSpinsAdded||base.payout>=maximum)return first;
 let selected=legacyAddSelection([],sample.roll),left=8,total=base.payout,played=0;
 const initial=selected[0],rounds:SpinResult[]=options.purchase?[]:[first];
 while(left>0&&total<maximum){
  if(played>=10000)throw Error('Legacy bonus did not converge');
  left--;played++;
  const calculated=legacyRound(board(played),bet,selected,maximum-total),round=legacyResult(id,bet,calculated);
  total+=round.payout;
  const added=total<maximum?calculated.freeSpinsAdded:0;
  if(added){selected=legacyAddSelection(selected,sample.roll);left+=added;}
  if(total>=maximum)left=0;
  round.freeSpinsAdded=added;round.freeSpinsRemaining=left;
  round.roundLabel='프리스핀 '+played+' · 남은 '+left;
  round.legacyFeature!.selectedAfter=selected.map(symbol=>id+'-'+symbol);
  rounds.push(round);
 }
 return{bet,board:[...rounds[rounds.length-1].board],rounds,wins:rounds.flatMap(r=>r.wins),payout:total,freeSpinsAwarded:8,selectedSymbol:id+'-'+initial,featureName:'모래의 기억 · 확장 심볼',bonusTriggerRound:options.purchase?first:undefined,bonusEndReason:total>=maximum?'max-win':'spins-exhausted'};
}
