import{CAST_PREVIEW_INPUTS}from'./StarlitCastMath';
import{castInputBoard}from'./StarlitCastInput';
import {Win} from './SlotMain';
import {socialSeed} from './Social1921Rules';
import {Social2230LineSlot,socialPresentation,sumResult} from './Social2230Rules';
export interface CastPlayback {actor:number;before:number[];after:number[];stars:number[];ranked:boolean;award?:Win;}
export class StarlitCastSlot extends Social2230LineSlot {
 readonly selectionTitle='별을 받을 배우를 고르세요';readonly selectionLabels=['연출가','가수','마술사','무용가','악사'];
 readonly presentation=socialPresentation('배우 다섯 명의 개별 별과 등급','별빛 극단 공연');
 readonly config=this.namedConfig('starlit-cast','별빛 배우 극장','STARLIT CAST',['연출 대본','가수 마이크','마술 모자','무용 신발','악사 바이올린','공연 티켓','분장 거울','무대등','극단 가면 WILD','배우 별'],'선택한 배우에게 착지한 별을 모읍니다. 배우마다 진행·등급 별도.\n배우 순서대로 별 5/6/7/8/9개마다 등급 상승(최대 3), 공연 보상 지급. 초과 별은 이월.\n연출/가수/마술사/무용가/악사는 ×2/3/4/5/6 공연.\n등급마다 +1배. 베팅별 저장. AUTO는 마지막 선택 유지.','#3d294d','#ebbded');
 selectionForBet(bet:number){const n=this.state(bet,Array(11).fill(0))[0];return n<5?n:0;}
 protected draw(bet:number,rng:()=>number){return this.evaluate(castInputBoard(this.config.id,bet,rng),bet);}
 spin(bet:number,rng:()=>number=Math.random){
  if(!Number.isInteger(this.selection)||this.selection<0||this.selection>4)throw Error('Invalid cast selection');
  const r=this.draw(bet,rng),raw=this.state(bet,Array(11).fill(0)),before=raw.length===11?raw:Array(11).fill(0),after=[...before],actor=this.selection,stars=r.board.flatMap((id,c)=>id===this.config.id+'-scatter'?[c]:[]);
  after[0]=actor;after[1+actor]+=stars.length;let multiplier=0,ranked=false;
  while(after[1+actor]>=5+actor){after[1+actor]-=5+actor;after[6+actor]=Math.min(3,after[6+actor]+1);multiplier+=2+actor+after[6+actor];ranked=true;}
  let award:Win|undefined;if(multiplier){award={line:-1,symbol:this.config.id+'-scatter',cells:stars,multiplier,amount:bet*multiplier};r.wins.push(award);}
  r.castFeature={actor,before,after,stars,ranked,award};r.progressUpdate=this.update(bet,after);return sumResult(r);
 }
 demoSpin(bet:number){const previous=this.progress,w=CAST_PREVIEW_INPUTS[this.selection];if(!w)throw Error('Invalid cast selection');try{this.progress={[this.config.id+':'+bet]:[...w.before]};return this.spin(bet,socialSeed(w.seed));}finally{this.progress=previous;}}
}
