/** Fixed categorical raw boards and direct conditional SCAT input gate. Source repair stays in engine. */
import{BRONZE_INPUTS as rows}from'./BronzeGuardMath';
function unit(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Bronze uniform');return u;}
function input(bet:number){const row=rows.find(r=>r.bet===bet);if(!row)throw Error('Invalid Bronze input wager');return row;}
function normal(u:number,z:number,free:boolean){const ratios=free?[6,7,8,10,12]:[6,7,8,10,12,14,16],sum=ratios.reduce((a,b)=>a+b,0);if(u<z)return 0;let mass=z;for(let n=0;n<ratios.length;n++){mass+=(1-z)*ratios[n]/sum;if(u<mass)return n+1;}return ratios.length;}
function remainingMass(n:number,need:number,p:number):number{if(need<=0)return 1;if(need>n)return 0;return p*remainingMass(n-1,need-1,p)+(1-p)*remainingMass(n-1,need,p);}
export function bronzeRawInput(id:string,bet:number,rng:()=>number,free=false,purchase=false){const row=input(bet),q=free?row.freeScatter:row.paidScatter,g=free?row.freeGuard:row.paidGuard,z=free?row.freeRegularZero:row.paidRegularZero,has:boolean[]=[],seen=Array(5).fill(false),board:string[]=[];
 if(purchase){const reel=1-(1-q)**3;let left=3;for(let c=0;c<5;c++){const yes=reel*remainingMass(4-c,left-1,reel),no=(1-reel)*remainingMass(4-c,left,reel),picked=unit(rng)<yes/(yes+no);has[c]=picked;if(picked)left--;}}
 for(let cell=0;cell<15;cell++){const col=cell%5,r=Math.floor(cell/5),flag=unit(rng),u=unit(rng),chance=!purchase?q:!has[col]?0:seen[col]?q:r===2?1:q/(1-(1-q)**(3-r)),scat=flag<chance;if(scat){seen[col]=true;board.push(id+'-scatter');}else if(u<g/(1-q))board.push(id+'-guard');else board.push(id+'-'+normal((u-g/(1-q))/(1-g/(1-q)),z,free));}
 return board;
}
