import {SpinResult,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,connected,randomIndex} from './TumbleCore';
import {MAGNET_TAPE_MODEL,magnetUniform,magnetSymbol,magnetPurchaseBoard} from './MagnetTapeMath';
export class MagnetTapeSlot extends TumbleGame {
 readonly columns=6;readonly rows=6;readonly hasBonus=true;
 readonly config=this.configFor('magnet-tape-studio','자석 테이프 스튜디오','MAGNET TAPE STUDIO',['빨강 테이프','주황 테이프','노랑 테이프','초록 테이프','파랑 테이프','보라 테이프','날개 테이프','음반 상금','자석','증폭기'],['0','1','2','3','4','5','wild','money','magnet','boost'],'6×6 · 연결5개. 자석은 같은 색을 연결 영역으로 이동. 증폭기는 WILD 배수 +2 후 음반으로 변환, 연쇄 당첨마다 +1. 일반 WILD는 연쇄 동안 유지. WILD3개가 모이면 차트로 전환. 고정 음반 수집3회, 마지막에 연결된 음반만 지급. 음반 한 개0.4BET × 연결 WILD 배수.',[12*MAGNET_TAPE_MODEL.baseHigh,12,12,12,12,12,MAGNET_TAPE_MODEL.baseWild,1,1.2,.7]);
 private purchasing=false;
 protected pick(rng:()=>number){return magnetSymbol(this.config.id,rng,this.purchasing);}
 draw(rng:()=>number){return this.purchasing?magnetPurchaseBoard(this.config.id,rng):super.draw(rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const saved=this.purchasing;this.purchasing=true;try{return super.prepareBonusPurchase(bet,rng);}finally{this.purchasing=saved;}}
 private magnet(board:string[],frames:TumbleFrame[],rng:()=>number){
  while(board.includes(this.id('magnet'))){const origin=board.indexOf(this.id('magnet'));
   const chosen=this.id(randomIndex(rng,6)),sources=indices(board,chosen);if(!sources.length){board[origin]=this.id('money');continue;}
   // BFS target cells form one connected region, unlike a row-major wrap.
   const targets:number[]=[],queue=[origin],seen=new Set([origin]);
   while(queue.length&&targets.length<sources.length+1){const c=queue.shift()!;if(board[c]!==this.wild&&board[c]!==this.id('boost'))targets.push(c);for(const n of adjacent(c,6,36))if(!seen.has(n)){seen.add(n);queue.push(n);}}
   const tokens=board.map((symbol,from)=>({symbol,from}));tokens[origin].symbol=chosen;
   const matching=tokens.filter(t=>t.symbol===chosen),rest=tokens.filter(t=>t.symbol!==chosen),placed=new Map<number,typeof tokens[number]>();
   targets.slice(0,matching.length).forEach((to,i)=>placed.set(to,matching[i]));const remainder=[...matching.slice(placed.size),...rest];let next=0;
   const moves:CellDrop[]=[];for(let to=0;to<36;to++){const t=placed.get(to)||remainder[next++];board[to]=t.symbol;moves.push({from:t.from,to,symbol:t.symbol});}
   this.frame(frames,board,'move','자석 · 흩어진 테이프를 한곳으로',{moves,cells:targets});
  }
 }
 play(board:string[],bet:number,rng:()=>number):SpinResult{
  this.check(board,bet);board=[...board];const frames:TumbleFrame[]=[];let wildPower=1,trigger=false;
  this.frame(frames,board,'land','테이프 착지');
  for(let step=0;;step++){
   trigger||=indices(board,this.wild!).length>=3;this.magnet(board,frames,rng);
   const boosts=indices(board,this.id('boost'));if(boosts.length){wildPower+=boosts.length*2;boosts.forEach(c=>board[c]=this.id('money'));this.frame(frames,board,'transform','증폭기 → 음반 · WILD ×'+wildPower,{cells:boosts,badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});}
   const wins=this.clusters(board,bet).map(w=>{const m=w.cells.some(c=>board[c]===this.wild)?wildPower:1;w.amount*=m;w.multiplier=m;return w;});
   for(const cells of connected(board,this.id('money'),this.wild,c=>adjacent(c,6,36)))if(cells.length>=5)wins.push(this.prize(bet,cells.length*.1*wildPower,cells,this.id('money')));
   if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>board[c]!==this.wild));this.frame(frames,board,'win','테이프 클러스터 지급',{wins,cells:Array.from(remove),badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});wildPower++;
   if(trigger||!remove.size)break;const next=this.gravity(board,remove,rng,new Set(indices(board,this.wild!)));board=next.board;this.frame(frames,board,'drop','빈자리 테이프 낙하',{moves:next.moves,badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});
   if(frames.reduce((n,f)=>n+f.wins.reduce((m,w)=>m+w.amount,0),0)>=bet*this.maxWin){this.frame(frames,board,'state','최대 당첨 정산');break;}
  }
  const base=this.round(bet,frames);if(!trigger)return this.finish([base]);
  const rounds=[base],locked=new Set(indices(board,this.wild!).concat(indices(board,this.id('money'))));
  this.frame(frames,board,'state','차트 진입 · WILD와 음반 고정',{marks:Array.from(locked)});
  for(let left=2;left>=0;left--){const ff:TumbleFrame[]=[];const prior=[...board],held=Array.from(locked);for(let c=0;c<36;c++)if(!locked.has(c)){const r=magnetUniform(rng),wild=this.purchasing?MAGNET_TAPE_MODEL.purchaseChartWild:MAGNET_TAPE_MODEL.baseChartWild;board[c]=r<.4?this.id('money'):r<.4+wild?this.wild!:this.id('void');}
   this.frame(ff,board,'land','차트 수집 · 남은 '+left+'회',{marks:Array.from(locked),stationary:held});
   const fresh=indices(board,this.id('money')).concat(indices(board,this.wild!)).filter(c=>!locked.has(c)).sort((a,b)=>a-b);
   // Reveal each new record before adding its fixed marker. No future locks on landing.
   for(const cell of fresh){
    this.frame(ff,board,'state','slot.magnet.chart.reveal',{cells:[cell],marks:Array.from(locked)});
    locked.add(cell);
    this.frame(ff,board,'state','slot.magnet.chart.lock',{cells:[cell],marks:Array.from(locked)});
   }
   if(!fresh.length)this.frame(ff,board,'state','slot.magnet.chart.miss',{marks:Array.from(locked)});
   if(left===0){
    const groups=connected(board,this.id('money'),this.wild,c=>adjacent(c,6,36)).filter(cells=>cells.length>=5);
    for(const cells of groups){
     const records=cells.filter(c=>board[c]===this.id('money')),wilds=cells.filter(c=>board[c]===this.wild),multiplier=1+wilds.length;
     this.frame(ff,board,'state','slot.magnet.chart.connect',{cells,marks:Array.from(locked)});
     const badges:Record<number,string>={};
     for(let i=0;i<wilds.length;i++){
      badges[wilds[i]]='+1';
      for(const cell of records)badges[cell]='×'+(i+2);
      this.frame(ff,board,'state','slot.magnet.chart.amplify',{cells:[wilds[i],...records],marks:Array.from(locked),badges});
     }
     this.frame(ff,board,'collect','slot.magnet.chart.pay',{wins:[this.prize(bet,records.length*MAGNET_TAPE_MODEL.recordUnit*multiplier,cells,this.id('money'))],cells,marks:Array.from(locked),badges});
    }
    if(!groups.length)this.frame(ff,board,'state','slot.magnet.chart.unlinked',{marks:Array.from(locked)});
   }
   const r=this.round(bet,ff);r.heldAtStart=held.map(cell=>({cell,symbol:prior[cell],value:1}));r.freeSpinsRemaining=left;rounds.push(r);
  }return this.finish(rounds,{freeSpinsAwarded:3});
 }
 rawSpin(bet:number,rng:()=>number=Math.random){return this.play(this.draw(rng),bet,rng);}
}

