export const GLYPH_INPUTS={"paidGate": 0.011054513547048967, "freeGate": 0.005, "wild": 0.005, "high": [0.404, 0.7860627346829305, 0.768097309984773, 0.81148864]};
export function glyphUniform(rng:()=>number){const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid Glyph uniform');return v;}
export function glyphBinomial(n:number,k:number,p:number){let c=1;for(let i=1;i<=k;i++)c=c*(n-i+1)/i;return c*p**k*(1-p)**(n-k);}
export function glyphSymbol(phase:number,rng:()=>number,noGate=false){if(!Number.isInteger(phase)||phase<0||phase>3)throw Error('Invalid Glyph phase');const q=noGate?0:phase?GLYPH_INPUTS.freeGate:GLYPH_INPUTS.paidGate;let u=glyphUniform(rng);if(u<q)return 'scatter';u=(u-q)/(1-q);if(u<GLYPH_INPUTS.wild)return 'wild';u=(u-GLYPH_INPUTS.wild)/(1-GLYPH_INPUTS.wild);const high=GLYPH_INPUTS.high[phase];if(u<high)return '0';return String(1+Math.min(4,Math.floor((u-high)/(1-high)*5)));}
