/** Conditional entrance for native three-row reels with at most one mark of each
 * kind per reel. It conditions symbol roles only, never awards or winning lines. */
export type ReelRole=0|1|2;
export interface ReelRoleInput {regular:number;wild:number;scatter:number;}
export interface ReelRoleProfile {roles:ReelRole[];probability:number;}
export function sequentialRoleProfiles(input:ReelRoleInput):ReelRoleProfile[]{
 if(!Number.isFinite(input.regular)||input.regular<=0||![input.wild,input.scatter].every(v=>Number.isFinite(v)&&v>=0))throw Error('Invalid reel weights');
 const out:ReelRoleProfile[]=[];
 const visit=(roles:ReelRole[],used:number,probability:number)=>{
  if(roles.length===3){out.push({roles,probability});return;}
  const weights=[input.regular,used&1?0:input.wild,used&2?0:input.scatter],sum=weights.reduce((a,b)=>a+b,0);
  for(let role=0;role<3;role++)if(weights[role]>0)visit([...roles,role as ReelRole],used|(role===1?1:role===2?2:0),probability*weights[role]/sum);
 };visit([],0,1);return out;
}
const entranceCache=new Map<string,(rng:()=>number)=>ReelRole[]>();
export function conditionalReelEntrance(inputs:ReelRoleInput[],role:1|2,count:number,exact:boolean){
 if(!Number.isInteger(count)||count<0||count>inputs.length)throw Error('Invalid entrance count');
 const key=JSON.stringify([inputs,role,count,exact]),cached=entranceCache.get(key);if(cached)return cached;
 const profiles=inputs.map(sequentialRoleProfiles),remaining=Array.from({length:inputs.length+1},()=>Array(inputs.length+1).fill(0));
 for(let n=0;n<=inputs.length;n++)remaining[inputs.length][n]=Number(exact?n===count:n>=count);
 for(let col=inputs.length-1;col>=0;col--)for(let n=0;n<=col;n++)for(const profile of profiles[col])remaining[col][n]+=profile.probability*remaining[col+1][n+Number(profile.roles.includes(role))];
 if(!(remaining[0][0]>0))throw Error('Impossible reel entrance');
 const sample=(rng:()=>number)=>{
  let seen=0;const board:ReelRole[]=Array(inputs.length*3).fill(0);
  for(let col=0;col<inputs.length;col++){
   const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid reel RNG');
   let roll=u*remaining[col][seen],chosen:ReelRoleProfile|undefined;
   for(const profile of profiles[col]){const mass=profile.probability*remaining[col+1][seen+Number(profile.roles.includes(role))];if(mass<=0)continue;chosen=profile;roll-=mass;if(roll<0)break;}
   if(!chosen)throw Error('Invalid conditioned profile');
   chosen.roles.forEach((r,row)=>board[row*inputs.length+col]=r);seen+=Number(chosen.roles.includes(role));
  }return board;
 };entranceCache.set(key,sample);return sample;
}
