import {SpinResult,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,connected,randomIndex,totalWins,tumbleRng} from './TumbleCore';
import {SIGNAL_INPUTS as M} from './SignalStackMath';
import {signalClusters} from './SignalStackCluster';

export class SignalStackSlot extends TumbleGame {
private purchasing=false;private feature=false;
 protected pick(rng:()=>number){if(!this.feature)return this.fieldSymbol(this.incomingCells.shift()??0,rng);const high=this.feature?(this.purchasing?M.purchaseHigh:M.freeHigh):1;const weights=[12*high,12,12,12,12,12];let r=this.uniform(rng)*weights.reduce((a,b)=>a+b,0);for(let i=0;i<6;i++){r-=weights[i];if(r<0)return this.id(i);}return this.id(5);}

private incomingCells:number[]=[];
 clusters(board:string[],bet:number,multiplier=1,neighbors?:(cell:number)=>number[],minimum=this.threshold){return board.length===35&&!neighbors&&minimum===5?signalClusters(this,board,bet,multiplier):super.clusters(board,bet,multiplier,neighbors,minimum);}
 private uniform(rng:()=>number){const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid signal RNG');return v;}
 // Only the red symbol has a new ordinary table; the native free table is preserved.
 unit(symbol:number,count:number){return !this.feature&&symbol===0?count<5?0:M.paidRedFiveUnit*(count-4):super.unit(symbol,count);}
 private fieldSymbol(cell:number,rng:()=>number){const favored=(Math.floor(cell/5)+cell%5)%6,accent=this.purchasing?M.purchaseFieldAccent:M.fieldAccent,weights=Array.from({length:6},(_,i)=>i===favored?accent:1);let r=this.uniform(rng)*(accent+5);for(let i=0;i<6;i++){r-=weights[i];if(r<0)return this.id(i);}return this.id(5);}
 draw(rng:()=>number){return this.feature?super.draw(rng):Array.from({length:35},(_,cell)=>this.fieldSymbol(cell,rng));}
 gravity(board:string[],removed:Set<number>,rng:()=>number,pinned=new Set<number>(),active=(c:number)=>board[c]!==this.id('void')){
  if(!this.feature){for(let col=0;col<5;col++){const n=Array.from(removed).filter(c=>c%5===col).length;for(let row=0;row<n;row++)this.incomingCells.push(row*5+col);}}
  try{return super.gravity(board,removed,rng,pinned,active);}finally{this.incomingCells=[];}
 }
 prepareBonusPurchase(bet:number,rng:()=>number){const saved=this.purchasing;this.purchasing=true;try{return super.prepareBonusPurchase(bet,rng);}finally{this.purchasing=saved;}}

 readonly columns=5;readonly rows=7;readonly hasBonus=true;
 readonly config=this.configFor('signal-stack-ruins','신호를 쌓는 유적','SIGNAL STACK RUINS',['태양 석판','달 석판','파도 석판','잎 석판','불 석판','눈 석판'],['0','1','2','3','4','5'],'5×7 · 연결5개. 당첨 심볼을 남기고 비당첨만 제거. 계속 커진 당첨 집합은 회전 종료 때 한 번 지급. 위쪽 행 도달: 무료3회, 전판 완성:6회. 무료에서는 집합 유지·행 완성 배수, 마지막 회전에만 전체 집합 지급.');
 private grow(initial:string[],bet:number,rng:()=>number,retained=new Set<number>(),free=false){
  let board=[...initial],locked=new Set(retained),frames:TumbleFrame[]=[],passes=0;
  this.frame(frames,board,'land',free?'유적 무료 · 수집 집합 유지':'신호 탐색',{marks:Array.from(locked),stationary:Array.from(retained)});
  // Each continuing pass adds at least one of the35 cells;35 is the exact finite state bound.
  for(;passes<35;passes++){
   const wins=this.clusters(board,bet),matching=new Set(wins.flatMap(w=>w.cells)),fresh=Array.from(matching).filter(c=>!locked.has(c));if(!fresh.length)break;
   fresh.forEach(c=>locked.add(c));this.frame(frames,board,'state','당첨 집합 확대 · 아직 미정산',{cells:fresh,marks:Array.from(locked)});
   if(locked.size===35)break;
   const remove=new Set(board.map((_,c)=>c).filter(c=>!locked.has(c))),next=this.gravity(board,remove,rng);
   locked=new Set(next.moves.filter(m=>m.from>=0&&locked.has(m.from)).map(m=>m.to));board=next.board;
   this.frame(frames,board,'drop','비당첨만 제거 · 당첨 집합은 내려와 유지',{moves:next.moves,marks:Array.from(locked),cells:Array.from(remove)});
  }
  const fullRows=[0,1,2,3,4,5,6].filter(r=>Array.from({length:5},(_,c)=>r*5+c).every(c=>locked.has(c))),multiplier=free?M.freeRowTiers[fullRows.length]:1;
  const wins=this.clusters(board,bet,multiplier).filter(w=>w.cells.some(c=>locked.has(c)));
  this.frame(frames,board,'collect','집합 최종 정산 ×'+multiplier,{wins,cells:wins.flatMap(w=>w.cells),marks:Array.from(locked)});
  return{round:this.round(bet,frames,'settled'),locked,board,trigger:Array.from(locked).some(c=>c<5)};
 }
 play(board:string[],bet:number,rng:()=>number):SpinResult{
  this.check(board,bet);const base=this.grow(board,bet,rng);if(!base.trigger)return this.finish([base.round]);const initial=base.locked.size===35?6:3,rounds=[base.round];let last=base;
  this.feature=true;try{for(let left=initial-1;left>=0;left--){const b=this.draw(rng);last.locked.forEach(c=>b[c]=last.board[c]);const next=this.grow(b,bet,rng,last.locked,true);if(left>0&&next.locked.size<35){for(const f of next.round.tumbleFeature!.frames){f.wins=[];if(f.action==='collect')f.caption='신호 집합 보관 · 무료 종료 때 지급';}next.round.wins=[];next.round.payout=0;}next.round.freeSpinsRemaining=left;rounds.push(next.round);last=next;
   if(last.locked.size===35){const f=last.round.tumbleFeature!.frames;this.frame(f,last.board,'collect','전판 완성 · 남은 회전 정산',{wins:left?[this.prize(bet,left*2,Array.from(last.locked))]:[]});last.round.wins=f.flatMap(x=>x.wins);last.round.payout=totalWins(last.round.wins);last.round.freeSpinsRemaining=0;break;}
  }return this.finish(rounds,{freeSpinsAwarded:initial});}finally{this.feature=false;}
 }
 rawSpin(bet:number,rng:()=>number=Math.random){return this.play(this.draw(rng),bet,rng);}
}
