import {Color,Graphics,Node,UITransform} from 'cc';

/** Epic marks a five-reel operation, independent of its numeric value.
 * Keep the backdrop behind a separate face so Cocos never paints it over art. */
export function chaosSymbolFace(symbol:Node,id:string,size:number):Node{
 if(id!=='chaos-crew-x-epic_skull'&&id!=='chaos-crew-x-epic_cat')return symbol;
 const back=new Node('Chaos Epic striped backdrop');back.layer=symbol.layer;symbol.addChild(back);
 back.addComponent(UITransform).setContentSize(size,size);
 const g=back.addComponent(Graphics),pixel=size/32;
 g.fillColor=new Color('#171724');g.rect(-size/2,-size/2,size,size);g.fill();
 g.fillColor=new Color('#ffd866');g.rect(-size/2+pixel,-size/2+pixel,size-2*pixel,size-2*pixel);g.fill();
 // Coarse, clipped diagonal bands on a 32px grid; no texture or RNG is needed.
 g.fillColor=new Color('#171724');
 for(let row=1;row<31;row++){
  for(let col=1;col<31;){
   if((col+row)%8>=4){col++;continue;}
   const run=Math.min(4-(col+row)%8,31-col);
   g.rect((col-16)*pixel,(row-16)*pixel,run*pixel,pixel);col+=run;
  }
 }
 g.fill();
 const face=new Node('Chaos Epic symbol face');face.layer=symbol.layer;symbol.addChild(face);
 face.addComponent(UITransform).setContentSize(size*.9,size*.9);
 return face;
}
