type Table={amount:Float64Array;symbol:Int8Array;count:Uint8Array};
const cache=new WeakMap<number[][],Map<number,Table>>();
/** Cache only native five-symbol pattern evaluations. No random input,
 * prior award or player state participates in this table. */
export function blackoutLineTable(bet:number,pays:number[][]){
 let byBet=cache.get(pays);if(!byBet){byBet=new Map();cache.set(pays,byBet);}let table=byBet.get(bet);if(table)return table;
 const amount=new Float64Array(59049),symbol=new Int8Array(59049).fill(-1),count=new Uint8Array(59049);
 for(let code=0;code<59049;code++){
  let n=code;const word=Array.from({length:5},()=>{const v=n%9;n=Math.floor(n/9);return v;});
  for(let s=0;s<7;s++){let length=0;for(const v of word){if(v!==s&&v!==7)break;length++;}
   if(length>=3){const paid=Math.round(bet*pays[s][length-3]);if(symbol[code]<0||paid>amount[code]){amount[code]=paid;symbol[code]=s;count[code]=length;}}
  }
 }table={amount,symbol,count};byBet.set(bet,table);return table;
}
