import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex as ri,Geometry} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {PRAIRIE_MODEL as M} from './PrairieBuffaloMath';
import {prairieBoard,prairiePurchaseBoard,prairieInputLaw} from './PrairieBuffaloInput';
export class PrairieBuffaloSlot extends ExpansionSlot {
 constructor(spec:ExpansionSlot['spec']){super(spec);const law=prairieInputLaw();this.config.symbols.find(s=>s.id===this.id('wild'))!.weight=M.baseWild;this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=law.scatter;}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(!this.bets.includes(bet)||g.columns!==6||g.rows!==4)throw Error('Invalid prairie wager or geometry');return prairieBoard(this,rng,false);}
 /** Sum every winning path's participating WILD values algebraically. The
  * pure regular path has multiplier1; pure WILD paths belong to symbol0. */
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(opts.wildMode!=='sum')return super.evaluate(board,bet,g,opts);
  if(opts.split||opts.reverse||opts.height||g.heights||opts.awardMultiplier||opts.mode)throw Error('Unsupported prairie WAYS options');
  this.validate(board,bet,g);const wins:Win[]=[];
  for(let n=0;n<8;n++){
   const groups:number[][]=[],regular:number[]=[],wild:number[]=[],values:number[]=[];
   for(let col=0;col<g.columns;col++){const found=Array.from({length:g.rows},(_,row)=>row*g.columns+col).filter(c=>board[c]===this.id(n)||this.isWild(board[c]));if(!found.length)break;groups.push(found);regular.push(found.filter(c=>board[c]===this.id(n)).length);wild.push(found.filter(c=>this.isWild(board[c])).length);values.push(found.filter(c=>this.isWild(board[c])).reduce((s,c)=>s+(opts.values?.[c]||1),0));}
   if(groups.length<3||n!==0&&!regular.some(Boolean))continue;
   let weighted=regular.reduce((p,r)=>p*r,1);
   for(let col=0;col<groups.length;col++){let all=values[col],pure=values[col];for(let c=0;c<groups.length;c++)if(c!==col){all*=regular[c]+wild[c];pure*=wild[c];}weighted+=all-(n?pure:0);}
   const mult=this.unit(n,groups.length)*weighted,amount=Math.round(bet*mult);if(amount>0)wins.push({line:-1,symbol:this.id(n),cells:groups.flat(),amount,multiplier:mult});
  }return{board:[...board],bet,wins,payout:wins.reduce((s,w)=>s+w.amount,0),presentation:this.presentation};
 }
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid prairie wager');return this.purchaseFromResult(this.play(prairiePurchaseBoard(this,rng),bet,rng));}
 play(board:string[],bet:number,rng:()=>number){const trigger=cells(board,this.id('scatter'));if(trigger.length<3)return this.finish([this.ordinary(board,bet,'6×4 · 4096 WAYS')]);
  const awarded=[0,0,0,8,15,25,100][trigger.length],base=this.ordinary(board,bet,'초원 일반 당첨');base.expansionFeature!.frames.push(this.frame(board,'trigger','달 '+trigger.length+'개 · 무료 '+awarded+'회',trigger));const rounds=[base];let remaining=awarded,totalAwarded=awarded;
  while(remaining>0){remaining--;const b=prairieBoard(this,rng,true),v=b.map(s=>s===this.id('wild')?[2,3,5][ri(rng,3)]:0),wilds=cells(b,this.id('wild')),extra=cells(b,this.id('scatter')),frames=[this.frame(b,'reels','야간 초원 · 배수 WILD 착지',[],{values:v})];if(wilds.length)frames.push(this.frame(b,'trigger','배수 개별 확인',wilds,{values:v}),this.frame(b,'effect','당첨 조합별 WILD 배수 합산',wilds,{values:v}));frames.push(this.hit(b,bet,'4096 WAYS · 조합별 배수 적용',this.geometry,{values:v,wildMode:'sum'}));
   const requested=extra.length>=2?[0,0,5,8,15,25,100][extra.length]:0,added=Math.min(requested,240-totalAwarded);if(added){remaining+=added;totalAwarded+=added;frames.push(this.frame(b,'trigger','달 '+extra.length+'개 · 무료 +'+added+'회',extra));}rounds.push(this.round(bet,frames,{freeSpinsRemaining:remaining,freeSpinsAdded:added||undefined}));
  }return this.finish(rounds,{freeSpinsAwarded:awarded,featureOnly:false});
 }
}
