import {BuffaloDiamondSlot} from './BuffaloDiamondSlot';
import {expansionCells as cells,Geometry} from './ExpansionCore';
import {buffaloNativeBoard,buffaloUniform} from './BuffaloNativeInput';
/** Original stacks, coin participation, diamond pot and five free rounds.
 * Only fixed input laws change; winnings are never used to select inputs. */
export class BuffaloNativeSlot extends BuffaloDiamondSlot {
 private nativeFree=false;
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(g.columns!==5||g.rows!==3)throw Error('Invalid Buffalo geometry');return (this as any).stack(buffaloNativeBoard(this.config.id,bet,rng,this.nativeFree),()=>buffaloUniform(rng));}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=(this as any).stack(buffaloNativeBoard(this.config.id,bet,rng,false,true),()=>buffaloUniform(rng));return this.purchaseFromResult(this.play(board,bet,rng));}
 play(board:string[],bet:number,rng:()=>number){
  const input=rng; rng=()=>buffaloUniform(input);
  const base=(this as any).coinRound(board,bet,rng),gates=cells(board,this.id('scatter'));
  if(new Set(gates.map(c=>c%5)).size<3)return this.finish([base]);
  this.nativeFree=true;
  try{return this.freeFromRound(base,bet,rng,5,b=>(this as any).coinRound(b,bet,rng,true),gates);}finally{this.nativeFree=false;}
 }
}
