import {Node,UITransform,Graphics,Color,Label,Vec3,Tween,tween} from 'cc';
import {FlowControl} from './FlowControl';
import {flightTiming,flightScale,flightPoint,FlightKind} from './FeatureFlightProfile';

/** The visible centre of a UI node, expressed in another node's coordinates. */
export function featureTargetPoint(target:Node,space:Node,x=.5,y=.5){
 const targetTransform=target.getComponent(UITransform),spaceTransform=space.getComponent(UITransform)||space.addComponent(UITransform);
 const world=targetTransform
  ?targetTransform.convertToWorldSpaceAR(new Vec3((x-targetTransform.anchorX)*targetTransform.width,(y-targetTransform.anchorY)*targetTransform.height,0))
  :target.worldPosition;
 return spaceTransform.convertToNodeSpaceAR(world);
}

/** Keep the artwork still while moving its transform origin to the visible centre. */
export function centerFlightAnchor(node:Node){
 const transform=node.getComponent(UITransform),parent=node.parent;if(!transform||!parent?.isValid)return;
 const center=featureTargetPoint(node,parent);
 node.setPosition(center.x,center.y,node.position.z);transform.setAnchorPoint(.5,.5);
}

/** A temporary foreground flight; landed artwork is never a collection token. */
export function featureFlight(node:Node,x:number,y:number,overlay:Node,flow?:FlowControl,kind:FlightKind='number',delay=0,ink='#ffe9a5'){
 if(!node.isValid||!node.parent?.isValid||!overlay.isValid)return Promise.resolve();
 const parent=node.parent,transform=parent.getComponent(UITransform)||parent.addComponent(UITransform),overlayTransform=overlay.getComponent(UITransform)||overlay.addComponent(UITransform);
 const from=overlayTransform.convertToNodeSpaceAR(transform.convertToWorldSpaceAR(node.position));
 const to=overlayTransform.convertToNodeSpaceAR(transform.convertToWorldSpaceAR(new Vec3(x,y,0)));
 const sibling=node.getSiblingIndex(),scale=node.scale.clone(),ui=node.getComponent(UITransform)!,label=node.getComponent(Label);
 const factor=flightScale(ui?.width||64,label?.fontSize),distance=Math.hypot(to.x-from.x,to.y-from.y),timing=flightTiming(distance,kind),bend=kind==='step'?0:Math.min(100,Math.max(28,distance*.16));
 const trail=new Node('Feature flight trail');trail.layer=overlay.layer;overlay.addChild(trail);trail.addComponent(UITransform);const g=trail.addComponent(Graphics);
 node.removeFromParent();overlay.addChild(node);node.setPosition(from);node.setScale(scale.x*factor,scale.y*factor,scale.z);
 const clock={t:0};
 return new Promise<void>(resolve=>{
  let finished=false,off=()=>{};
  const finish=()=>{if(finished)return;finished=true;clearTimeout(watchdog);off();Tween.stopAllByTarget(clock);
   if(node.isValid){node.setScale(scale);if(parent.isValid){node.removeFromParent();parent.addChild(node);node.setSiblingIndex(sibling);node.setPosition(x,y);}else node.destroy();}
   if(trail.isValid){trail.removeFromParent();trail.destroy();}resolve();};
  const draw=()=>{
   if(!node.isValid||!overlay.isValid||!parent.isValid){finish();return;}
   const p=flightPoint(from,to,clock.t,bend);node.setPosition(p.x,p.y);
   g.clear();const cx=(.5-(ui?.anchorX??.5))*(ui?.width||0)*scale.x*factor,cy=(.5-(ui?.anchorY??.5))*(ui?.height||0)*scale.y*factor;
   // A short coloured trail follows the same arc as the enlarged object.
   for(let i=4;i>=0;i--){const q=flightPoint(from,to,Math.max(0,clock.t-i*.035),bend),c=new Color(ink);c.a=210-i*32;g.fillColor=c;g.circle(q.x+cx,q.y+cy,Math.max(2,7-i));g.fill();}
   g.strokeColor=new Color(ink);g.lineWidth=3;g.circle(p.x+cx,p.y+cy,16+(clock.t===0||clock.t===1?5:0));g.stroke();
   g.strokeColor=new Color('#fff8dd');g.lineWidth=1.5;g.circle(p.x+cx,p.y+cy,13);g.stroke();
  };
  const motion=tween(clock).delay(delay).call(draw).delay(timing.depart).to(timing.travel,{t:1},{easing:'sineInOut',onUpdate:draw}).delay(timing.arrive).call(finish);
  const watchdog=setTimeout(finish,(delay+timing.depart+timing.travel+timing.arrive+.75)*1000);
  off=flow?flow.track(finish,speed=>motion.timeScale(speed)):()=>{};
  draw();motion.timeScale(flow?.speed??1).start();
 });
}

/** Fly an object's visible centre to a target's visible centre across any parent hierarchy. */
export function featureFlightToNode(node:Node,target:Node,overlay:Node,flow?:FlowControl,kind:FlightKind='number',delay=0,ink='#ffe9a5',targetX=.5,targetY=.5){
 if(!node.isValid||!node.parent?.isValid||!target.isValid)return Promise.resolve();
 const destination=featureTargetPoint(target,node.parent,targetX,targetY);
 centerFlightAnchor(node);
 return featureFlight(node,destination.x,destination.y,overlay,flow,kind,delay,ink);
}
