/** Local fixed input distributions. Awards always use OlympusFeature's paytable.
 * Base and free symbols have separate reel weights; no outcome is accepted,
 * rejected, scaled, or retried based on its payout.
 */
export const OLYMPUS_MODEL={"baseLowSymbol":37.037109375,"baseScatter":3.4980917043701614,"freeScatter":3.8,"freeLowSymbol":76.84837329370316};
export function olympusWeight(id:string,weight:number,free:boolean){
 if(id.endsWith('-scatter'))return free?OLYMPUS_MODEL.freeScatter:OLYMPUS_MODEL.baseScatter;
 if(id.endsWith('-8'))return free?OLYMPUS_MODEL.freeLowSymbol:OLYMPUS_MODEL.baseLowSymbol;
 return weight;
}
