import {SlotMain,SlotConfig,SlotPresentation,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {socialSlotCatalog,SocialSlotSpec} from './SocialSlotCatalog';
import {SocialFeatureProfile,socialFeatureProfiles} from './SocialFeatureProfiles';
import {socialPresentationFor,socialPresentationProfiles} from './SocialPresentationProfiles';
import {makeLines} from './FeatureKit';
import {MoonPower,MOON_PAYS} from './MoonFeature';
import {moonChoiceResults} from './MoonChoices';
import {moonPhaseBoard} from './MoonMath';
import {moonPurchaseResults} from './MoonRefinedPurchase';
/** Guardian choices persist into subsequent paid boards. A fresh purchase
 * uses its own selected guardian and never changes the paid guardian. */
export class MoonSlot extends SlotMain {
 readonly bets=[...BET_LEVELS];readonly columns=5;readonly rows=5;readonly mode='clusters' as const;readonly hasBonus=true;
 readonly spec:SocialSlotSpec;readonly profile:SocialFeatureProfile;readonly presentation:SlotPresentation;
 readonly maxWin:number;readonly paylines:number[][];readonly config:SlotConfig;
 readonly pays:Record<string,number[]>={};readonly regularPays:number[][];
 private moonGuardian:MoonPower=0;private moonChoice:MoonPower=0;
 get bonusChoice(){return this.moonChoice;}
 set bonusChoice(value:number){if(value!==0&&value!==1&&value!==2)throw Error('Invalid guardian choice');this.moonChoice=value;}
 get bonusOptions(){return[{spins:4,m:[1]},{spins:5,m:[1]},{spins:8,m:[1]}];}
 /** The legacy readiness key names the one purchase engine contract. All
  * three native results are reviewed together; choice is not another engine. */
 get bonusCalibrationKey(){return 'moon-princessa:0';}
 get usesReferencePayouts(){return true;}get unlockPriceTenths(){return 1000;}
 get bonusSymbol(){return this.spec.id+'-scatter';}get wildSymbol(){return this.spec.id+'-wild';}
 get bonusTriggerCount(){return 99;}
 constructor(){
  super();this.spec=socialSlotCatalog.find(s=>s.id==='moon-princessa')!;
  const spec=this.spec;this.profile=socialFeatureProfiles[spec.id];this.presentation=socialPresentationProfiles[spec.id]||socialPresentationFor(spec,this.profile);
  this.maxWin=this.profile.maxWin;this.paylines=makeLines(this.rows,this.profile.lineCount);
  const defaults=[[0,0,.5,2,12],[0,0,.4,1.5,8],[0,0,.3,1,5],[0,0,.25,.8,4],[0,0,.2,.6,3],[0,0,.15,.5,2],[0,0,.12,.4,1.5],[0,0,.1,.3,1]];
  this.regularPays=(spec.paytable??defaults.slice(0,spec.symbols.length)).map(row=>[...row]);
  this.config={id:spec.id,title:spec.title,subtitle:spec.subtitle,tag:'TRINITY · 달빛 수호자',color:spec.colors[0],accent:spec.colors[1],description:[spec.hero,...this.profile.rules].join('\n'),symbols:spec.symbols.map((name,i)=>({id:spec.id+'-'+i,name,art:spec.arts[i],color:i<2?spec.colors[1]:spec.colors[2],weight:10+i*2,payout:this.regularPays[i][this.regularPays[i].length-1]}))};
  this.config.symbols.push({id:this.wildSymbol,name:'WILD',art:'star',color:'#fff4bd',weight:0,payout:50});
  spec.symbols.forEach((_,i)=>this.pays[spec.id+'-'+i]=[...this.regularPays[i]]);
 }
 symbolPay(symbol:number,count:number){return count>=3&&count<=5?(symbol===7?MOON_PAYS.wild:symbol===8?MOON_PAYS.mixedPrincess:MOON_PAYS.regular[symbol])?.[count-3]||0:0;}
 private attach(r:SpinResult){r.presentation=this.presentation;r.rounds?.forEach(round=>round.presentation=this.presentation);if(r.bonusTriggerRound)r.bonusTriggerRound.presentation=this.presentation;}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Moon bet');
  const r=moonPurchaseResults(this.spec.id,bet,rng,this.moonChoice);this.attach(r);r.moonChoices?.forEach(v=>this.attach(v));return r;
 }
 private moonSpin(bet:number,rng:()=>number,opening?:number[]):SpinResult{
  const r=moonChoiceResults({id:this.spec.id,bet,rng,guardian:this.moonGuardian,choice:this.moonChoice,opening,board:(source,mode,guardian)=>moonPhaseBoard(source,mode,guardian)});
  this.moonGuardian=r.moonNextGuardian!;this.attach(r);r.moonChoices?.forEach(v=>this.attach(v));return r;
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.moonSpin(bet,rng);}
 spinForPurchase(bet:number,rng:()=>number){return this.spin(bet,rng);}
 demoSpin(bet:number){let seed=99173;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const board=Array.from({length:25},(_,i)=>(i+Math.floor(i/5))%7);board[0]=board[1]=board[2]=0;return this.moonSpin(bet,rng,board);}
 bonusDemoSpin(bet:number){return this.moonSpin(bet,()=>.384721,Array(25).fill(4));}
}
