import{ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri}from'./ExpansionCore';
import{SpinResult,Win}from'./SlotMain';
import{POTION_INPUTS as M,potionUniform}from'./PotionNativeMath';
const pools=new Map<string,{name:string;weight:number}[]>(),totals=new WeakMap<{name:string;weight:number}[],number>();
const potionCodes=new Map([...Array.from({length:8},(_,n)=>['potion-purse-tower-'+n,n]as const),['potion-purse-tower-wild',8]as const,...['scatter','potion','ink'].map(n=>['potion-purse-tower-'+n,9]as const)]);
export class PotionNativeSlot extends ExpansionSlot {
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(g.columns!==5||g.rows!==3||Object.keys(opts).some(k=>k!=='awardMultiplier')||this.config.id!=='potion-purse-tower')return super.evaluate(board,bet,g,opts);
  if(!this.bets.includes(bet)||board.length!==15)throw Error('Invalid expansion board or wager');
  const codes=board.map(id=>{const n=potionCodes.get(id);if(n===undefined)throw Error('Invalid expansion board or wager');return n;}),wins:Win[]=[];
  // Only the first non-WILD symbol and the highest all-WILD prefix can win.
  // Keep symbol0 first, strict greater-than ties and the original round order.
  for(let line=0;line<this.paylines.length;line++){
   const path=this.paylines[line];let lead=9;for(const c of path)if(codes[c]!==8){lead=codes[c];break;}
   let best:Win|undefined;
   for(const symbol of lead>0&&lead<8?[0,lead]:[0]){
    let count=0;for(const c of path){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}
    if(count<3)continue;const mult=this.unit(symbol,count)*(opts.awardMultiplier??1),amount=Math.round(bet*mult);
    if(!best||amount>best.amount)best={line,symbol:this.id(symbol),cells:path.slice(0,count),amount,multiplier:mult};
   }
   if(best&&best.amount>0)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }

 private pool(bet:number,col:number,free:boolean,gated=false){const p=free?M.free:M.paid,high=free?(M.freeHighByBet[bet]??p.high):(M.highByBet[bet]??p.high),gate=col>0&&col<4?p.gate:0,potion=col<=2?p.potion:0,ink=col===2?p.ink:0,rest=1-p.wild-gate-potion-ink,key=[high,p.wild,gate,potion,ink,gated].join('/');let pool=pools.get(key);if(!pool){pool=[{name:'0',weight:rest*high},...Array.from({length:7},(_,i)=>({name:String(i+1),weight:rest*(1-high)/7})),{name:'wild',weight:p.wild},{name:'scatter',weight:gated?0:gate},{name:'potion',weight:potion},{name:'ink',weight:ink}].filter(v=>v.weight>0);pools.set(key,pool);}return pool;}
 private weighted(pool:{name:string;weight:number}[],rng:()=>number){let sum=totals.get(pool);if(sum===undefined){sum=pool.reduce((a,v)=>a+v.weight,0);totals.set(pool,sum);}let u=potionUniform(rng)*sum;for(const v of pool){u-=v.weight;if(u<0)return this.id(v.name);}return this.id(pool[pool.length-1].name);}
 private wizardDraw(bet:number,rng:()=>number,free=false){if(!this.bets.includes(bet))throw Error('Invalid bet');const b:string[]=[],gates=new Set<number>();for(let c=0;c<15;c++){const col=c%5,id=this.weighted(this.pool(bet,col,free,gates.has(col)),rng);b.push(id);if(id===this.id('scatter'))gates.add(col);}return b;}
 draw(bet:number,rng:()=>number){return this.wizardDraw(bet,rng);}
 private potionLines(b:string[]){return this.paylines.filter(line=>line.slice(0,3).every(c=>b[c]===this.id('potion')));}
 private picks(b:string[],bet:number,rng:()=>number,kind:'potions'|'ink',lines=1,scale=1){
  const values:number[]=[];let completed=false;
  if(kind==='ink')values.push(2+ri(rng,19));else{
   let sum=0;for(let pick=0;pick<7;pick++){if(ri(rng,5)===0){values.push(0);break;}const value=Math.min([10,20,30,50,70,90,100][ri(rng,7)],650-sum);values.push(value);sum+=value;if(pick===6)completed=true;}
  }
  const initial=kind==='potions'?10:0,clearBonus=completed?100:0,total=initial+clearBonus+values.reduce((n,v)=>n+v,0),multiple=kind==='potions'?total*lines/50:total*30/50;
  const win=this.prize(b,bet,multiple*scale,cells(b,this.id(kind==='potions'?'potion':'ink')),kind==='potions'?'물약 선택 보상':'숨은 잉크 보상');
  return this.frame(b,'reveal',kind==='potions'?'물약을 선택하세요':'잉크를 눌러 상금을 공개하세요',[],{picks:{kind,initial,values,completed,clearBonus},wins:win.wins});
 }
 private freeRounds(b:string[],bet:number,rng:()=>number,count:number,base:SpinResult){
  const entry=this.prize(b,bet,2*30/50,cells(b,this.id('scatter')),'무료 여행 진입 상금');const rounds=[base,this.round(bet,[entry])];let left=count,awarded=count;
  while(left>0){left--;const raw=this.wizardDraw(bet,rng,true),fs=[this.frame(raw,'reels','물약 탑 무료 회전'),this.hit(raw,bet,'무료 당첨 ×3',this.geometry,{awardMultiplier:3})],lines=this.potionLines(raw),ink=cells(raw,this.id('ink')).filter(c=>c%5===2);
   if(lines.length)fs.push(this.picks(raw,bet,rng,'potions',lines.length,3));else if(ink.length)fs.push(this.picks(raw,bet,rng,'ink',1,3));
   const added=[1,2,3].every(col=>cells(raw,this.id('scatter')).some(c=>c%5===col))?Math.min(count,120-awarded):0;if(added){left+=added;awarded+=added;fs.push(this.frame(raw,'trigger','추가 무료 +'+added,cells(raw,this.id('scatter'))));}
   rounds.push(this.round(bet,fs,{freeSpinsRemaining:left,freeSpinsAdded:added||undefined}));
  }return this.finish(rounds,{freeSpinsAwarded:count,featureOnly:false});
 }
 play(b:string[],bet:number,rng:()=>number){
  const base=this.ordinary(b,bet,'30라인 · 물약 금고'),scatter=cells(b,this.id('scatter')),lines=this.potionLines(b),ink=cells(b,this.id('ink')).filter(c=>c%5===2);
  if([1,2,3].every(col=>scatter.some(c=>c%5===col))){base.expansionFeature!.frames.push(this.frame(b,'trigger','가운데 3릴 표식 · 무료 15회',scatter));return this.freeRounds(b,bet,rng,15,base);}
  if(lines.length||ink.length){const kind=lines.length?'potions':'ink';base.expansionFeature!.frames.push(this.frame(b,'trigger',lines.length?'물약 3개 라인 · 선택 보너스':'가운데 릴 잉크 · 숨은 보상',lines.length?lines.flatMap(line=>line.slice(0,3)):ink));return this.finish([base,this.round(bet,[this.picks(b,bet,rng,kind,lines.length||1)])]);}
  const mystery=ri(rng,1000);
  if(mystery<M.mysteryWild*1000){const after=[...b],targets=Array.from({length:15},(_,c)=>c),changed:number[]=[];for(let n=2+ri(rng,4);n>0;n--){const c=targets.splice(ri(rng,targets.length),1)[0];changed.push(c);after[c]=this.id('wild');}return this.finish([this.round(bet,[this.frame(after,'reels','마법사 · WILD 2~5개 고정',[],{held:changed}),this.frame(after,'effect','마법사 WILD 착지',changed),this.hit(after,bet)])]);}
  if(mystery<(M.mysteryWild+M.mysteryWheel)*1000){const values=[2,4,10,20,40,200,5,10,15,20],selected=ri(rng,10),labels=values.map((v,i)=>i>=6?'FREE '+v:'×'+v),frame=this.frame(b,'reveal','신비의 마법 휠',[],{wheel:{label:'신비의 마법 휠',values,selected,labels,unit:'mixed',stage:'first'}});base.expansionFeature!.frames.push(this.frame(b,'trigger','마법사의 신비 휠',[]));if(selected>=6){base.expansionFeature!.frames.push(frame);return this.freeRounds(b,bet,rng,values[selected],base);}return this.finish([base,this.round(bet,[frame,this.prize(b,bet,values[selected],[],'신비 휠 상금')])]);}
  return this.finish([base]);
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const positions=new Set<number>(),q=1-M.paid.gate;
  for(const col of[1,2,3]){let u=potionUniform(rng)*(1+q+q*q),row=2;for(let r=0;r<3;r++){u-=q**r;if(u<0){row=r;break;}}positions.add(row*5+col);}
  const board=Array.from({length:15},(_,c)=>positions.has(c)?this.id('scatter'):this.weighted(this.pool(bet,c%5,false,true),rng));
  const base=this.ordinary(board,bet,'가운데 3릴 표식 · 독립 무료 15회');base.expansionFeature!.frames.push(this.frame(board,'trigger','독립 물약 무료 15회',cells(board,this.id('scatter'))));
  return this.purchaseFromResult(this.freeRounds(board,bet,rng,15,base));
 }

}
