import {Win} from './SlotMain';
/** Fixed6×5 numeric DFS; preserve original ordered up/down/left/right LIFO
 * groups and unit arithmetic. Synchronous scratch storage avoids allocating
 * stacks/cell arrays for small nonpaying components; no RNG is consumed. */
export function createGlyphClusterEvaluator(ids:string[],wild:string,unit:(symbol:number,count:number)=>number){
 if(ids.length!==6)throw Error('Invalid Glyph symbol table');
 const units=ids.map((_,symbol)=>Array.from({length:31},(_,count)=>unit(symbol,count))),symbolById=new Map(ids.map((id,symbol)=>[id,symbol]));
 const neighbors=Array.from({length:30},(_,cell)=>[...(cell>=6?[cell-6]:[]),...(cell<24?[cell+6]:[]),...(cell%6?[cell-1]:[]),...(cell%6<5?[cell+1]:[])]);
 const stack=new Uint8Array(30),ordered=new Uint8Array(30);
 return (board:string[],bet:number,multiplier=1):Win[]=>{
  if(board.length!==30)throw Error('Invalid Glyph graph');
  const masks=[0,0,0,0,0,0];let wildMask=0;
  for(let cell=0;cell<30;cell++){const value=board[cell];if(value===wild)wildMask|=1<<cell;else{const symbol=symbolById.get(value);if(symbol!==undefined)masks[symbol]|=1<<cell;}}
  const wins:Win[]=[];
  for(let symbol=0;symbol<6;symbol++){
   let remaining=masks[symbol]|wildMask;
   while(remaining){
    const first=remaining&-remaining;stack[0]=31-Math.clz32(first);let top=1,size=0,component=first;remaining^=first;
    while(top){
     const cell=stack[--top];ordered[size++]=cell;const adjacent=neighbors[cell];
     for(let j=0;j<adjacent.length;j++){const neighbor=adjacent[j],bit=1<<neighbor;if(remaining&bit){remaining^=bit;component|=bit;stack[top++]=neighbor;}}
    }
    if(size>=5&&(component&masks[symbol]))wins.push({line:-1,symbol:ids[symbol],cells:Array.from(ordered.subarray(0,size)),amount:bet*units[symbol][size]*multiplier,multiplier});
   }
  }return wins;
 };
}
