export const PLAYER_NAME_MAX_LENGTH=12;
// Keep this list explicit and reviewable. Avoid ambiguous short English fragments
// (such as "ass") that would reject ordinary names like Cassandra.
const prohibitedWords=[
 '시발','씨발','씨팔','씨바','씹새','개새끼','새끼','병신','븅신','지랄','좆','존나','보지','자지','섹스','강간',
 'fuck','shit','bitch','asshole','bastard','dickhead','motherfucker','nigger','nigga','faggot',
];
function prohibitedName(key:string){
 // Separators, inserted digits and common Latin substitutions must not bypass
 // the list. Check both forms so legitimate digits retain their display value.
 const letters=key.replace(/[0-9_]/g,'');
 const substitutions:Record<string,string>={'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t'};
 const leet=key.replace(/_/g,'').replace(/[013457]/g,digit=>substitutions[digit]);
 return [letters,leet].some(form=>prohibitedWords.some(word=>form.includes(word))||/^cunt|cunt$/.test(form));
}
/** Case-insensitive, NFC-normalized names; errors are stable localization tags. */
export function playerName(value:string){
 const display=value.normalize('NFC').trim();
 if(!display)throw Error('profile.name.error.required');
 if(!/^[A-Za-z0-9가-힣_]+$/.test(display))throw Error('profile.name.error.characters');
 if(display.length>PLAYER_NAME_MAX_LENGTH)throw Error('profile.name.error.maximum');
 const key=display.toLowerCase();
 if(prohibitedName(key))throw Error('profile.name.error.prohibited');
 const hangul=(display.match(/[가-힣]/g)||[]).length,alphanumeric=(display.match(/[A-Za-z0-9]/g)||[]).length;
 if(hangul*2+alphanumeric<6)throw Error('profile.name.error.minimum');
 return {display,key};
}
export function canUseName(owner:string|undefined,uid:string){return !owner||owner===uid;}
