/** Native fixed inputs. These laws are selected before any award is evaluated. */
export const MAGNET_TAPE_MODEL={baseHigh:2.10,baseWild:0.5768319222683385,purchaseHigh:2,purchaseWild:.9,baseChartWild:.1294,purchaseChartWild:0.1296086848098476,recordUnit:.4};
export function magnetUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Magnet uniform');return u;}
export const magnetRoles=['0','1','2','3','4','5','wild','money','magnet','boost'];
function weights(purchased:boolean){const m=MAGNET_TAPE_MODEL;return [12*(purchased?m.purchaseHigh:m.baseHigh),12,12,12,12,12,purchased?m.purchaseWild:m.baseWild,1,1.2,.7];}
const pools=new Map<string,{weights:number[];total:number}>();
function pool(purchased:boolean){const w=weights(purchased),key=w.join(',');let p=pools.get(key);if(!p){p={weights:w,total:w.reduce((a,b)=>a+b,0)};pools.set(key,p);}return p;}
export function magnetSymbol(id:string,rng:()=>number,purchased=false){const p=pool(purchased);let r=magnetUniform(rng)*p.total;for(let i=0;i<p.weights.length;i++){r-=p.weights[i];if(r<0)return id+'-'+magnetRoles[i];}return id+'-boost';}
const gates=new Map<string,{rows:{count:number;mass:number}[];total:number}>();
/** Exact iid opening law conditioned on >=3 WILDs. No winning-cluster condition. */
export function magnetPurchaseBoard(id:string,rng:()=>number){
 const p=pool(true),wild=p.weights[6]/p.total,key=String(wild);let gate=gates.get(key);
 if(!gate){const rows=[];let total=0;for(let count=3;count<=36;count++){let choose=1;for(let i=1;i<=count;i++)choose*= (37-i)/i;const mass=choose*wild**count*(1-wild)**(36-count);rows.push({count,mass});total+=mass;}gate={rows,total};gates.set(key,gate);}
 let r=magnetUniform(rng)*gate.total,count=36;for(const row of gate.rows){r-=row.mass;if(r<0){count=row.count;break;}}
 const cells=Array.from({length:36},(_,i)=>i);for(let i=0;i<count;i++){const at=i+Math.floor(magnetUniform(rng)*(36-i));[cells[i],cells[at]]=[cells[at],cells[i]];}const held=new Set(cells.slice(0,count)),plain=p.total-p.weights[6];
 return Array.from({length:36},(_,cell)=>{if(held.has(cell))return id+'-wild';let r=magnetUniform(rng)*plain;for(let i=0;i<p.weights.length;i++){if(i===6)continue;r-=p.weights[i];if(r<0)return id+'-'+magnetRoles[i];}return id+'-5';});
}
