import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {RELIC_MODEL,relicCellInput,relicUniform} from './RelicMath';
/** Discovery Rush structure; local weights, seven-coin threshold and fixed regional awards. */
export const RELIC_ZONES=[{columns:[0,1,2],award:12},{columns:[1,2,3],award:12},{columns:[2,3,4],award:12},{columns:[0,1,2,3],award:40},{columns:[1,2,3,4],award:40},{columns:[0,1,2,3,4],award:150}];
export class RelicDiscoverySlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){
  super(spec);this.config.description='5×3 · 50라인 · 왼쪽부터 연결\n코인 7개 이상: 고정 리스핀 4회. 새 코인이 멈출 때마다 남은 횟수를 4회로 복구합니다.\n연속 3릴·4릴·5릴을 코인으로 모두 채우면 구역 상금. 완성한 최고 등급 한 개와 코인 상금을 종료 때 한 번 지급합니다.\n잭팟은 고정 로컬 상금입니다. 구매는 일반 상금 없이 독립 코인 보너스로 진입합니다.';
  this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=14;
  for(const name of ['chest','portrait','minor','major'])this.config.symbols.push({id:this.id(name),name,color:'#efd08c',weight:0,payout:0});
  const seen=new Set(this.paylines.map(x=>x.join(',')));for(let code=0;this.paylines.length<50;code++){let n=code;const line=Array.from({length:5},(_,c)=>{const r=n%3;n=Math.floor(n/3);return r*5+c;});if(!seen.has(line.join(','))){seen.add(line.join(','));this.paylines.push(line);}}
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-discovery';}
 get bonusTriggerCount(){return 7;}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let r=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){r-=s.weight;if(r<0)return s.id;}return pool[pool.length-1].id;}
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');return Array.from({length:15},()=>this.id(relicCellInput(bet,rng)));}
 private coin(rng:()=>number){const r=relicUniform(rng);return r<.6?1:r<.8?2:r<.9?3:r<.96?5:r<.99?10:25;}
 private rush(board:string[],bet:number,rng:()=>number,base:SpinResult){
  const held=new Map<number,number>(),rounds=[base],snapshots:ExpansionFrame[]=[];let left=4;
  for(const c of cells(board,this.id('scatter')))held.set(c,this.coin(rng));
  const complete=()=>RELIC_ZONES.map(z=>Array.from({length:15},(_,c)=>c).filter(c=>z.columns.includes(c%5)).every(c=>held.has(c))?1:0);
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],previous=Array.from(held.keys()))=>{
   const b=Array.from({length:15},(_,c)=>held.has(c)?this.id('scatter'):''),f=this.frame(b,action,caption,focus,{held:previous,remaining:left,panel:{label:'DISCOVERY',values:complete(),columns:6}});snapshots.push(f);return f;
  };
  rounds.push(this.round(bet,[frame('state','코인 고정 · 리스핀 4회')]));
  while(left>0&&held.size<15){
   left--;const previous=Array.from(held.keys()),landed:number[]=[];
   for(let c=0;c<15;c++)if(!held.has(c)&&relicUniform(rng)<RELIC_MODEL.landing){held.set(c,this.coin(rng));landed.push(c);}
   const fs=[frame('reels','빈칸만 탐험',[],previous)];
   if(landed.length){left=4;fs.push(frame('effect','새 코인 고정 · 4회 복구',landed));}
   fs.push(frame('state','남은 탐험 '+left+'회'));rounds.push(this.round(bet,fs));
  }
  left=0;
  const awards=new Map<number,Win>();for(const [cell,value]of held)awards.set(cell,{line:-1,symbol:this.id('scatter'),cells:[cell],amount:bet*value,multiplier:value});
  const fs:ExpansionFrame[]=[];const filled=complete(),highest=filled.lastIndexOf(1);
  if(highest>=0){const zone=RELIC_ZONES[highest],area=Array.from(held.keys()).filter(c=>zone.columns.includes(c%5));fs.push(frame('trigger','탐험 구역 완성 · '+['MINOR','MINOR','MINOR','MAJOR','MAJOR','GRAND'][highest],area));const shown=frame('win','최고 구역 상금 한 번 지급',area);shown.wins=[{line:-1,symbol:this.id('wild'),cells:[...area],amount:bet*zone.award,multiplier:zone.award}];fs.push(shown);}
  const paid=frame('win','발굴 코인 합계 · 한 번 지급',Array.from(held.keys()));paid.wins=Array.from(awards.values());fs.push(paid);rounds.push(this.round(bet,fs));
  for(const f of snapshots)f.coinAwards=cells(f.board,this.id('scatter')).map(cell=>({cell,win:awards.get(cell)!}));
  return this.finish(rounds,{featureOnly:true});
 }
 play(board:string[],bet:number,rng:()=>number){this.validate(board,bet,this.geometry);const base=this.ordinary(board,bet),found=cells(board,this.id('scatter'));if(found.length<7)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','코인 '+found.length+'개 · 발견 리스핀',found));return this.rush(board,bet,rng,base);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // Exact binomial coin count conditional on >=7; uniform held positions.
  const pool=this.config.symbols.filter(s=>s.weight>0),p=RELIC_MODEL.coin,weights:number[]=[];let choose=1;
  for(let n=0;n<=15;n++){if(n>=7)weights.push(choose*p**n*(1-p)**(15-n));choose=choose*(15-n)/(n+1);}
  let roll=relicUniform(rng)*weights.reduce((n,v)=>n+v,0),count=15;for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0){count=i+7;break;}}
  const positions=Array.from({length:15},(_,c)=>c);for(let i=14;i>0;i--){const j=randomIndex(rng,i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
  const rich=new Set(positions.slice(0,count)),plain=pool.filter(s=>s.id!==this.id('scatter')),board=positions.map((_,c)=>rich.has(c)?this.id('scatter'):this.weighted(rng,plain));
  const base=this.round(bet,[this.frame(board,'trigger','독립 발견 리스핀 구매',Array.from(rich))]);return this.purchaseFromResult(this.rush(board,bet,rng,base));
 }
}
