import {ExpansionSlot,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {drawReelBoard} from './ReelScatter';
import {SUNSET_MODEL,SUNSET_PRIZES,SUNSET_FREE_COUNTS,sunsetModelForBet} from './SunsetMath';
export class SunsetRoadSlot extends ExpansionSlot {
 private roadBoard(bet:number,rng:()=>number,free=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const model=sunsetModelForBet(bet),symbols=this.config.symbols.filter(s=>s.weight>0).map(s=>({...s,weight:s.id===this.id('0')?(free?model.freeHigh:model.baseHigh):s.id===this.id('scatter')?(free?0:model.baseScatter):s.weight}));
  return drawReelBoard(this.columns,this.rows,symbols,this.id('scatter'),rng);
 }
 draw(bet:number,rng:()=>number){return this.roadBoard(bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  const board=this.roadBoard(bet,rng,true),columns=Array.from({length:5},(_,col)=>col);
  for(let i=0;i<3;i++){const selected=i+ri(rng,5-i);[columns[i],columns[selected]]=[columns[selected],columns[i]];board[columns[i]+5*ri(rng,3)]=this.id('scatter');}
  return this.purchaseFromResult(this.play(board,bet,rng));
 }
 play(b:string[],bet:number,rng:()=>number){
  const found=cells(b,this.id('scatter')),base=this.ordinary(b,bet);if(found.length<3)return this.finish([base]);
  base.expansionFeature!.frames.push(this.frame(b,'trigger','여행 표식 3개 · 로드 보너스',found));
  const branch=rng(),kind=branch<SUNSET_MODEL.freeBranchChance?2:Math.min(1,Math.floor((branch-SUNSET_MODEL.freeBranchChance)/(1-SUNSET_MODEL.freeBranchChance)*2)),rounds=[base],values=SUNSET_PRIZES;let last=[...b],free=0;
  const wheel=(label:string,stage:'first'|'encore',unit:'prize'|'free',wedges:number[])=>{
   const selected=ri(rng,wedges.length),frame=this.frame(last,'reveal',label,[],{wheel:{label,values:[...wedges],selected,unit,stage}});
   return {selected,value:wedges[selected],frame};
  };
  if(kind===2){
   const count=wheel('무료 여행 휠','first','free',SUNSET_FREE_COUNTS);free=count.value;
   rounds.push(this.round(bet,[count.frame]));
   for(let left=free-1;left>=0;left--){last=this.roadBoard(bet,rng,true);const r=this.ordinary(last,bet,'로드 무료 회전');r.freeSpinsRemaining=left;rounds.push(r);}
  }else{
   const turns=kind===1?3:1;
   for(let turn=0;turn<turns;turn++){
    const spin=wheel(kind===1?'연속 여행 휠 '+(turn+1)+'/3':'여행 상금 휠','first','prize',values);
    rounds.push(this.round(bet,[spin.frame,this.prize(last,bet,spin.value,found,'첫 여행 휠 상금')]));
   }
  }
  const encore=wheel('마지막 보너스 휠','encore','prize',values);
  rounds.push(this.round(bet,[this.frame(last,'state','첫 보너스 종료 · 마지막 휠로 연결'),encore.frame,this.prize(last,bet,encore.value,found,'마지막 휠 별도 상금')]));
  return this.finish(rounds,{featureOnly:free===0,...(free?{freeSpinsAwarded:free}:{})});
 }
}
