import {MOON_PAYS,MOON_INITIAL_SPINS,MoonPower,moonRound,moonFreeSequence,MoonResolvedRound} from './MoonFeature';
import {MOON_REFINED_MODEL as MOON_MODEL,moonRefinedPhaseBoard as moonPhaseBoard} from './MoonRefinedMath';
import {moonResult} from './MoonResult';
import type {SpinResult} from './SlotMain';
/** A local purchase gate, not a provider purchase mode. A randomly oriented
 * family of full-clear boards is sampled directly: five homogeneous lines,
 * each with seven possible symbols. Conditional weights are the product of
 * the fixed base cell weights. There is no paid-spin search or paid entry win. */
const gatePools=new Map<string,{weights:number[][];tail:(line:number,a:number,b:number)=>number}>();
function gateInput(vertical:boolean){
 const key=[vertical,MOON_MODEL.base.premium,MOON_MODEL.base.bias].join(':');let pool=gatePools.get(key);if(pool)return pool;
 const weights=Array.from({length:5},(_,line)=>Array.from({length:7},(_,symbol)=>Array.from({length:5},(_,i)=>vertical?i*5+line:line*5+i).reduce((v,cell)=>{const phase=(cell%5+2*Math.floor(cell/5))%7;return v*(symbol<3?8*MOON_MODEL.base.premium:19)*((symbol===phase||symbol===(phase+1)%7)?MOON_MODEL.base.bias:1);},1)));
 const memo=new Map<string,number>();
 const tail=(line:number,a:number,b:number):number=>{
  if(line===5)return 1;const id=[line,a,b].join(':');if(memo.has(id))return memo.get(id)!;
  let total=0;for(let symbol=0;symbol<7;symbol++)if(!(a===b&&b===symbol)&&!(a>=0&&a<3&&b<3&&symbol<3))total+=weights[line][symbol]*tail(line+1,b,symbol);
  memo.set(id,total);return total;
 };pool={weights,tail};gatePools.set(key,pool);return pool;
}
export function moonPurchaseGate(rng:()=>number){
 const draw=()=>{const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid Moon random input');return v;};
 const vertical=draw()<.5,board=Array<number>(25),pool=gateInput(vertical);let a=-1,b=-1;
 for(let line=0;line<5;line++){
  // No three-symbol cross run can leave a new WILD in this gate. This is a
  // declared input constraint, evaluated before any award or feature result.
  const weights=pool.weights[line].map((w,symbol)=>a===b&&b===symbol||a>=0&&a<3&&b<3&&symbol<3?0:w*pool.tail(line+1,b,symbol));
  let roll=draw()*weights.reduce((v,w)=>v+w,0),symbol=6;for(let i=0;i<7;i++){roll-=weights[i];if(roll<0){symbol=i;break;}}
  for(let i=0;i<5;i++)board[vertical?i*5+line:line*5+i]=symbol;a=b;b=symbol;
 }
 return board;
}
export function moonPurchaseResults(id:string,bet:number,rng:()=>number,choice:MoonPower):SpinResult{
 const opening=moonPurchaseGate(rng),entry=moonRound({board:opening,pays:MOON_PAYS,bet,limit:0,rng,multiplier:1});
 if(!entry.cleared||entry.payout!==0||entry.multiplier!==2)throw Error('Invalid Moon purchase gate');
 const gate:MoonResolvedRound={...entry,opening,mode:'base',guardian:choice,freeSpinsAdded:0,freeSpinsRemaining:0,clearAward:0};
 const trigger=moonResult(id,bet,gate);trigger.roundLabel='BONUS TRIGGER';
 const draws:number[]=[];
 const branch=(selected:MoonPower)=>{
  let index=0;const source=()=>{if(index===draws.length){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Moon random input');draws.push(value);}return draws[index++];};
  const sequence=moonFreeSequence({bet,choice:selected,rng:source,pick:()=>0,multiplier:entry.multiplier,limit:bet*5000,board:(phase,guardian)=>moonPhaseBoard(source,phase,guardian,true),settle:amount=>Math.floor(amount)+(source()<amount%1?1:0)});
  const rounds=sequence.rounds.map(round=>moonResult(id,bet,round)),last=rounds[rounds.length-1];
  return{bet,board:[...last.board],rounds,wins:rounds.flatMap(round=>round.wins),payout:sequence.payout,freeSpinsAwarded:MOON_INITIAL_SPINS[selected],featureName:'달빛 수호자의 축복',bonusTriggerRound:{...trigger,moonFeature:{...trigger.moonFeature!,guardian:selected}}} as SpinResult;
 };
 const selected=branch(choice),choices=([0,1,2] as MoonPower[]).map(c=>c===choice?selected:branch(c));
 return{...selected,moonChoices:choices,moonDefaultChoice:choice};
}
