import {JoeyPuzzleSlot} from './JoeyPuzzleSlot';
import {EXPANSION_SPECS} from './ExpansionCatalog';
/** Offline witnesses include actual saved progress from complete paid prefixes.
 * No fixture boards, forced completion or production RNG selection. */
export const JOEY_AUDIT_SEEDS:Record<string,{seed:number;progress:number[]}>={empty:{seed:11322961,progress:[0,0]},multi:{seed:1717834041,progress:[0,0]},newPiece:{seed:1143408321,progress:[0,0]},duplicate:{seed:2908710553,progress:[212,0]},free0:{seed:1782111923,progress:[255,0]},free1:{seed:131548248,progress:[255,1]},free2:{seed:1659974079,progress:[509,2]}};
export function joeyAudit(params:URLSearchParams){
 const slot=new JoeyPuzzleSlot(EXPANSION_SPECS.find(s=>s.id==='joey-puzzle-trail')!),outcome=params.get('audit-joey-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi','free':'free0'} as Record<string,string>)[outcome]||outcome,witness=JOEY_AUDIT_SEEDS[kind];
 if(witness){const spin=(bet:number)=>{slot.setProgress({[slot.config.id+':'+bet]:witness.progress});let seed=witness.seed;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const r=slot.spin(bet,rng);if(kind.startsWith('free')&&(r.rounds?.length!==7||r.freeSpinsAwarded!==6))throw Error('Stale Joey completion witness');return r;};slot.demoSpin=spin;if(kind.startsWith('free'))slot.bonusDemoSpin=spin;}
 return slot;
}
