/** Native per-symbol, per-length WAYS paytable; never an output multiplier. */
export const PRISM_INPUTS={paidHigh:.2912,freeHigh:0.5107641846608408,paidGate:.01073386201859701,freeGate:.004,wild:.003,
 paytable:[[.00008,.001,.002],[.00007,.00085,.0018],[.00006,.0007,.0016],[.00005,.0006,.0014],[.00004,.0005,.0012],[.00003,.0004,.001]]};
export function prismUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Prism RNG');return u;}
export function prismConditionalOpening(slot:{id:(s:string|number)=>string;pick:(rng:()=>number)=>string},rng:()=>number){
 const M=PRISM_INPUTS,heights=[3,4,4,4,3],active=Array.from({length:40},(_,c)=>c).filter(c=>Math.floor(c/5)>=8-heights[c%5]),memo=new Map<string,number>();
 const probability=(left:number,need:number):number=>{if(need<=0)return 1;if(left<need)return 0;const key=left+','+need,k=memo.get(key);if(k!==undefined)return k;const p=M.paidGate*probability(left-1,need-1)+(1-M.paidGate)*probability(left-1,need);memo.set(key,p);return p;};
 let need=3;const board=Array(40).fill(slot.id('void'));
 active.forEach((cell,i)=>{const left=active.length-i-1,total=probability(left+1,need),chance=M.paidGate*probability(left,need-1)/total,u=prismUniform(rng);if(u<chance){board[cell]=slot.id('scatter');need--;}else board[cell]=slot.pick(()=>M.paidGate+(1-M.paidGate)*prismUniform(rng));});
 [1,2,3].forEach(c=>board[c]=slot.id(Math.floor(prismUniform(rng)*6)));return board;
}
