import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {CellDrop,SpinResult,Win} from './SlotMain';
import {RENAISSANCE_INPUTS as M,renaissanceUniform} from './RenaissanceNativeMath';
// The law depends only on fixed native inputs, reel eligibility and phase.
// Cache all inputs in the key; no player, payout or previous result enters it.
const renaissancePools=new Map<string,{id:string;weight:number}[]>();
const renaissancePoolTotals=new WeakMap<{id:string;weight:number}[],number>();
const renaissanceCodes=new Map([...Array.from({length:8},(_,n)=>['renaissance-gem-fall-'+n,n] as const),['renaissance-gem-fall-wild',8] as const,...['scatter','ruby-medal','emerald-medal','sapphire-medal'].map(s=>['renaissance-gem-fall-'+s,9] as const)]);
export class RenaissanceNativeSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);this.paylines.splice(20);for(const [i,name]of ['ruby-medal','emerald-medal','sapphire-medal'].entries())this.config.symbols.push({id:this.id(name),name,color:['#e87676','#74bf95','#71bbee'][i],weight:0,payout:0});}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-tumble';}
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(g.columns!==5||g.rows!==3||Object.keys(opts).length||this.config.id!=='renaissance-gem-fall')return super.evaluate(board,bet,g,opts);
  if(!this.bets.includes(bet)||board.length!==15)throw Error('Invalid expansion board or wager');
  const codes=board.map(id=>{const n=renaissanceCodes.get(id);if(n===undefined)throw Error('Invalid expansion board or wager');return n;}),wins:Win[]=[];
  // Only the first non-WILD symbol and the highest all-WILD prefix can win.
  // Keep symbol0 first, strict greater-than ties and the original round order.
  for(let line=0;line<this.paylines.length;line++){
   const path=this.paylines[line];let lead=9;for(const c of path)if(codes[c]!==8){lead=codes[c];break;}
   let best:Win|undefined;
   for(const symbol of lead>0&&lead<8?[0,lead]:[0]){
    let count=0;for(const c of path){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}
    if(count<3)continue;const mult=this.unit(symbol,count),amount=Math.round(bet*mult);
    if(!best||amount>best.amount)best={line,symbol:this.id(symbol),cells:path.slice(0,count),amount,multiplier:mult};
   }
   if(best&&best.amount>0)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private pool(col:number,free:boolean,hasGate=false){
  const gate=!free&&col>2?0:free?M.freeGate:M.paidGate,wild=free||col===0||col===4?0:M.wild,medal=free?M.medal:0,high=free?M.freeHigh:M.paidHigh,rest=1-gate-wild-3*medal;
  const key=[this.config.id,gate,wild,medal,high,hasGate].join('/'),cached=renaissancePools.get(key);if(cached)return cached;
  const pool=[{id:this.id('scatter'),weight:hasGate?0:gate},{id:this.id('wild'),weight:wild},{id:this.id(0),weight:rest*high},...Array.from({length:7},(_,n)=>({id:this.id(n+1),weight:rest*(1-high)/7})),...['ruby-medal','emerald-medal','sapphire-medal'].map(name=>({id:this.id(name),weight:medal}))].filter(v=>v.weight>0);renaissancePools.set(key,pool);renaissancePoolTotals.set(pool,pool.reduce((n,s)=>n+s.weight,0));return pool;
 }
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=renaissanceUniform(rng)*(renaissancePoolTotals.get(pool)??pool.reduce((n,s)=>n+s.weight,0));for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private grid(bet:number,rng:()=>number,free:boolean){if(!this.bets.includes(bet))throw Error('Invalid bet');const b:string[]=[];for(let c=0;c<15;c++)b.push(this.weighted(rng,this.pool(c%5,free,b.some((s,i)=>i%5===c%5&&s===this.id('scatter')))));return b;}
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng,false);}
 private gate(board:string[],free:boolean){if(free)return cells(board,this.id('scatter'));const line=this.paylines.find(line=>line.slice(0,3).every(c=>board[c]===this.id('scatter')));return line?line.slice(0,3):[];}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const prefixes=Array.from(new Set(this.paylines.map(p=>p.slice(0,3).join(',')))).map(k=>k.split(',').map(Number)),q=1-M.paidGate,weighted=prefixes.map(path=>({path,weight:path.reduce((p,c)=>p*q**Math.floor(c/5),1)}));let roll=renaissanceUniform(rng)*weighted.reduce((p,v)=>p+v.weight,0),path=weighted[weighted.length-1].path;for(const item of weighted){roll-=item.weight;if(roll<0){path=item.path;break;}}
  const board=Array.from({length:15},(_,c)=>c%5<3&&path.includes(c)?this.id('scatter'):this.weighted(rng,this.pool(c%5,false,c%5<3)));return this.purchaseFromResult(this.play(board,bet,rng));
 }
 private artRound(input:string[],bet:number,rng:()=>number,free:boolean,remainingAward=300,budget={remaining:bet*this.maxWin}){
  let board=[...input],triggered=false,added=0;const frames:ExpansionFrame[]=[this.frame(board,'reels',free?'무료 보석 낙하 · 특별 보석 3종':'보석이 위에서 낙하')];
  for(let stage=0;budget.remaining>0;stage++){
   const stageStart=frames.length,hit=this.hit(board,bet,'연쇄 '+(stage+1)+' · 20라인 당첨'),gate=this.gate(board,free),removed=new Set(hit.wins.flatMap(w=>w.cells));frames.push(hit);
   if(free)for(const [kind,name]of ['ruby-medal','emerald-medal','sapphire-medal'].entries()){const found=cells(board,this.id(name));if(found.length<3)continue;const f=this.prize(board,bet,[.15,.25,.4][kind]*2**Math.min(4,found.length-3),found,'무료 특별 보석 · 별도 상금');f.wins[0].symbol=this.id(name);frames.push(f);found.forEach(c=>removed.add(c));}
   if(gate.length>=3){if(free){const options=gate.length>=5?[6,8,10,12,15]:gate.length===4?[4,6,8,10]:[2,3,4],n=Math.min(options[ri(rng,options.length)],remainingAward-added);added+=n;if(n)frames.push(this.frame(board,'trigger','보너스 두루마리 · 무료 +'+n+'회',gate));}else{triggered=true;frames.push(this.frame(board,'trigger','첫 세 릴 당첨선 두루마리 · 무료 6회',gate));}gate.forEach(c=>removed.add(c));}
   budget.remaining-=frames.slice(stageStart).reduce((p,f)=>p+f.wins.reduce((v,w)=>v+w.amount,0),0);if(budget.remaining<=0){frames.push(this.frame(board,'state','최대 지급 한도 도달'));break;}if(!removed.size)break;
   const empty=[...board];removed.forEach(c=>empty[c]='');frames.push(this.frame(empty,'remove','당첨 보석 제거',Array.from(removed)));const next=[...board],moves:CellDrop[]=[];
   for(let col=0;col<5;col++){const targets=[col+10,col+5,col],survivors=targets.filter(c=>!removed.has(c));let hasGate=survivors.some(c=>board[c]===this.id('scatter'));targets.forEach((to,i)=>{const from=survivors[i]??col-5*(i-survivors.length+1),symbol=from>=0?board[from]:this.weighted(rng,this.pool(col,free,hasGate));if(symbol===this.id('scatter'))hasGate=true;next[to]=symbol;moves.push({from,to,symbol});});}
   frames.push(this.frame(next,'drop','빈칸으로 보석 낙하',Array.from(removed),{moves}));board=next;
  }
  return{round:this.round(bet,frames,{freeSpinsAdded:added||undefined}),triggered};
 }
 play(board:string[],bet:number,rng:()=>number){const budget={remaining:bet*this.maxWin},base=this.artRound(board,bet,rng,false,300,budget);if(!base.triggered)return this.finish([base.round]);const rounds=[base.round];let left=6,total=6;while(left>0){left--;const item=this.artRound(this.grid(bet,rng,true),bet,rng,true,300-total,budget),added=item.round.freeSpinsAdded||0;left+=added;total+=added;item.round.freeSpinsRemaining=left;rounds.push(item.round);}return this.finish(rounds,{freeSpinsAwarded:6,featureOnly:false});}
}
