import {SpinResult} from './SlotMain';
import {GapSlot,gapCellsOf as cellsOf,gapInteger as integer} from './GapCore';
import {normalizeSlotProgress,SlotProgress} from './Social2230Rules';
import {sparkInput,sparkInputBoard,sparkPurchaseBoard} from './LifeSparkMath';
/** Consecutive occupied reels from the left; both colors count, blue alone
 * becomes sticky. This topology is an explicit local interpretation. */
export function sparkParticipants(board:string[],id:string){const cells:number[]=[];for(let col=0;col<5;col++){const found=[col,col+5,col+10].filter(c=>board[c]===id+'-0'||board[c]===id+'-1');if(!found.length)break;cells.push(...found);}return cells.length>=5?cells:[];}
export class LifeSparkSlot extends GapSlot {
 readonly kind='spark' as const;private progress:SlotProgress={};
 protected purchaseSource():GapSlot{return new LifeSparkSlot();}
 setProgress(input:SlotProgress){this.progress=normalizeSlotProgress(input);}
 readonly config=this.makeConfig('life-spark-laboratory','생명 불꽃 연구소','PERSONAL RESERVE',['초록 불꽃','파랑 불꽃','축전 보석','실험 코일','측정기','유리병','도구','설계도','전류 WILD','점화 표식'],'연속 릴 불꽃5개: 무료5회, 추가 불꽃마다 +5회(최대100). 트리거 파랑만 고정. 보석8개 수집 시 개인 예비 전력 지급·초기화. 베팅별 저장.',[9,6,5,8,10,12,14,16,2,2]);
 protected board(rng:()=>number,bet=this.bets[0]){return sparkInputBoard(this.config.id,sparkInput(bet),rng);}
 spin(bet:number,rng:()=>number=Math.random){return this.play(this.board(rng,bet),bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){return this.play(sparkPurchaseBoard(this.config.id,bet,rng),bet,rng,true);}
 play(board:string[],bet:number,rng:()=>number,purchase=false){const key=this.config.id+':'+bet,state=[...(purchase?[0,0]:(this.progress[key]||[0,0]))],rounds:SpinResult[]=[];
  const make=(b:string[],caption:string,unpaidEntry=false)=>{const line=unpaidEntry?{wins:[]}:this.evaluate(b,bet),jewels=cellsOf(b,this.id(2)),before=[...state];state[0]+=jewels.length;state[1]+=jewels.length;
   const frames=[this.frame(b,caption+' · 보석 '+before[0]+'/8',jewels,before,line.wins)];if(state[0]>=8){const multiplier=state[1]*(1+integer(rng,4)),prize=this.prize(bet,multiplier,jewels);frames.push(this.frame(b,'생명 점화 · 개인 전력 지급',jewels,[state[0],state[1]],unpaidEntry?[]:[prize]));state[0]=0;state[1]=0;frames.push(this.frame(b,'개인 전력 장부 초기화',[],[0,0]));}else if(jewels.length)frames.push(this.frame(b,'전력 보석 적립',jewels,state));
   if(jewels.length){const collected=frames[1];collected.collection={before:before[0],after:before[0]+jewels.length,items:jewels.map(cell=>({cell,value:1}))};}
   return this.round(bet,frames);};
  const participants=sparkParticipants(board,this.config.id),initial=participants.length?Math.min(100,5*(participants.length-4)):0,held=participants.filter(c=>board[c]===this.id(1));rounds.push(make(board,'전력 수집',purchase));
  for(let left=initial-1;left>=0;left--){const b=sparkInputBoard(this.config.id,sparkInput(bet,true),rng);held.forEach(c=>b[c]=this.id('wild'));const r=make(b,'파랑 고정 '+held.length+'개');r.heldAtStart=held.map(cell=>({cell,symbol:this.id('wild'),value:1}));r.freeSpinsRemaining=left;rounds.push(r);}
  if(purchase){const entry=rounds.shift()!;const result=this.finish(rounds,{freeSpinsAwarded:initial,featureOnly:true});return {...result,bonusTriggerRound:{...entry,wins:[],payout:0},progressUpdate:undefined};}
  const result=this.finish(rounds,{freeSpinsAwarded:initial||undefined,featureOnly:false,progressUpdate:{key,values:[...state]}});return result;
 }
}

