import {ExpansionSlot,ExpansionFrame,Geometry,randomIndex as ri} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {HARVEST_INPUTS as M,harvestUniform} from './HarvestNativeMath';
const harvestCodes=new Map([...Array.from({length:8},(_,n)=>['harvest-moon-fiesta-'+n,n] as const),['harvest-moon-fiesta-wild',8] as const,...['scatter','gift-food','gift-honey','gift-pirate','diamond','coin','tnt','bee','bomb','lock'].map(name=>['harvest-moon-fiesta-'+name,9] as const)]);
const harvestPools=new Map<string,{id:string;weight:number}[]>();
const harvestPoolTotals=new WeakMap<{id:string;weight:number}[],number>();
type Prize={symbol:string;raw:number};
type Landing={p:number;c:number;id:string;raw?:number};
/** Official six-gift/ten-respin/four-theme structure. Per-theme prize operations,
 * probabilities and local fixed pots are documented local interpretations. */
export class HarvestNativeSlot extends ExpansionSlot {
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-gifts';}
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(g.columns!==5||g.rows!==3||Object.keys(opts).length||this.config.id!=='harvest-moon-fiesta')return super.evaluate(board,bet,g,opts);
  if(!this.bets.includes(bet)||board.length!==15)throw Error('Invalid expansion board or wager');
  const codes=board.map(id=>{const n=harvestCodes.get(id);if(n===undefined)throw Error('Invalid expansion board or wager');return n;}),wins:Win[]=[];
  // Only the first non-WILD symbol and the highest all-WILD prefix can win.
  // Keep symbol0 first, strict greater-than ties and the original round order.
  for(let line=0;line<this.paylines.length;line++){
   const path=this.paylines[line];let lead=9;for(const c of path)if(codes[c]!==8){lead=codes[c];break;}
   let best:Win|undefined;
   for(const symbol of lead>0&&lead<8?[0,lead]:[0]){
    let count=0;for(const c of path){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}
    if(count<3)continue;const mult=this.unit(symbol,count),amount=Math.round(bet*mult);
    if(!best||amount>best.amount)best={line,symbol:this.id(symbol),cells:path.slice(0,count),amount,multiplier:mult};
   }
   if(best&&best.amount>0)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private gifts=['scatter','gift-food','gift-honey','gift-pirate'];
 private gift(id:string){return this.gifts.findIndex(s=>id===this.id(s));}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let total=harvestPoolTotals.get(pool);if(total===undefined){total=pool.reduce((n,s)=>n+s.weight,0);harvestPoolTotals.set(pool,total);}let roll=harvestUniform(rng)*total;for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private pool(bet:number){const high=M.highByBet[bet]??.54,rest=1-M.gift-M.wild,key=[this.config.id,high,M.gift,M.wild].join('/'),prior=harvestPools.get(key);if(prior)return prior;const pool=[{id:this.id(0),weight:rest*high},...Array.from({length:7},(_,n)=>({id:this.id(n+1),weight:rest*(1-high)/7})),{id:this.id('wild'),weight:M.wild},...this.gifts.map(name=>({id:this.id(name),weight:M.gift/4}))];harvestPools.set(key,pool);return pool;}
 draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const pool=this.pool(bet);return Array.from({length:15},()=>this.weighted(rng,pool));}
 private bonus(b:string[],bet:number,rng:()=>number,base:SpinResult,superBonus:boolean){
  const landing=M[superBonus?'super':'standard'],active=new Set(superBonus?[0,1,2,3]:b.map(id=>this.gift(id)).filter(n=>n>=0)),boards=Array.from({length:4},()=>new Map<number,Prize>()),rounds=[base],snapshots:{f:ExpansionFrame;items:{cell:number;key:string;raw:number}[]}[]=[];
  const global=(p:number,c:number)=>Math.floor(p/2)*30+Math.floor(c/5)*10+p%2*5+c%5,clamp=(n:number)=>Math.min(100000,Math.max(1,n));
  const coin=(p:number,c:number,raw?:number)=>boards[p].set(c,{symbol:this.id('coin'),raw:raw??[1,2,3,5,8][ri(rng,5)]});
  b.forEach((id,c)=>{const p=this.gift(id);if(p>=0)coin(p,c);});
  const frame=(action:ExpansionFrame['action'],caption:string,left:number,highlights:{p:number;c:number}[]=[],temporary:Landing[]=[])=>{
   const board=Array(60).fill(''),held:number[]=[],items:{cell:number;key:string;raw:number}[]=[];
   for(const p of active)for(const [c,t]of boards[p]){const cell=global(p,c);board[cell]=t.symbol;held.push(cell);items.push({cell,key:p+':'+c,raw:t.raw});}
   for(const t of temporary){board[global(t.p,t.c)]=t.id;if(t.raw!==undefined)items.push({cell:global(t.p,t.c),key:t.p+':'+t.c,raw:t.raw});}
   const f=this.frame(board,action,caption,highlights.map(v=>global(v.p,v.c)),{held,remaining:left,cartBoards:{split:true,unlocked:active.size,active:Array.from(active),label:'GIFT'}},{columns:10,rows:6});snapshots.push({f,items});return f;
  };
  rounds.push(this.round(bet,[frame('expand',superBonus?'슈퍼 선물 · 네 판 모두 해금 · 10회':'선물 종류별 시작판 · 리스핀 10회',10)]));
  for(let turn=0;turn<10;turn++){
   const left=9-turn,events:Landing[]=[],unlocks=new Set<number>();
   for(const p of Array.from(active))for(let c=0;c<15;c++){if(boards[p].has(c))continue;const roll=harvestUniform(rng);if(roll<landing.coin)events.push({p,c,id:this.id('coin'),raw:[1,2,3,5,8][ri(rng,5)]});else if(roll<landing.coin+landing.effect)events.push({p,c,id:this.id(['diamond','gift-food','bee','bomb'][p])});else if(roll<landing.coin+landing.effect+landing.unlock){const locked=[0,1,2,3].filter(i=>!active.has(i));if(locked.length){const next=locked[ri(rng,locked.length)];unlocks.add(next);events.push({p,c,id:this.id(this.gifts[next])});}}}
   const fs=[frame('reels','선물 리스핀 '+(turn+1)+'/10',left,[],events)],landed=events.filter(e=>e.id===this.id('coin'));
   for(const e of landed)coin(e.p,e.c,e.raw);if(landed.length)fs.push(frame('effect','선물 상금 고정',left,landed));
   // Unlock gifts are resolved separately, never mistaken for a tomato effect.
   for(const e of events.filter(e=>e.id!==this.id('coin'))){
    if(e.id===this.id('diamond')){const raw=clamp(Array.from(boards[e.p].values()).reduce((n,t)=>n+t.raw,0));boards[e.p].set(e.c,{symbol:e.id,raw});fs.push(frame('collect','광산 다이아몬드 · 같은 판 합산',left,[e]));}
    else if(e.p===1&&e.id===this.id('gift-food')&&!unlocks.has(1)){const add=[1,2,3][ri(rng,3)];for(const t of boards[1].values())t.raw=clamp(t.raw+add);coin(1,e.c,add);fs.push(frame('effect','수확 음식 · 같은 판 상금 +'+add,left,Array.from(boards[1].keys()).map(c=>({p:1,c}))));}
    else if(e.id===this.id('bee')){const empty=Array.from({length:15},(_,c)=>c).filter(c=>!boards[2].has(c)),targets:{p:number;c:number}[]=[];for(let i=0;i<3&&empty.length;i++){const c=empty.splice(ri(rng,empty.length),1)[0];coin(2,c);targets.push({p:2,c});}fs.push(frame('effect','꿀벌 · 빈칸 세 곳에 상금',left,targets,[e]));}
    else if(e.id===this.id('bomb')){const multiplier=[2,3,5][ri(rng,3)],targets:{p:number;c:number}[]=[];for(const [c,t]of boards[3])if(Math.abs(c%5-e.c%5)<=1&&Math.abs(Math.floor(c/5)-Math.floor(e.c/5))<=1){t.raw=clamp(t.raw*multiplier);targets.push({p:3,c});}fs.push(frame('effect','해적 폭탄 · 인접 상금 ×'+multiplier,left,targets,[e]));}
   }
   for(const p of unlocks){active.add(p);fs.push(frame('reveal','새 선물 · '+(p+1)+'번 판 해금',left));}
   fs.push(frame('state','남은 리스핀 '+left+'회',left));rounds.push(this.round(bet,fs));
   if(Array.from(active).every(p=>boards[p].size===15))break;
  }
  const awards=new Map<string,Win>();for(const p of active)for(const [c,t]of boards[p])awards.set(p+':'+c,{line:-1,symbol:t.symbol,cells:[global(p,c)],amount:Math.round(bet*t.raw*this.payoutFactor),multiplier:t.raw*this.payoutFactor});
  for(const p of active){const f=frame('win','축제 '+(p+1)+'번 판 · 한 번 지급',0);f.wins=Array.from(boards[p].keys()).map(c=>awards.get(p+':'+c)!);f.cells=f.wins.flatMap(w=>w.cells);rounds.push(this.round(bet,[f]));}
  for(const s of snapshots)s.f.coinAwards=s.items.map(i=>({cell:i.cell,win:awards.get(i.key)!,fraction:i.raw/boards[Number(i.key.split(':')[0])].get(Number(i.key.split(':')[1]))!.raw}));
  return this.finish(rounds,{featureOnly:true});
 }
 play(b:string[],bet:number,rng:()=>number,forceSuper?:boolean){
  this.validate(b,bet);const base=this.ordinary(b,bet),wilds=Array.from(new Set(this.evaluate(b,10000).wins.flatMap(w=>w.cells).filter(c=>b[c]===this.id('wild'))));
  if(wilds.length&&rng()<.035){const value=[5,10,25,100][ri(rng,4)],f=this.prize(b,bet,value,wilds,'달빛 가마솥 · 고정 상금');base.expansionFeature!.frames.push(f);base.wins.push(...f.wins);base.payout+=f.wins.reduce((n,w)=>n+w.amount,0);}
  const gifts=b.flatMap((id,c)=>this.gift(id)>=0?[c]:[]);if(gifts.length<6)return this.finish([base]);const superBonus=forceSuper??rng()<.08;base.expansionFeature!.frames.push(this.frame(b,'trigger',superBonus?'선물 6개 이상 · 슈퍼 선물':'선물 6개 이상 · 선물 보너스',gifts));return this.bonus(b,bet,rng,base,superBonus);
 }
 private conditional(bet:number,rng:()=>number){
  const pool=this.pool(bet),gift=pool.filter(s=>this.gift(s.id)>=0),plain=pool.filter(s=>this.gift(s.id)<0),p=gift.reduce((n,s)=>n+s.weight,0)/pool.reduce((n,s)=>n+s.weight,0),weights:number[]=[];let choose=1;
  for(let n=0;n<=15;n++){if(n>=6)weights.push(choose*Math.pow(p,n)*Math.pow(1-p,15-n));choose=choose*(15-n)/(n+1);}let roll=rng()*weights.reduce((n,v)=>n+v,0),count=15;for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0){count=i+6;break;}}
  const positions=Array.from({length:15},(_,i)=>i);for(let i=14;i>0;i--){const j=ri(rng,i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}const selected=new Set(positions.slice(0,count));return positions.map((_,c)=>this.weighted(rng,selected.has(c)?gift:plain));
 }
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.choices('선물 보너스 선택',['선물 10회','슈퍼 선물 · 네 판 10회'],[false,true].map(superBonus=>this.purchaseFromResult(this.play(this.conditional(bet,rng),bet,rng,superBonus))));}
}
