import {nativeClusterWins} from './NativeClusterEvaluator';
import {cloneSlotData,SpinResult,Win} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,randomIndex} from './TumbleCore';
import {GOLDEN_INPUTS as M,goldenUniform,GoldenInput} from './GoldenReactionNativeMath';
const goldenPools=new WeakMap<GoldenInput,GoldenInput&{id:string;ids:string[];weights:number[]}>();
export class GoldenReactionNativeSlot extends TumbleGame {
 readonly columns=8;readonly rows=8;readonly hasBonus=true;
 clusters(board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=this.threshold):Win[]{return nativeClusterWins(this,board,bet,multiplier,neighbors,minimum);}
 unit(symbol:number,count:number){return !this.nativeFree&&symbol===0&&count===5?M.highFive:super.unit(symbol,count);}
 private nativeFree=false;
 pick(rng:()=>number=Math.random){const p=this.nativeFree?M.free:M.paid,id=this.config.id;let pool=goldenPools.get(p);if(!pool||pool.id!==id||pool.high!==p.high||pool.wild!==p.wild||pool.nucleus!==p.nucleus){const rest=1-p.wild-p.nucleus,weights=[rest*p.high,...Array(5).fill(rest*(1-p.high)/5),p.wild,p.nucleus],ids=weights.map((_,i)=>this.id(i===6?'wild':i===7?'nucleus':i));pool={...p,id,ids,weights};goldenPools.set(p,pool);}let u=goldenUniform(rng);for(let i=0;i<pool.weights.length;i++){u-=pool.weights[i];if(u<0)return pool.ids[i];}return pool.ids[pool.weights.findLastIndex(v=>v>0)];}
 readonly config=this.configFor('golden-reaction-lab','황금 반응 연구소','GOLDEN REACTION LAB',['붉은 시약','금빛 시약','초록 시약','청색 시약','보라 시약','흰 시약','반응 WILD','반응핵'],['0','1','2','3','4','5','wild','nucleus'],'8×8 · 연결5개. 색 칸 당첨 뒤 정해진 순서로 전판 교체→WILD→2×2→3×3→추가WILD. 반응핵 착지는 인접색 변환. 한 회전'+M.entryCollected+'개 수집: 골드피버, 5단계×2/4/6/8/10. 각 단계25개 수집 시 다음 단계. 구매는 독립 골드피버×2에서 시작.',[12,12,12,12,12,12,.8,.6]);
 private run(bet:number,rng:()=>number,multi:number,fever:boolean){const old=this.nativeFree;this.nativeFree=fever;try{return this.nativeRun(bet,rng,multi,fever);}finally{this.nativeFree=old;}}
 private nativeRun(bet:number,rng:()=>number,multi:number,fever:boolean){let board=this.draw(rng);const frames:TumbleFrame[]=[],marks=[0,15,24,47,60],pending=new Set<number>(fever?[0,1,2,3,4]:[]),used=new Set<number>();let collected=0;
  this.frame(frames,board,'land',fever?'골드피버 ×'+multi:'반응 표식 대기',{marks});
  let spent=0;for(let step=0;spent<bet*this.maxWin;step++){if(step>=100000)throw Error('Golden reaction did not settle');
   const nuclei=indices(board,this.id('nucleus'));if(nuclei.length){const cells=new Set<number>();for(const c of nuclei){const color=this.id(randomIndex(rng,6));[c,...adjacent(c,8,64)].forEach(n=>{board[n]=color;cells.add(n);});}this.frame(frames,board,'transform','반응핵 · 인접색 변환',{cells:Array.from(cells),marks});}
   const wins=this.clusters(board,bet,multi);if(wins.length){spent+=wins.reduce((a,w)=>a+w.amount,0);const removed=new Set(wins.flatMap(w=>w.cells));collected+=removed.size;marks.forEach((c,i)=>{if(removed.has(c)&&!used.has(i))pending.add(i);});this.frame(frames,board,'win','반응 수집 '+collected+' · ×'+multi,{wins,cells:Array.from(removed),marks});const next=this.gravity(board,removed,rng);board=next.board;this.frame(frames,board,'drop','반응 낙하',{moves:next.moves,marks});if(spent>=bet*this.maxWin)this.frame(frames,board,'state','최대 지급 한도 도달',{marks});continue;}
   const effect=Array.from(pending).sort()[0];if(effect===undefined)break;pending.delete(effect);used.add(effect);const cells:number[]=[];
   if(effect===0){board=this.draw(rng);cells.push(...board.map((_,c)=>c));}
   else if(effect===1||effect===4){for(let i=0;i<(effect===1?3:6);i++){const c=randomIndex(rng,64);board[c]=this.wild!;cells.push(c);}}
   else{const size=effect===2?2:3,x=randomIndex(rng,9-size),y=randomIndex(rng,9-size),symbol=this.id(randomIndex(rng,6));for(let r=0;r<size;r++)for(let c=0;c<size;c++){const at=(y+r)*8+x+c;board[at]=symbol;cells.push(at);}}
   this.frame(frames,board,'transform',['전판 반응','WILD 반응','사각 반응','거대 반응','마지막 WILD 반응'][effect],{cells,marks});if(spent>=bet*this.maxWin)this.frame(frames,board,'state','최대 지급 한도 도달',{marks});
  }return{round:this.round(bet,frames),collected};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.run(bet,rng,1,false);if(base.collected<M.entryCollected)return this.finish([base.round]);const rounds=[base.round];for(let level=1;level<=5;level++){const next=this.run(bet,rng,level*2,true);next.round.roundLabel='GOLD FEVER · '+level+'단계';rounds.push(next.round);if(next.collected<25)break;}return this.finish(rounds,{featureOnly:true});}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // Fever has no carried board, collection count or multiplier from the
  // qualifying paid spin. Its independent first stage is always ×2.
  const frames:TumbleFrame[]=[];this.frame(frames,this.draw(rng),'state','보너스 구매 · 골드피버 1단계 · ×2');const trigger=this.round(bet,frames),rounds:SpinResult[]=[];
  for(let level=1;level<=5;level++){const next=this.run(bet,rng,level*2,true);next.round.roundLabel='GOLD FEVER · '+level+'단계';rounds.push(next.round);if(next.collected<25)break;}
  return {...this.finish(rounds,{featureOnly:true,bonusTriggerRound:trigger}),rounds};
 }
}
