import{MOON_MODEL,moonInputBoard}from'./MoonMath';
/** Full10M purchase choice2 response refinement. Shared historical inputs
 * remain immutable; all paid/natural inputs and native feature rules retained. */
export const MOON_REFINED_MODEL={...MOON_MODEL,purchaseFree:MOON_MODEL.purchaseFree.map((p,i)=>i===2?{...p,premium:.18109654549237222}:{...p})};
export function moonRefinedPhaseBoard(rng:()=>number,phase:'base'|'trinity'|'free',guardian:number,purchased=false){return moonInputBoard(rng,phase==='free'?(purchased?MOON_REFINED_MODEL.purchaseFree:MOON_REFINED_MODEL.naturalFree)[guardian]:MOON_REFINED_MODEL[phase]);}
