import {WIND_HOUSE_MODEL as M} from './WindHouseMath';import {ExpansionSlot} from './ExpansionCore';
function uniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid house uniform');return u;}
function weights(free=false){const high=free?M.freeHigh:M.baseHigh,p=free?M.freeScatter:M.baseScatter;return [5*high,6,7,8,10,12,14,16,2,(75+5*high)*p/(1-p)];}
function pick(slot:ExpansionSlot,rng:()=>number,ws:number[]){let roll=uniform(rng)*ws.reduce((s,w)=>s+w,0);for(let n=0;n<ws.length;n++){roll-=ws[n];if(roll<0)return slot.id(n<8?n:n===8?'wild':'scatter');}return slot.id(ws.length===10?'scatter':'wild');}
/** Continuous native categorical input. No integer-floor distortion of the
 * declared fractional frequencies, no state or award-dependent probability. */
export function windHouseBoard(slot:ExpansionSlot,rng:()=>number,rows:number,free=false){const ws=weights(free);return Array.from({length:rows*5},()=>pick(slot,rng,ws));}
export function windHousePurchaseLaw(){const p=M.baseScatter;let choose=1;const count=Array.from({length:16},(_,k)=>{if(k)choose=choose*(16-k)/k;return {k,mass:k>=6?choose*p**k*(1-p)**(15-k):0};}).filter(s=>s.mass>0);return {count,trigger:count.reduce((s,v)=>s+v.mass,0)};}
const law=windHousePurchaseLaw();
/** Native fifteen-cell input conditioned only on >=6 hats. Count binomial,
 * positions uniform without replacement, other labels native non-hat. */
export function windHousePurchaseBoard(slot:ExpansionSlot,rng:()=>number){let roll=uniform(rng)*law.trigger,k=15;for(const v of law.count){roll-=v.mass;if(roll<0){k=v.k;break;}}const positions=Array.from({length:15},(_,c)=>c);for(let i=0;i<k;i++){const j=i+Math.floor(uniform(rng)*(15-i));[positions[i],positions[j]]=[positions[j],positions[i]];}const hats=new Set(positions.slice(0,k)),ws=weights().slice(0,9);return Array.from({length:15},(_,c)=>hats.has(c)?slot.id('scatter'):pick(slot,rng,ws));}
