import {BUFFALO_INPUTS as M} from './BuffaloNativeMath';
export function buffaloUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Buffalo random value');return u;}
export function buffaloNativeBoard(id:string,bet:number,rng:()=>number,free=false,conditional=false){
 const base=M.baseByBet[bet];if(!base)throw Error('Invalid Buffalo wager');
 const gate=free?M.freeGate:base.gate,high=free?M.freeHigh:base.high,wild=free?M.freeWildByBet[bet]:M.baseWild;
 const flags=Array(5).fill(false);
 if(conditional){let total=0;const masks:{mask:number;mass:number}[]=[];for(let mask=0;mask<32;mask++){const n=flags.reduce((sum,_,col)=>sum+(mask>>col&1),0);if(n<3)continue;const mass=gate**n*(1-gate)**(5-n);masks.push({mask,mass});total+=mass;}let u=buffaloUniform(rng)*total,chosen=masks[masks.length-1].mask;for(const item of masks){u-=item.mass;if(u<0){chosen=item.mask;break;}}flags.forEach((_,col)=>flags[col]=!!(chosen>>col&1));}
 else flags.forEach((_,col)=>flags[col]=buffaloUniform(rng)<gate);
 const rows=flags.map(flag=>flag?Math.floor(buffaloUniform(rng)*3):-1),weights=[6,7,8,10,12,14,16],sum=weights.reduce((a,b)=>a+b,0);
 return Array.from({length:15},(_,cell)=>{
  const col=cell%5,row=Math.floor(cell/5);if(rows[col]===row)return id+'-scatter';
  const w=col>=3?wild:0,u=buffaloUniform(rng);if(u<M.diamond)return id+'-diamond';if(u<M.diamond+w)return id+'-wild';
  const v=(u-M.diamond-w)/(1-M.diamond-w);if(v<high)return id+'-0';let roll=(v-high)/(1-high)*sum;
  for(let n=0;n<weights.length;n++){roll-=weights[n];if(roll<0)return id+'-'+(n+1);}return id+'-7';
 });
}
