import {Color,Graphics} from 'cc';

export const HELD_REEL_COLOR='#00d9ff';
export const REEL_FRAME_LEVEL_COLORS=['#ff8a24','#3578ff','#f13ad4'] as const;
const FRAME_OUTLINE='#102638';

/** Inset, opaque edges stay distinct against both light cells and gold trim. */
export function drawHeldReelFrame(g:Graphics,x:number,y:number,cell:number,color=HELD_REEL_COLOR){
 const width=Math.max(6,Math.min(10,Math.round(cell*.08)))/2,outer=width+2,inset=outer/2;
 for(const [stroke,lineWidth]of [[FRAME_OUTLINE,outer],[color,width]] as const){
  g.strokeColor=new Color(stroke);g.lineWidth=lineWidth;
  g.rect(x+inset,y-cell+inset,cell-outer,cell-outer);g.stroke();
 }
}
