import {moonSequence,MoonPower} from './MoonFeature';
import {moonResult} from './MoonResult';
import type {SpinResult} from './SlotMain';

export interface MoonChoicesOptions {
 id:string;bet:number;seed?:number;rng?:()=>number;guardian:MoonPower;choice:MoonPower;opening?:number[];
 board?:(rng:()=>number,mode:'base'|'trinity'|'free',guardian:MoonPower,multiplier:number)=>number[];
}
/** Original strip frequencies are not public. These are our own weights;
 * no incoming WILD/SCATTER is fabricated. A WILD is created by a match/power. */
export const MOON_WEIGHTS=[8,8,8,19,19,19,19];
export function moonChoiceResults(o:MoonChoicesOptions):SpinResult{
 if(!o.rng&&o.seed===undefined)throw Error('Moon requires a random input');
 const draws:number[]=[];
 const branch=(choice:MoonPower)=>{
  let seed=(o.seed??0)>>>0,index=0;
  const rng=o.rng?()=>{if(index===draws.length){const value=o.rng!();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Moon random value');draws.push(value);}return draws[index++];}:()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  const pick=()=>{let value=rng()*100;for(let symbol=0;symbol<7;symbol++){value-=MOON_WEIGHTS[symbol];if(value<0)return symbol;}return 6;};
  const sequence=moonSequence({bet:o.bet,rng,pick,guardian:o.guardian,choice,powerChance:.18,opening:o.opening,board:o.board?((mode,guardian,multiplier)=>o.board!(rng,mode,guardian,multiplier)):undefined,settle:amount=>Math.floor(amount)+(rng()<amount%1?1:0)});
  const rounds=sequence.rounds.map(round=>moonResult(o.id,o.bet,round)),last=rounds[rounds.length-1];
  const result:SpinResult=rounds.length===1?last:{bet:o.bet,board:[...last.board],wins:rounds.flatMap(round=>round.wins),payout:sequence.payout,rounds,freeSpinsAwarded:sequence.freeSpinsAwarded,featureName:'달빛 수호자의 축복'};
  result.moonNextGuardian=sequence.nextGuardian;return result;
 };
 const selected=branch(o.choice);if(!selected.freeSpinsAwarded)return selected;
 // Replaying the same random inputs holds the entry/Trinity path constant. Only
 // the free-game choice changes; its payout is not revealed before selection.
 const choices=([0,1,2] as MoonPower[]).map(choice=>choice===o.choice?selected:branch(choice));
 return{...selected,moonChoices:choices,moonDefaultChoice:o.choice};
}
