/** Declared local input frequencies. The adaptation's existing line awards,
 * prize tiers, three lives/reset rule and full-board award remain unchanged. */
export const OIL_MODEL:{baseCoin:number;landing:number;baseHighByBet:Record<number,number>}={"baseCoin":0.11396441623466685,"landing":0.2560083900375483,"baseHighByBet":{"20":13.453180017967977,"30":13.907804901613076,"40":13.58316492151316,"50":13.862547617760505,"70":13.742616779812376,"100":13.791030798798602,"150":13.659269269296257,"200":13.710850814545346,"250":13.712213983542085,"300":13.683110504246667,"350":13.68869349946419,"400":13.710850814545346,"450":13.711586412205225,"500":13.694308451350125,"600":13.710850814545346,"700":13.698950650948476,"800":13.710850814545346,"900":13.701509595698688,"1000":13.710850814545338,"2000":13.710850814545338,"3000":13.710850814545338,"4000":13.710850814545338,"5000":13.710850814545346,"6000":13.710850814545338,"7000":13.710850814545346,"8000":13.710850814545338,"9000":13.710850814545346,"10000":13.710850814545346}};
export const OIL_PRIZES=[1,2,5,10,15,30,60,100];
export const OIL_PRIZE_CDF=[.5,.75,.9,.97,.987,.996,.9995,1];
export const OIL_INPUT_WEIGHTS=[5,6,7,8,10,12,14,16,2];
const pools=new Map<number,{high:number;weights:number[];sum:number}>();
export function oilUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Oil random value');return value;}
export function oilPrizeValue(rng:()=>number){const value=oilUniform(rng);return OIL_PRIZES[OIL_PRIZE_CDF.findIndex(c=>value<c)];}
export function oilSymbolInput(bet:number,rng:()=>number){
 const roll=oilUniform(rng),coin=OIL_MODEL.baseCoin;
 if(roll<coin)return 'coin';
 const high=OIL_MODEL.baseHighByBet[bet]??1;let pool=pools.get(bet);
 if(!pool||pool.high!==high){const weights=OIL_INPUT_WEIGHTS.map((w,i)=>w*(i===0?high:1));pool={high,weights,sum:weights.reduce((n,w)=>n+w,0)};pools.set(bet,pool);}
 const weights=pool.weights;let sample=(roll-coin)/(1-coin)*pool.sum;
 for(let i=0;i<weights.length;i++){sample-=weights[i];if(sample<0)return i===8?'wild':i;}
 return 7;
}
