import {SocialFeatureSlot} from './SocialFeatureSlot';
import {SocialSlotSpec} from './SocialSlotCatalog';
import {banditRound,GoldenKind} from './BanditFeature';
import {SpinResult} from './SlotMain';
import {BANDIT_INPUTS} from './BanditNativeMath';
function checked(rng:()=>number){return()=>{const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Bandit RNG');return value;};}
/** Dedicated fixed native sampling; shared legacy family branches stay unchanged. */
export class BanditSlot extends SocialFeatureSlot {
 constructor(spec:SocialSlotSpec){super(spec);this.prepareBonusPurchase=function(bet,rng){return(this as BanditSlot).nativePurchase(bet,checked(rng));};}
 spin(bet:number,rng:()=>number=Math.random):SpinResult{if(!this.bets.includes(bet))throw Error('Invalid bet');return this.nativeSpin(bet,checked(rng));}
 private nativeBase(bet:number,rng:()=>number,golden:number[]=[],mode=0,limit=bet*this.maxWin,opening?:string[],inputSampler?:(symbols:{id:string;weight:number}[],rng:()=>number)=>string){
  const reveal=()=>{const roll=rng();if(roll<.008)return{kind:'pot' as GoldenKind,value:0};if(roll<.065)return{kind:'clover' as GoldenKind,value:[2,3,4,5,10][Math.floor(rng()*rng()*5)]};const choices=(mode===3?[[5,10000],[10,2000],[15,800],[20,200],[25,80],[50,20],[100,4],[250,1],[500,.2]]:[[.2,10000],[.5,7000],[1,4000],[2,1500],[3,700],[4,400],[5,200],[10,80],[15,40],[20,15],[25,8],[50,3],[100,1],[250,.2],[500,.1]]);let draw=rng()*choices.reduce((n,p)=>n+p[1],0),value=choices[0][0];for(const pair of choices){draw-=pair[1];if(draw<0){value=pair[0];break;}}return{kind:(value<5?'bronze':value<25?'silver':'gold') as GoldenKind,value};};
  const symbols=this.config.symbols,weights=symbols.map(s=>s.id===this.spec.id+'-0'?(mode?BANDIT_INPUTS.freeHigh:BANDIT_INPUTS.baseHigh):s.id===this.bonusSymbol?(mode?BANDIT_INPUTS.freeScatter:BANDIT_INPUTS.baseScatter):s.id===this.spec.id+'-rainbow'&&!mode?BANDIT_INPUTS.baseRainbow:s.weight),sum=weights.reduce((n,w)=>n+w,0);
  const inputPool=inputSampler?symbols.map((s,i)=>({id:s.id,weight:weights[i]})):undefined;
  const pick=()=>{if(inputSampler)return inputSampler(inputPool!,rng);let roll=rng()*sum;for(let i=0;i<symbols.length;i++){roll-=weights[i];if(roll<0)return symbols[i].id;}return symbols[symbols.length-1].id;};
  let board=opening;if(mode===3){board=board?[...board]:Array.from({length:30},pick);if(!board.includes(this.spec.id+'-rainbow'))board[Math.floor(rng()*30)]=this.spec.id+'-rainbow';}
  const result=banditRound({id:this.spec.id,bet,limit,golden,retain:mode>=2?'bonus':mode===1?'until-rainbow':'none',pick:pick,reveal},board);result.presentation=this.presentation;return result;
 }
 private nativeSpin(bet:number,rng:()=>number):SpinResult{
  return this.nativeSequence(this.nativeBase(bet,rng),bet,rng);
 }
 private nativeSequence(base:SpinResult,bet:number,rng:()=>number,purchase=false){
  const scatters=(round:SpinResult)=>round.board.filter(id=>id===this.bonusSymbol).length,count=scatters(base);
  if(count<3)return base;
  let mode=count>=5?3:count===4?2:1,remaining=mode===1?8:12,paid=purchase?0:base.payout,golden:number[]=[],played=0;const initial=remaining,rounds:SpinResult[]=purchase?[]:[base];
  while(remaining>0&&paid<bet*this.maxWin){
   if(played++>=1000)throw Error('Bandit free spins did not converge');remaining--;
   const round=this.nativeBase(bet,rng,golden,mode,bet*this.maxWin-paid),hits=scatters(round),extra=hits>=4?4:hits>=2?hits:0;
   golden=round.nextGoldenCells||[];if(hits>=4&&mode===1)mode=2;remaining+=extra;paid+=round.payout;
   round.freeSpinsRemaining=remaining;round.freeSpinsAdded=extra;round.roundLabel=`FREE SPINS · ${played}회 · 남은 ${remaining}회`;
   round.featureText=mode===3?'매회 무지개 · 황금 칸 유지':mode===2?'황금 칸 보너스 내내 유지':'무지개까지 황금 칸 유지';rounds.push(round);
  }
  return{board:[...rounds[rounds.length-1]!.board],bet,wins:rounds.flatMap(r=>r.wins),payout:paid,rounds,freeSpinsAwarded:initial,featureName:count>=5?'매회 무지개':count===4?'영구 황금 칸':'황금 칸 수집',presentation:this.presentation,bonusTriggerRound:purchase?base:undefined};
 }
 private nativePurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const board=Array.from({length:30},()=>this.spec.id+'-'+Math.floor(rng()*10)),positions=Array.from({length:30},(_,i)=>i);
  for(let i=0;i<3;i++){const selected=i+Math.floor(rng()*(30-i));[positions[i],positions[selected]]=[positions[selected],positions[i]];board[positions[i]]=this.bonusSymbol;}
  return this.nativeSequence({bet,board,wins:[],payout:0,presentation:this.presentation},bet,rng,true);
 }
}
