import{LANTERN_FIRE_MODEL}from'./LanternFireMath';
export type LanternFireInputs={sign:number;fire:number;freeSign:number;wild:number;landing:number;baseZeroByBet:Record<number,number>;freeZeroByCountSetBet:Record<string,Record<number,number>>};const D:LanternFireInputs=LANTERN_FIRE_MODEL;
function lanternBinomial(n:number,p:number){let v=[1];for(let i=0;i<n;i++){const next=Array(v.length+1).fill(0);v.forEach((q,k)=>{next[k]+=q*(1-p);next[k+1]+=q*p;});v=next;}return v;}
function lanternGateMass(sign:number,fire:number){const signs=lanternBinomial(3,sign);return{rows:signs.map((p,k)=>({k,p,tail:lanternBinomial(20-k,fire).slice(4).reduce((a,b)=>a+b,0)}))};}
/** Fixed categorical inputs with exact gate conditioning; no output search. */
export function lanternFireInputBoard(id:string,bet:number,rng:()=>number,free=false,count=20,set=[2,3,5],conditional?:'fire'|'free'){
 if(!Number.isFinite(D.baseZeroByBet[bet])||free&&conditional)throw Error('Invalid Lantern mode/bet');const uniform=()=>{const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid Lantern uniform');return v;},choose=(weights:number[])=>{const total=weights.reduce((a,b)=>a+b,0);let u=uniform()*total;for(let n=0;n<weights.length;n++){u-=weights[n];if(u<0)return n;}return weights.length-1;};
 const signs=Array(5).fill(false),positions=Array(5).fill(0);const sign=free?D.freeSign:D.sign;
 if(conditional==='fire'){const mass=lanternGateMass(sign,D.fire),mask=choose(Array.from({length:8},(_,mask)=>{const k=[0,1,2].reduce((n,c)=>n+((mask>>c)&1),0);return sign**k*(1-sign)**(3-k)*mass.rows[k].tail;}));for(let col=0;col<5;col++){uniform();positions[col]=Math.floor(uniform()*4);signs[col]=col>0&&col<4&&!!(mask>>(col-1)&1);}}
 else for(let col=0;col<5;col++){const u=uniform();positions[col]=Math.floor(uniform()*4);signs[col]=col>0&&col<4&&(conditional==='free'||u<sign);}
 const freeCells=new Set<number>();signs.forEach((has,col)=>{if(has)freeCells.add(positions[col]*5+col);});const available=Array.from({length:20},(_,n)=>n).filter(n=>!freeCells.has(n)),fireCells=new Set<number>();
 if(conditional){const weights=lanternBinomial(available.length,D.fire).map((p,n)=>conditional==='fire'?(n>=4?p:0):(n<4?p:0));let n=choose(weights);for(let i=0;i<available.length;i++){if(uniform()<n/(available.length-i)){fireCells.add(available[i]);n--;}}if(n)throw Error('Conditional Lantern subset mismatch');}
 const z=free?D.freeZeroByCountSetBet[count+':'+set.join(',')]?.[bet]:D.baseZeroByBet[bet];if(!Number.isFinite(z))throw Error('Invalid Lantern policy');const pool=[z,...[6,7,8,10,12,14,16].map(v=>(1-z-D.wild)*v/73),D.wild];
 return Array.from({length:20},(_,cell)=>{const hit=uniform()<(!free?D.fire:0);let u=uniform(),n=8;for(let i=0;i<pool.length;i++){u-=pool[i];if(u<0){n=i;break;}}return id+'-'+(freeCells.has(cell)?'free':(conditional?fireCells.has(cell):hit)?'scatter':n===8?'wild':n);});
}
