import {ExpansionSlot,expansionCells as cells} from './ExpansionCore';
import {CAT_PROMOTION_MODEL,catUniform,catOrdinary} from './CatPromotionMath';
export class CatPromotionSlot extends ExpansionSlot {
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-bowls';}
 private drawingFree=false;
 unit(symbol:number,count:number){return(.025+.015*(8-symbol))*2**Math.max(0,count-3);}
 private grid(bet:number,rng:()=>number,conditional=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const high=this.drawingFree?CAT_PROMOTION_MODEL.freeHighByBet[bet]:CAT_PROMOTION_MODEL.baseHighByBet[bet],q=this.drawingFree?CAT_PROMOTION_MODEL.freeGate:CAT_PROMOTION_MODEL.baseGate,b=Array.from({length:15},(_,c)=>this.id(catOrdinary(high,c%5,rng)));
  for(let col=0;col<5;col++)if(col<3&&conditional||catUniform(rng)<(col<3?q:CAT_PROMOTION_MODEL.outerGate))b[Math.floor(catUniform(rng)*3)*5+col]=this.id('scatter');return b;
 }
 draw(bet:number,rng:()=>number){return this.grid(bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const result=this.purchaseFromResult(this.play(this.grid(bet,rng,true),bet,rng)),trigger=result.bonusTriggerRound!;trigger.expansionFeature!.frames=[this.frame(trigger.board,'trigger','독립 무료 15회',cells(trigger.board,this.id('scatter')).filter(c=>c%5<3))];return result;}
 play(board:string[],bet:number,rng:()=>number){const gate=cells(board,this.id('scatter')).filter(c=>c%5<3);if(new Set(gate.map(c=>c%5)).size<3)return this.finish([this.ordinary(board,bet)]);const base=this.ordinary(board,bet),diamonds=[0,0,0,0],promoted=new Set<number>(),rounds=[base];base.expansionFeature!.frames.push(this.frame(board,'trigger','첫 세 릴의 보석 그릇 · 무료 15회',gate));const saved=this.drawingFree;this.drawingFree=true;try{let remaining=15,awarded=15;
  while(remaining>0){remaining--;const b=this.draw(bet,rng),fresh:number[]=[];for(const c of [4,9,14])if(rng()<.15){b[c]=this.id('diamond');fresh.push(c);}const before=[...b],fs=[this.frame(before,'reels','5릴 큰 보석 · 고양이 그릇 수집',[],{panel:{label:'고양이 그릇',values:[...diamonds],columns:4,active:Array.from(promoted)}})];
   for(const cell of fresh){const kind=diamonds.findIndex(n=>n<3);if(kind<0)break;const old=diamonds[kind],beforeCounts=[...diamonds];diamonds[kind]++;fs.push(this.frame(before,'collect','5릴 보석 → '+this.config.symbols[kind].name,[cell],{meter:{label:'승급 보석 '+(kind+1),before:old,after:diamonds[kind],target:3,items:[{cell,value:1}]},panel:{label:'고양이 그릇',values:beforeCounts,columns:4,active:Array.from(promoted),collectIndex:kind}}));if(diamonds[kind]===3){promoted.add(kind);fs.push(this.frame(before,'trigger','그릇 3개 완성 · 해당 고양이 전체 승급',[cell],{panel:{label:'고양이 그릇',values:[...diamonds],columns:4,active:Array.from(promoted)}}));}}
   const transformed:number[]=[];b.forEach((id,c)=>{if(Array.from(promoted).some(n=>id===this.id(n))){b[c]=this.id('wild');transformed.push(c);}});fs.push(this.frame(b,'effect','승급 종류 전체 WILD 변환',transformed,{panel:{label:'고양이 그릇 · 3개 완성 시 WILD',values:[...diamonds],columns:4,active:Array.from(promoted)}}),this.hit(b,bet));const retrigger=cells(b,this.id('scatter')).filter(c=>c%5<3),added=new Set(retrigger.map(c=>c%5)).size===3?Math.min(15,240-awarded):0;if(added){remaining+=added;awarded+=added;fs.push(this.frame(b,'trigger','보석 그릇 재발동 · 무료 +'+added+'회',retrigger));}for(const f of fs)if(!f.panel)f.panel={label:'고양이 그릇',values:[...diamonds],columns:4,active:Array.from(promoted)};rounds.push(this.round(bet,fs,{freeSpinsRemaining:remaining,freeSpinsAdded:added||undefined}));
  }return this.finish(rounds,{freeSpinsAwarded:15,featureOnly:false});}finally{this.drawingFree=saved;}
 }
}
