import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import{SUMO_INPUTS as M,SumoInput,sumoUniform}from'./SumoNativeMath';
const pools=new Map<string,{id:string;weight:number}[]>(),totals=new WeakMap<{id:string;weight:number}[],number>();
const sumoCodes=new Map([...Array.from({length:8},(_,n)=>['sumo-ring-hold-'+n,n]as const),['sumo-ring-hold-wild',8]as const,...['scatter','coin','free','portrait','unlock'].map(n=>['sumo-ring-hold-'+n,9]as const)]);
/** Observed four-array Coin Grab and 9/6/3 free choices. Weights and tier awards are local. */
export class SumoNativeSlot extends ExpansionSlot {
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  if(g.columns!==5||g.rows!==3||Object.keys(opts).length||this.config.id!=='sumo-ring-hold')return super.evaluate(board,bet,g,opts);
  if(!this.bets.includes(bet)||board.length!==15)throw Error('Invalid expansion board or wager');
  const codes=board.map(id=>{const n=sumoCodes.get(id);if(n===undefined)throw Error('Invalid expansion board or wager');return n;}),wins:Win[]=[];
  // Only the first non-WILD symbol and the highest all-WILD prefix can win.
  // Keep symbol0 first, strict greater-than ties and the original round order.
  for(let line=0;line<this.paylines.length;line++){
   const path=this.paylines[line];let lead=9;for(const c of path)if(codes[c]!==8){lead=codes[c];break;}
   let best:Win|undefined;
   for(const symbol of lead>0&&lead<8?[0,lead]:[0]){
    let count=0;for(const c of path){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}
    if(count<3)continue;const mult=this.unit(symbol,count),amount=Math.round(bet*mult);
    if(!best||amount>best.amount)best={line,symbol:this.id(symbol),cells:path.slice(0,count),amount,multiplier:mult};
   }
   if(best&&best.amount>0)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }

 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['free','portrait','unlock'])this.config.symbols.push({id:this.id(name),name,color:'#f2cb86',weight:0,payout:0});this.config.description='5×3 · 50라인 · 왼쪽부터 연결\n붉은 코인 6개: 금고 1개로 시작. 황금 코인 6개: 같은 시작 코인을 네 금고에 복사합니다.\n열린 금고 코인 8/16/36개: 두 번째/세 번째/네 번째 금고를 해금합니다.\n리스핀 3회. 열린 금고에 새 코인이 오면 3회 복구하며 잠긴 금고의 코인도 고정됩니다.\n해금된 금고만 마지막에 한 번 지급. 각 금고 15칸 완성은 별도 고정 상금입니다.\n가운데 3릴 BONUS: 무료 9/6/3회 선택, 코인 발동 문턱은 6/5/4개. 무료 WILD는 해당 릴 전체로 확장됩니다.\n재발동은 선택 횟수 추가, 최대90회. 출현 확률·티어·재발동 횟수는 로컬 규칙이며 공유 잭팟은 없습니다.';}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-sumo';}
 get bonusSymbol(){return this.id('free');}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let total=totals.get(pool);if(total===undefined){total=pool.reduce((n,s)=>n+s.weight,0);totals.set(pool,total);}let roll=sumoUniform(rng)*total;for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private pool(bet:number,col:number,p:SumoInput,gated=false){const gate=col>0&&col<4?p.gate:0,high=p===M.paid?(M.highByBet[bet]??p.high):(M.freeHighByBet[M.free.indexOf(p)]?.[bet]??p.high),rest=1-p.red-p.gold-p.wild-gate,key=[high,p.red,p.gold,p.wild,gate,gated].join('/');let pool=pools.get(key);if(!pool){pool=[{id:this.id(0),weight:rest*high},...Array.from({length:7},(_,n)=>({id:this.id(n+1),weight:rest*(1-high)/7})),{id:this.id('wild'),weight:p.wild},{id:this.id('scatter'),weight:p.red},{id:this.id('coin'),weight:p.gold},{id:this.id('free'),weight:gated?0:gate}].filter(v=>v.weight>0);pools.set(key,pool);}return pool;}
 private drawPhase(bet:number,rng:()=>number,p:SumoInput){if(!this.bets.includes(bet))throw Error('Invalid bet');const out:string[]=[],gates=new Set<number>();for(let c=0;c<15;c++){const col=c%5,id=this.weighted(rng,this.pool(bet,col,p,gates.has(col)));out.push(id);if(id===this.id('free'))gates.add(col);}return out;}
 draw(bet:number,rng:()=>number){return this.drawPhase(bet,rng,M.paid);}
 private freeGate(b:string[]){return [1,2,3].every(col=>b.some((id,c)=>c%5===col&&id===this.id('free')));}
 private hold(board:string[],bet:number,rng:()=>number,superMode:boolean):SpinResult[]{
  const boards=Array.from({length:4},()=>new Map<number,number>()),global=(p:number,c:number)=>Math.floor(p/2)*30+Math.floor(c/5)*10+p%2*5+c%5,rounds:SpinResult[]=[],snaps:ExpansionFrame[]=[];let unlocked=superMode?4:1,left=3;
  const values=()=>[1,2,3,5,10,20][ri(rng,6)],symbol=this.id(superMode?'coin':'scatter');for(const c of cells(board,symbol)){const v=values();for(let p=0;p<(superMode?4:1);p++)boards[p].set(c,v);}
  const count=()=>boards.slice(0,unlocked).reduce((n,b)=>n+b.size,0),frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[])=>{const b=Array(60).fill(''),held:number[]=[];for(let p=0;p<4;p++)for(const c of boards[p].keys()){b[global(p,c)]=symbol;held.push(global(p,c));}const f=this.frame(b,action,caption,focus,{held,remaining:left,sumoVault:{unlocked,superMode,filled:boards.map(b=>b.size),collected:count()},panel:{label:'SUMO HOLD',values:[unlocked,count()],columns:2}},{columns:10,rows:6});snaps.push(f);return f;};
  rounds.push(this.round(bet,[frame('reveal',superMode?'황금 코인 · 같은 시작판을 네 금고에 복사':'붉은 코인 · 첫 금고 해금 · 리스핀 3회')]));
  const unlock=(fs:ExpansionFrame[])=>{while(unlocked<4&&count()>=[8,16,36][unlocked-1]){const p=unlocked;fs.push(frame('trigger','열린 금고 코인 '+[8,16,36][p-1]+'개 · 다음 금고 해금',[global(p,7)]));unlocked++;fs.push(frame('effect','금고 '+unlocked+' 해금 · 저장된 코인도 합산',[global(p,7)]));}};
  const initial:ExpansionFrame[]=[];unlock(initial);if(initial.length)rounds.push(this.round(bet,initial));
  while(left>0&&boards.some(b=>b.size<15)){left--;const prior=boards.flatMap((b,p)=>Array.from(b.keys(),c=>global(p,c))),fs:ExpansionFrame[]=[],active=unlocked,landed:number[]=[];let reset=false;for(let p=0;p<4;p++)for(let c=0;c<15;c++)if(!boards[p].has(c)&&rng()<.038){boards[p].set(c,values());landed.push(global(p,c));if(p<active)reset=true;}const spin=frame('reels','고정 코인 유지 · 네 금고 빈칸 회전');spin.held=prior;fs.push(spin);if(reset)left=3;if(landed.length)fs.push(frame('effect',reset?'열린 금고 새 코인 · 3회 복구':'잠긴 금고 코인 고정 · 횟수는 복구하지 않음',landed));unlock(fs);fs.push(frame('state','열린 금고만 최종 지급 · 남은 '+left+'회'));rounds.push(this.round(bet,fs));}
  left=0;const awards=new Map<number,Win>();for(let p=0;p<unlocked;p++)for(const [c,v]of boards[p]){const cell=global(p,c);awards.set(cell,{line:-1,symbol,cells:[cell],amount:Math.round(bet*v*this.payoutFactor),multiplier:v*this.payoutFactor});}
  const first=Array.from(awards.values())[0],firstRaw=first.amount;const paid=frame('collect','해금 금고 → 코인 숫자만 수집 · 한 번 지급',Array.from(awards.keys()));paid.wins=Array.from(awards.values());rounds.push(this.round(bet,[paid]));for(let p=0;p<unlocked;p++)if(boards[p].size===15){const f=frame('win','금고 '+(p+1)+' 15칸 완성 · 고정 GRAND',[global(p,7)]);f.wins=[{line:-1,symbol:this.id('portrait'),cells:[global(p,7)],amount:Math.round(bet*100*this.payoutFactor),multiplier:100*this.payoutFactor}];rounds.push(this.round(bet,[f]));}
  // Unopened potential coins share a scalable reference, but never enter the paid wins.
  for(const f of snaps)f.coinAwards=f.board.flatMap((id,cell)=>{if(!id)return[];const p=Math.floor(cell/30)*2+Math.floor(cell%10/5),c=Math.floor(cell%30/10)*5+cell%5;return[{cell,win:awards.get(cell)||first,...(awards.has(cell)?{}:{fraction:Math.round(bet*boards[p].get(c)!*this.payoutFactor)/Math.max(1,firstRaw)})}];});return rounds;
 }
 private freeRounds(base:SpinResult,bet:number,rng:()=>number,index:number){const rounds=[base],initial=[9,6,3][index],threshold=[6,5,4][index];let left=initial,awarded=initial;while(left>0){left--;const b=this.drawPhase(bet,rng,M.free[index]),wilds=cells(b,this.id('wild')),expanded=[...b];for(const c of wilds)for(let row=0;row<3;row++)expanded[row*5+c%5]=this.id('wild');const fs=[this.frame(b,'reels','스모 무료 회전')];if(wilds.length)fs.push(this.frame(expanded,'effect','스모 WILD · 해당 릴 전체 확장',expanded.flatMap((s,c)=>s!==b[c]?[c]:[])));fs.push(this.hit(expanded,bet,'확장 WILD 라인 당첨',{columns:5,rows:3}));const added=this.freeGate(b)?Math.min(initial,90-awarded):0;if(added){left+=added;awarded+=added;fs.splice(1,0,this.frame(b,'trigger','BONUS 재발동 · 무료 +'+added,cells(b,this.id('free'))));}for(const f of fs)f.panel={label:'SUMO FREE',values:[left,threshold],columns:2};rounds.push(this.round(bet,fs,{freeSpinsRemaining:left,freeSpinsAdded:added||undefined}));const gold=cells(b,this.id('coin')),red=cells(b,this.id('scatter')),superMode=gold.length>=threshold;if(superMode||red.length>=threshold){rounds.push(this.round(bet,[this.frame(b,'trigger','무료 중 코인 '+threshold+'개 · 멀티 금고 진입',superMode?gold:red)]),...this.hold(b,bet,rng,superMode));}}
 return this.finish(rounds,{freeSpinsAwarded:initial,featureOnly:false});}
 private branches(base:SpinResult,bet:number,rng:()=>number){return this.choices('무료 회전과 코인 문턱 선택',['9회 · 코인 6개','6회 · 코인 5개','3회 · 코인 4개'],[0,1,2].map(i=>this.freeRounds(JSON.parse(JSON.stringify(base)),bet,rng,i)));}
 play(b:string[],bet:number,rng:()=>number){this.validate(b,bet,{columns:5,rows:3});const base=this.ordinary(b,bet,undefined,{columns:5,rows:3}),gold=cells(b,this.id('coin')),red=cells(b,this.id('scatter')),superMode=gold.length>=6;if(superMode||red.length>=6){base.expansionFeature!.frames.push(this.frame(b,'trigger','코인 6개 이상 · 멀티 금고',superMode?gold:red));return this.finish([base,...this.hold(b,bet,rng,superMode)],{featureOnly:true});}if(this.freeGate(b)){base.expansionFeature!.frames.push(this.frame(b,'trigger','가운데 3릴 BONUS · 무료 선택',cells(b,this.id('free'))));return this.branches(base,bet,rng);}return this.finish([base]);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const q=1-M.paid.gate;
  for(let attempt=0;attempt<100000;attempt++){
   const positions=new Set<number>();for(const col of[1,2,3]){let u=sumoUniform(rng)*(1+q+q*q),row=2;for(let r=0;r<3;r++){u-=q**r;if(u<0){row=r;break;}}positions.add(row*5+col);}
   const board=Array.from({length:15},(_,c)=>positions.has(c)?this.id('free'):this.weighted(rng,this.pool(bet,c%5,M.paid,true)));
   if(cells(board,this.id('coin')).length>=6||cells(board,this.id('scatter')).length>=6)continue;
   return this.purchaseFromResult(this.branches(this.round(bet,[this.frame(board,'trigger','독립 무료 스모 보너스',cells(board,this.id('free')))]),bet,rng));
  }throw Error('Sumo structural purchase gate unavailable');
 }

}
