import type {SpinResult} from './SlotMain';
/** Exclude the paid trigger and presentation steps from the free-spin count.
 * Include welcome and wheel awards in the bonus total even when they are not spins. */
export function bonusCompletion(result:SpinResult,purchased:boolean){
 if(!result.rounds?.length)return null;
 const bonusRounds=purchased?result.rounds:result.rounds.slice(1),compass=bonusRounds.find(round=>round.compassFeature)?.compassFeature;
 const counted=bonusRounds.filter(round=>(!round.expansionFeature||round.freeSpinsRemaining!==undefined)&&(!round.moonFeature||round.moonFeature.mode==='free')&&round.crossroadsFeature?.mode!=='wheel'&&(!round.parkFeature||round.parkFeature.stage==='spin')&&(!compass||(compass.mode==='free'&&!round.compassFeature)));
 if(!counted.length)return null;
 return{count:counted.length,payout:bonusRounds.reduce((sum,round)=>sum+round.payout,0)};
}

/** Final result card for both free spins and non-spin bonus modes.
 * Presentation-only: never creates an award or changes the wallet. */
export function bonusResultCompletion(result:SpinResult,purchased:boolean){
 if(result.vikingRagnarok&&!result.rounds)return {count:1,payout:result.payout};
 if(result.featureOnly&&result.rounds?.length){
  const rounds=purchased?result.rounds:result.rounds.slice(1);
  return rounds.length?{count:0,payout:rounds.reduce((sum,round)=>sum+round.payout,0)}:null;
 }
 const free=bonusCompletion(result,purchased);if(free)return free;
 // These engines embed the complete free sequence instead of using rounds.
 if(!result.rounds){
  const f=result.phoenixFeature||result.caveFeature||(result.trainFeature?.kind==='sticky-free'?result.trainFeature:undefined);
  if(f)return {count:f.stages.length,payout:result.payout-f.triggerWins.reduce((sum,win)=>sum+win.amount,0)};
  if(result.submarineFeature)return {count:result.submarineFeature.stages.length,payout:result.payout};
 }
 return null;
}
