/** Fixed native phase weights; unchanged7x7 cluster table/world rules. Independent10M RTP verification required. */
export const GEM_PATTERN_MODEL={"baseHigh":2,"baseWild":4.203311731905022,"purchaseHigh":1,"purchaseWild":34.883741265663986} as const;
const pools=[false,true].map(p=>{const m=GEM_PATTERN_MODEL,weights=[12*(p?m.purchaseHigh:m.baseHigh),12,12,12,12,12,p?m.purchaseWild:m.baseWild];return{weights,total:weights.reduce((a,b)=>a+b,0)};});
export function gemPatternSymbol(id:string,rng:()=>number,purchase:boolean){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Gem random value');const pool=pools[Number(purchase)];let roll=u*pool.total;for(let n=0;n<pool.weights.length;n++){roll-=pool.weights[n];if(roll<0)return id+'-'+(n===6?'wild':n);}return id+'-wild';}
