import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {WOLF_LINES} from './WolfRules';
import {drawReelBoard} from './ReelScatter';
import{gapInputBoard,gapUniform}from'./GapInputBoard';
import{TOY_MODEL}from'./ToyDefendersMath';
import{toyCountInput}from'./ToyInputTape';
export const TOY_ID='toy-defenders';
export const TOY_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export const TOY_BONUS_SCALES=[1,1,1];
export const TOY_TOOLS=['자석 열 제어','망치 전방 제어','그물 분산 제어'];
export interface ToyPlayback {tool:number;round:number;before:number[];after:number[];targets:number[];advanceBefore:number;advanceAfter:number;status:'advance'|'cleared'|'overrun';awards:Win[];}
export interface ToyRound extends SpinResult {toyFeature?:ToyPlayback;}
export class ToyDefendersSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;readonly usesLocalPayouts=true;
 readonly bonusCalibrationKey=TOY_ID+':defense-v1';readonly bonusChoiceCount=3;
 get bonusSymbol(){return TOY_ID+'-scatter';}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'방위 배지 세 개',triggerText:'장난감 방위 개시',bonusInText:'10라운드의 도구 전략 선택',hitText:'고장 로봇 정지',totalWinText:'방위 총 보상',signature:'도구별 표적 선택·제거·접근·전멸/실패',uiEffect:'표적 제어와 접근',soundCue:'featureLand',anticipationHold:.3,hitHold:.2,outHold:.4};
 readonly config:SlotConfig={id:TOY_ID,title:'장난감 방위대',subtitle:'TOY DEFENDERS',tag:'TEN ROUND DEFENSE',color:'#253c48',accent:'#dfb879',description:'5×3 · 25라인 · 왼쪽부터3개 이상\n방위 배지3개 이상이면 도구 전략을 선택합니다.\n자석은 한 열, 망치는 전방, 그물은 분산 표적을 정지시킵니다.\n최대10라운드 안에20대를 모두 정지하면 추가 보상.\n10라운드 뒤 남은 로봇이 도달하면 종료. 이미 얻은 보상은 유지.\n로봇 한 대당0.3배·전멸 추가5배. 도구마다 표적과 처치 수 확률이 다릅니다.',symbols:['청동 로봇','비행 장난감','공구상자','스패너','볼트','건전지','태엽 열쇠','고무 망치','자석 방패 WILD','방위 배지'].map((name,i)=>({id:TOY_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#dfb879',weight:[5,6,7,8,10,12,14,16,3,5][i],payout:i<8?TOY_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):ToyRound {
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid defense spin');
  const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<8;s++){const cells:number[]=[];for(const c of line){if(board[c]!==TOY_ID+'-'+s&&board[c]!==TOY_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*TOY_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:TOY_ID+'-'+s,cells,amount};}if(best)wins.push(best);});
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Toy bet');const M=TOY_MODEL;return this.evaluate(gapInputBoard(TOY_ID,5,M.baseZero,M.highByBet[bet as keyof typeof M.highByBet],M.restWild,M.scatterGate,rng),bet);}
 private stars(board:string[]){return board.flatMap((s,i)=>s===this.bonusSymbol?[i]:[]);}
 private branch(base:ToyRound,tool:number,tape:number[]):SpinResult {
  const rounds:ToyRound[]=[{...base,board:[...base.board],wins:base.wins.map(w=>({...w,cells:[...w.cells]}))}];let alive=Array.from({length:20},(_,i)=>i);
  for(let round=1;round<=10&&alive.length;round++){
   const before=[...alive],a=tool===0?tape[(round-1)*3]:toyCountInput(tool,tape[(round-1)*3]),b=tool===0?toyCountInput(tool,tape[(round-1)*3+1]):tape[(round-1)*3+1];let targets:number[]=[];
   if(tool===0){const column=Math.floor(a*5),count=2+Math.floor(b*3);targets=alive.filter(i=>i%5===column).sort((a,b)=>b-a).slice(0,count);}
   else if(tool===1){const count=1+Math.floor(a*3);targets=[...alive].sort((a,b)=>b-a).slice(0,count);}
   else{const count=[0,2,4,6][Math.floor(a*4)],offset=Math.floor(b*20);targets=[...alive].sort((a,b)=>(a-offset+20)%20-(b-offset+20)%20).filter((_,i)=>i%2===0).slice(0,count);}
   alive=alive.filter(i=>!targets.includes(i));const status=alive.length===0?'cleared':round===10?'overrun':'advance',awards:Win[]=[];
   const award=(multiple:number)=>{const win:Win={line:-1,symbol:this.bonusSymbol,cells:this.stars(base.board),amount:Math.round(base.bet*multiple*TOY_BONUS_SCALES[tool])};awards.push(win);};
   if(targets.length){award(targets.length*.3);awards[awards.length-1].amount=targets.length*Math.round(base.bet*.3*TOY_BONUS_SCALES[tool]);}if(status==='cleared')award(5);
   const feature:ToyPlayback={tool,round,before,after:[...alive],targets,advanceBefore:round-1,advanceAfter:round,status,awards};
   rounds.push({board:[...base.board],bet:base.bet,wins:awards,payout:awards.reduce((n,w)=>n+w.amount,0),toyFeature:feature,roundLabel:'방위 '+round+' · 남은 로봇 '+before.length});
  }
  let left=base.bet*this.maxWin;for(const r of rounds){for(const w of r.wins){w.amount=Math.min(left,w.amount);left-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);}
  return {board:[...base.board],bet:base.bet,rounds,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),featureOnly:true,featureName:'장난감 방위',presentation:this.presentation,bonusEndReason:left?'spins-exhausted':'max-win'};
 }
 private bonus(base:ToyRound,rng:()=>number){const tape=Array.from({length:30},()=>gapUniform(rng)),results=[0,1,2].map(tool=>this.branch(base,tool,tape));return {...results[0],featureChoices:{title:'10라운드 도구 전략 선택',labels:TOY_TOOLS.map((t,i)=>t+(i===0?' · 한 열 2~4대':i===1?' · 앞쪽 1~3대':' · 분산 0~6대')),defaultIndex:0,results,noBonusEntry:true}};}
 spin(bet:number,rng:()=>number=Math.random):SpinResult {const base=this.draw(bet,rng);return this.stars(base.board).length>=3?this.bonus(base,rng):base;}
 prepareBonusPurchase(_bet:number,_rng:()=>number):SpinResult{throw Error('Unsupported Toy purchase: maximum11bet is below98bet return for100bet price');}

 demoSpin(bet:number){return this.findDemo(bet,false);}
 bonusDemoSpin(bet:number){return this.findDemo(bet,true);}
 private findDemo(bet:number,bonus:boolean){let seed=330928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.wins.length===1)return r;}throw Error('Defense fixture search failed');}
}
