import type {RhinoBoard} from '../slots/RhinoRules';

export const RHINO_SPIN_TIMING={
 targetSeconds:1,
 speed:1.2,
 fallSettleSeconds:.205,
 exitSeconds:.26,
 exitReelDelay:.004,
 exitRowDelay:.006666666666666667,
 enterSeconds:.34,
 enterReelDelay:.014,
 enterRowDelay:.01,
 topSeconds:.85,
} as const;

/** Longest six-reel/seven-row lower-board motion at the configured speed. */
export function rhinoSpinEnvelopeSeconds(reels=6,rows=7){
 const lastReel=Math.max(0,reels-1),lastRow=Math.max(0,rows-1),t=RHINO_SPIN_TIMING;
 const exit=t.exitSeconds+t.fallSettleSeconds+lastReel*t.exitReelDelay+lastRow*t.exitRowDelay;
 const enter=t.enterSeconds+t.fallSettleSeconds+lastReel*t.enterReelDelay+lastRow*t.enterRowDelay;
 return(exit+enter)/t.speed;
}
/** The lower board empties completely before the new geometry enters. */
export interface RhinoSpinView {
 exit(reel:number,symbols:readonly number[]):Promise<void>;
 enter(reel:number,symbols:readonly number[]):Promise<void>;
 slideTop(previous:readonly number[],result:readonly number[]):Promise<void>;
}
export async function spinRhinoReels(previous:RhinoBoard,result:RhinoBoard,view:RhinoSpinView){
 await Promise.all([
  (async()=>{
   await Promise.all(previous.columns.map((symbols,reel)=>view.exit(reel,symbols)));
   await Promise.all(result.columns.map((symbols,reel)=>view.enter(reel,symbols)));
  })(),
  view.slideTop(previous.top,result.top),
 ]);
}
