import {VAULT_INPUTS} from './VaultWorkshopMath';
const values=[.975,1.95,3.9],first=[2,3,5,10],last=[2,3,5,20];
function pick<T>(items:readonly T[],prob:readonly number[],rng:()=>number):T{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid vault uniform');let mass=0;for(let i=0;i<items.length;i++){mass+=prob[i];if(u<mass)return items[i];}return items[items.length-1];}
/** Base consumes original3board+3value uniforms; native samples the existing3role gate directly. */
export function vaultInput(id:string,bet:number,rng:()=>number,native=false):{board:string[];values:number[]}{
 const input=VAULT_INPUTS.find(v=>v.bet===bet);if(!input)throw Error('Invalid vault wager');
 const regular=[input.regularZero,...[14,18,24].map(p=>(1-input.regularZero)*p/56)];
 const board=native?[4,5,5]:Array.from({length:3},(_,col)=>{const special=col?input.stamp:input.vault;return pick([0,1,2,3,col?5:4],regular.map(p=>p*(1-special)).concat([special]),rng);});
 const mass=native?[.8,.15,.045].map(p=>(1-input.nativeHigh)*p/.995).concat([input.nativeHigh]):[.8,.15,.045,.005];
 return{board:board.map(n=>id+'-'+n),values:[pick(values,native?[.001,.001,.998]:[.7,.25,.05],rng),pick(first,mass,rng),pick(last,mass,rng)]};
}
