// Muted coloured plates separate pixel silhouettes from the illustrated stage.
// Feature and winning plates still take precedence.
const families = [
 {color:'#9fbaa9',slots:['animal-lines','frog-crown-pond','jungle-height-fortune','dog-yard-original','rabbit-bingo-garden','frog-story-chapters']},
 {color:'#a2bdcf',slots:['polar-tiger-path','white-peak-impact','tundra-two-way','wolf-gold-moon','cruise-feature-builder','mirror-manor-reels']},
 {color:'#b8a8ca',slots:['moon','potion-purse-tower','feline-double-trails','renaissance-gem-fall','serpent-gaze-reels','angel-devil-contract']},
 {color:'#cba7b6',slots:['cherry','puppy-paris-path','heart-link-vault','cat-diamond-promotion','city-linked-prize']},
 {color:'#cfad98',slots:['sunset-road-wheel','festival-drum-choice','lantern-fire-link','oil-prize-boom','sumo-ring-hold']},
 {color:'#c8be92',slots:['animal','season-tile-garden','bear-honey-prize','four-cart-gold','sun-goddess-stack','stone-king-collector']},
 {color:'#96bdb9',slots:['lobster-harbor-choice','lobster-harbor-ways','nile-queen-double','coin-rail-express','silver-mine-hold','rhino-grand-ways']},
 {color:'#a6b1cb',slots:['twin-circuit','cosmic-herd-cascade','midnight-sticky-rail','wolf-stack-ridge','thunder-kept-respin','dragon-ember-vault']},
 {color:'#afb994',slots:['clockwork','wind-house-frames','builder-house-rise','joey-puzzle-trail','prairie-buffalo-king','buffalo-diamond-pot','harvest-moon-fiesta','relic-discovery-ledger','bison-daily-trail']},
];
const slotColors:Record<string,string>={};
for(const family of families)for(const slot of family.slots)slotColors[slot]=family.color;
// Explicit palettes for the most prominent machines; avoid unrelated hash colours.
Object.assign(slotColors,{
 'gates-of-clouds':'#a7bacb','le-raccoon-bandit':'#a6b39a',
 'book-of-wildead':'#c4ac92','chaos-crew-x':'#a89eb7',
 'sugar-lane-rush':'#c6a8bd','sweet-bananaza':'#c7b696',
 'moon-princessa':'#aaa9c7','starlight-princessa':'#b9a9c7',
 'fire-in-dwarf-hole':'#b6a28f','gladiator-lore':'#b7aa94',
 'tome-of-madness':'#a6b8b1','crypt-of-x':'#aca4ba',
 'viking-runecrafty':'#9eb5b9','road-rage-x':'#b8aa9d',
});
// A quiet dark prairie field gives the blue buffalo and pale moon clear contrast.
slotColors['prairie-buffalo-king']='#343b35';
slotColors['jade-tile-cascade-ii']='#285346';
slotColors['four-cart-gold']='#253646';

export function reelCellBackground(slotId:string):string {
 if(slotColors[slotId])return slotColors[slotId];
 // Stable fallback also gives existing and future machines varied muted plates.
 let hash=0;
 for(let i=0;i<slotId.length;i++)hash=(Math.imul(hash,31)+slotId.charCodeAt(i))>>>0;
 return families[hash%families.length].color;
}


/** A coloured edge and a broad luminous core, both tied to the reel plate. */
export function reelHitPalette(slotId:string):{edge:string;colors:string[]} {
 const base=reelCellBackground(slotId);
 const accents:Record<string,string>={
  '#9fbaa9':'#54c89c','#a2bdcf':'#54bce9','#b8a8ca':'#b38ae9',
  '#cba7b6':'#ef8caf','#cfad98':'#eda36c','#c8be92':'#e9c65d',
  '#96bdb9':'#4cd3c1','#a6b1cb':'#839eec','#afb994':'#a2cd68',
  '#a7bacb':'#6ac8e8','#a6b39a':'#a0d16c','#c4ac92':'#edbd63',
  '#a89eb7':'#bc91ed','#c6a8bd':'#ea91c5','#c7b696':'#e5b965',
  '#aaa9c7':'#9e9bea','#b9a9c7':'#c29beb','#b6a28f':'#eba36a',
  '#b7aa94':'#e1b766','#a6b8b1':'#62c5aa','#aca4ba':'#bd96db',
  '#9eb5b9':'#6cc5d1','#b8aa9d':'#e3a478','#343b35':'#b6cf83','#253646':'#e9c65d',
 };
 const accent=accents[base]||'#83c5c5';
 const rgb=[1,3,5].map(i=>parseInt(accent.slice(i,i+2),16));
 const mix=(target:number[],amount:number)=>'#'+rgb.map((v,i)=>Math.round(v+(target[i]-v)*amount).toString(16).padStart(2,'0')).join('');
 // Preserve hue in the outline instead of using the old nearly black border.
 const edge=mix([0,0,0],.32);
 const colors=[accent,mix([255,245,202],.28),mix([203,244,255],.3)];
 return {edge,colors};
}
