/** Fixed input tables. No award selection depends on the resulting payout. */
export const STARGEM_BASE_PRIZES=[[1,45],[2,25],[3,15],[5,8],[10,4],[20,2],[50,1]] as const;
export const STARGEM_FREE_PRIZES=[[2,35],[3,25],[5,20],[10,12],[20,5],[50,2],[100,1]] as const;
export function stargemPrize(uniform:number,free=false){
 const table=free?STARGEM_FREE_PRIZES:STARGEM_BASE_PRIZES;let pick=uniform*100;
 for(const [value,weight] of table){pick-=weight;if(pick<0)return value;}throw Error('Invalid Stargem prize uniform');
}
