import {SpinResult} from '../slots/SlotMain';
import {BALLOON,TICKET,FESTIVAL_SCATTER} from '../slots/BalloonBundleSlot';

export interface BalloonGrant {cell:number;count:number;kind:'balloon'|'scatter';}
/** Display only the grant accepted by the engine, including the 100-spin cap. */
export function balloonGrants(round:SpinResult):BalloonGrant[]{
 const f=round.balloonFeature;if(!f)return [];
 let budget=f.free?(round.freeSpinsAdded||0):Math.min(100,f.awarded);
 const sources:BalloonGrant[]=f.pops.filter(p=>p.freeSpins>0).map(p=>({cell:p.cell,count:p.freeSpins,kind:'balloon'}));
 const scatters=round.board.flatMap((id,cell)=>id===FESTIVAL_SCATTER?[cell]:[]);
 if(scatters.length>=6)for(const cell of scatters)sources.push({cell,count:f.scatterSpins[cell],kind:'scatter'});
 return sources.flatMap(source=>{const count=Math.min(budget,source.count);budget-=count;return count>0?[{...source,count}]:[];});
}
/** The same per-reel maximum tickets used by the engine's balloon connection. */
export function balloonBoostCells(round:SpinResult):number[]{
 const f=round.balloonFeature;if(!f?.pops.length)return [];
 const cells:number[]=[];
 for(let col=0;col<5;col++){
  const connected=[col,col+5,col+10].filter(i=>round.board[i]===BALLOON||round.board[i]===TICKET);
  if(!connected.length)break;
  const tickets=connected.filter(i=>round.board[i]===TICKET).sort((a,b)=>f.tickets[b]-f.tickets[a]);
  if(tickets.length)cells.push(tickets[0]);
 }
 return cells;
}
/** Individual existing balloon sprites, rather than one balloon with a count. */
export function balloonBundleOffsets(count:number){
 return count>=3?[{x:-.22,y:-.04},{x:.22,y:-.04},{x:0,y:.14}]:count===2?[{x:-.18,y:0},{x:.18,y:.08}]:count===1?[{x:0,y:0}]:[];
}
