export class AmberMaskSlot extends GapSlot {
 private maskBoard(bet:number,rng:()=>number,free=false){if(!this.bets.includes(bet))throw Error('Invalid Mask bet');const M=MASK_MODEL;return gapInputBoard(this.config.id,5,free?M.freeZero:M.baseZero,free?1:M.highByBet[bet],M.restWild,free?M.freeScatterGate:M.scatterGate,rng);}
 spin(bet:number,rng:()=>number=Math.random){return this.play(this.maskBoard(bet,rng),bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Mask bet');const M=MASK_MODEL,r=this.play(maskConditionalBoard(this.config.id,M.baseZero,M.highByBet[bet],M.restWild,M.scatterGate,rng),bet,rng),trigger=r.rounds![0];return packRounds(r.rounds!.slice(1),{featureOnly:false,freeSpinsAwarded:r.freeSpinsAwarded,featureName:r.featureName,presentation:this.presentation,bonusTriggerRound:{bet,board:[...trigger.board],wins:[],payout:0,presentation:this.presentation}});}

 readonly kind='mask' as const;
 readonly config=this.makeConfig('amber-mask-theatre','황금 가면극','SYMBOL MERGE',['금빛 가면','깃털 왕관','가면 부채','비단 망토','무대 등불','리본','입장권','장갑','주연 WILD','황금 봉인'],'5×3 · 25라인. 봉인3/4/5개: 무료8/15/20회. 무료 중 금빛 가면3개마다 상위 심볼 하나를 가면으로 통합. 무료 봉인2개: +5회. 총100회 상한.');
 play(board:string[],bet:number,rng:()=>number){const base=this.evaluate(board,bet),count=cellsOf(board,this.bonusSymbol).length,initial=count>=5?20:count===4?15:count===3?8:0;if(!initial)return base;
  const rounds=[this.round(bet,[this.frame(board,'봉인 확정 · 가면극 시작',cellsOf(board,this.bonusSymbol),[],base.wins)])];let left=initial,awarded=initial,tally=0,merged=0;
  while(left-->0){const raw=this.maskBoard(bet,rng,true),before=[...raw],old=merged;for(let c=0;c<15;c++)for(let n=1;n<=merged;n++)if(raw[c]===this.id(n))raw[c]=this.id(0);
   tally+=cellsOf(raw,this.id(0)).length;while(tally>=3&&merged<3){tally-=3;merged++;}
   for(let c=0;c<15;c++)for(let n=1;n<=merged;n++)if(raw[c]===this.id(n))raw[c]=this.id(0);
   const extra=Math.min(cellsOf(raw,this.bonusSymbol).length>=2?5:0,100-awarded);left+=extra;awarded+=extra;
   const paid=this.evaluate(raw,bet),frames=[this.frame(before,'가면 수집 · 통합 '+old+'/3',cellsOf(before,this.id(0)),[tally,old])];
   frames.push(this.frame(raw,merged>old?'상위 심볼 '+merged+'종 통합':'가면극 당첨',raw.flatMap((s,c)=>s!==before[c]?[c]:[]),[tally,merged],paid.wins));
   const r=this.round(bet,frames);r.freeSpinsRemaining=left;r.freeSpinsAdded=extra||undefined;rounds.push(r);
  }return this.finish(rounds,{freeSpinsAwarded:initial,featureOnly:false});
 }
}

