import {cloneSlotData,SpinResult,Win} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,randomIndex} from './TumbleCore';
import {PARROT_INPUTS as M,parrotUniform,ParrotInput} from './ParrotNativeMath';
const parrotPools=new WeakMap<ParrotInput,ParrotInput&{id:string;ids:string[];weights:number[]}>();
export class ParrotNativeSlot extends TumbleGame {
 readonly columns=8;readonly rows=8;readonly regularCount=4;readonly hasBonus=true;
 private nativeFree=false;
 pick(rng:()=>number=Math.random){const p=this.nativeFree?M.free:M.paid,id=this.config.id;let pool=parrotPools.get(p);if(!pool||pool.id!==id||pool.coin!==p.coin||pool.upgrade!==p.upgrade||pool.bomb!==p.bomb||pool.map!==p.map){const rest=1-p.coin-p.upgrade-p.bomb-p.map,weights=[...Array(4).fill(rest/4),p.coin,p.upgrade,p.bomb,p.map],ids=['0','1','2','3','coin','upgrade','bomb','scatter'].map(v=>this.id(v));pool={...p,id,ids,weights};parrotPools.set(p,pool);}let u=parrotUniform(rng);for(let i=0;i<pool.weights.length;i++){u-=pool.weights[i];if(u<0)return pool.ids[i];}return pool.ids[pool.weights.findLastIndex(v=>v>0)];}
 readonly config=this.configFor('parrot-frontier','앵무 개척단','PARROT FRONTIER',['붉은 열매','파란 열매','초록 열매','보라 열매','탐험 주화','승급 깃털','발굴 폭탄','보너스 지도','붉은 앵무','파란 앵무','초록 앵무','보라 앵무'],['0','1','2','3','coin','upgrade','bomb','scatter','bird0','bird1','bird2','bird3'],'6×6에서8×8로 확장. 네 앵무가 인접한 자기색 열매를 따라 이동·수집. 깃털은 열매 승급, 폭탄은 이웃 제거·영역 확장. 지도3개: 무료5회. 무료 중 크기·등급 유지, 지도3개 +2(총25회). 구매는 독립6×6·네 앵무L1·무료5회. 주화는 유료'+M.paidCoin+'BET / 무료'+M.freeCoin+'BET.',[16,16,16,16,2,2,2,2,0,0,0,0]);
 idleFrame(){
  const size=6,birds=[0,size-1,(size-1)*8,(size-1)*8+size-1],board=Array.from({length:this.columns*this.rows},(_,cell)=>cell%8<size&&Math.floor(cell/8)<size?this.id((cell%8+Math.floor(cell/8))%this.regularCount):this.id('void'));
  birds.forEach((cell,index)=>board[cell]=this.id('bird'+index));
  return{action:'state' as const,board,caption:'6×6 · 앵무 개척 대기',wins:[],cells:[],moves:[],badges:Object.fromEntries(birds.map(cell=>[cell,'L1'])),marks:[],stationary:birds};
 }
 private run(bet:number,rng:()=>number,state:{size:number;grades:number[]},free:boolean){const old=this.nativeFree;this.nativeFree=free;try{return this.nativeRun(bet,rng,state,free);}finally{this.nativeFree=old;}}
 private nativeRun(bet:number,rng:()=>number,state:{size:number;grades:number[]},free:boolean){
  let board=this.draw(rng).map((s,c)=>c%8<state.size&&Math.floor(c/8)<state.size?s:this.id('void'));
  const birds=[0,state.size-1,(state.size-1)*8,(state.size-1)*8+state.size-1];birds.forEach((c,i)=>board[c]=this.id('bird'+i));
  const frames:TumbleFrame[]=[],badges=()=>Object.fromEntries(birds.map((c,i)=>[c,'L'+state.grades[i]]));let maps=0;
  this.frame(frames,board,'land',(free?'무료 탐험 · ':'')+state.size+'×'+state.size,{badges:badges(),stationary:birds});
  let spent=0;for(let step=0;spent<bet*this.maxWin;step++){if(step>=100000)throw Error('Parrot exploration did not settle');
   let moved=false;
   for(let i=0;i<4;i++){
    const from=birds[i],to=adjacent(from,8,64).find(c=>[this.id(i),this.id('coin'),this.id('upgrade'),this.id('bomb'),this.bonusSymbol!].includes(board[c]));if(to===undefined)continue;
    moved=true;const token=board[to],remove=new Set([from]),wins:Win[]=[];
    if(token===this.id(i))wins.push(this.prize(bet,.025*state.grades[i],[to],token));
    if(token===this.id('coin'))wins.push(this.prize(bet,free?M.freeCoin:M.paidCoin,[to],token));
    if(token===this.id('upgrade'))state.grades[i]=Math.min(5,state.grades[i]+1);
    if(token===this.bonusSymbol)maps++;spent+=wins.reduce((a,w)=>a+w.amount,0);
    board[to]=this.id('bird'+i);board[from]=this.id('void');birds[i]=to;
    this.frame(frames,board,'move','앵무 '+(i+1)+' 이동·수집',{moves:[{from,to,symbol:this.id('bird'+i)}],cells:[to],badges:badges()});
    this.frame(frames,board,'collect',token===this.id('upgrade')?'열매 등급 상승':token===this.bonusSymbol?'지도 '+maps+'/3':token===this.id('bomb')?'폭탄 발굴':token===this.id('coin')?'탐험 주화 지급':'열매 수집 지급',{wins,cells:[to],badges:badges()});
    if(token===this.id('bomb')){
     const blast=adjacent(to,8,64).filter(c=>!birds.includes(c)&&board[c]!==this.id('void'));blast.forEach(c=>remove.add(c));
     if(state.size<8){state.size++;for(let c=0;c<64;c++)if(c%8<state.size&&Math.floor(c/8)<state.size&&board[c]===this.id('void')&&!birds.includes(c))remove.add(c);}
     this.frame(frames,board,'transform','폭탄 발굴 · '+state.size+'×'+state.size+' 개방',{cells:Array.from(remove),badges:badges()});
    }
    const next=this.gravity(board,remove,rng,new Set(birds),c=>c%8<state.size&&Math.floor(c/8)<state.size);board=next.board;
    this.frame(frames,board,'drop','수집 빈칸 낙하',{moves:next.moves,badges:badges()});
   }if(!moved)break;if(spent>=bet*this.maxWin)this.frame(frames,board,'state','최대 지급 한도 도달',{badges:badges()});
  }return{round:this.round(bet,frames),maps};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const state={size:6,grades:[1,1,1,1]},base=this.run(bet,rng,state,false);if(base.maps<3)return this.finish([base.round]);const rounds=[base.round];let left=5,awarded=5;while(left>0){left--;const next=this.run(bet,rng,state,true),extra=next.maps>=3?Math.min(2,25-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsRemaining=left;next.round.freeSpinsAdded=extra||undefined;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:5});}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // A bought expedition starts from the native fresh6x6/L1state, not a
  // hidden paid-spin search. Every free board is still freshly sampled.
  const state={size:6,grades:[1,1,1,1]},intro=this.draw(rng),birds=[0,5,40,45];
  for(let c=0;c<64;c++)if(c%8>=6||Math.floor(c/8)>=6)intro[c]=this.id('void');birds.forEach((c,i)=>intro[c]=this.id('bird'+i));
  const fs:TumbleFrame[]=[];this.frame(fs,intro,'state','독립 무료 탐험5회 ·6x6 ·앵무L1',{stationary:birds});const trigger=this.round(bet,fs),rounds:SpinResult[]=[];let left=5,awarded=5;
  while(left>0){left--;const next=this.run(bet,rng,state,true),extra=next.maps>=3?Math.min(2,25-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsRemaining=left;next.round.freeSpinsAdded=extra||undefined;rounds.push(next.round);}
  return {...this.finish(rounds,{freeSpinsAwarded:5,bonusTriggerRound:trigger}),rounds};
 }

}
