/** Direct conditioning of actual winning-shield input domains; no output acceptance or payout scaling. */
import {WOLF_LINES} from './WolfRules';import {BET_LEVELS} from './BetLevels';import {OATH_INPUT} from './OathbladeMath';
const OATH_LINES=WOLF_LINES.slice(0,5);
const oathRegular=(z:number,sword:number)=>[z,...[6,8,10,12,14,16].map(v=>(1-z-sword)*v/66),sword];
const M=OATH_INPUT,uniform=(rng:()=>number)=>{const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid Oath uniform');return v;};
export function oathInputBoard(id:string,bet:number,rng:()=>number,free=false){if(!BET_LEVELS.includes(bet))throw Error('Invalid Oath bet');const q=free?M.freeQ:M.q,reg=oathRegular(free?M.freeZero:M.baseZero,free?M.freeSword:M.baseSword),board=Array<string>(15);for(let col=0;col<5;col++){let used=false;for(let row=0;row<3;row++){const flag=uniform(rng),v=uniform(rng),cell=row*5+col;if(!used&&flag<q){board[cell]=id+'-scatter';used=true;}else if(v<M.wild)board[cell]=id+'-wild';else{let r=(v-M.wild)/(1-M.wild),n=0;while(n<7&&r>=reg[n])r-=reg[n++];board[cell]=id+'-'+n;}}}return board;}
export interface GateTerm {components:number[];required:number;coefficient:number;}
export function oathMaskTerms(mask:number):GateTerm[]{const prefixes=OATH_LINES.map(line=>{const first=line.findIndex(c=>!!(mask&(1<<c)));return first<0?undefined:line.slice(0,Math.max(3,first+1)).filter(c=>!(mask&(1<<c)));}),out=new Map<string,GateTerm>();for(let subset=1;subset<32;subset++){if(prefixes.some((p,i)=>!!(subset&(1<<i))&&p===undefined))continue;const parent=Array.from({length:15},(_,i)=>i),used=new Set<number>(),find=(i:number):number=>parent[i]===i?i:parent[i]=find(parent[i]);for(let i=0;i<5;i++)if(subset&(1<<i)){const group=prefixes[i]!;for(const c of group){used.add(c);parent[find(c)]=find(group[0]);}}const comp=new Map<number,number>();for(const c of used)comp.set(find(c),(comp.get(find(c))||0)|(1<<c));const components=Array.from(comp.values()).sort((a,b)=>a-b),required=components.reduce((a,b)=>a|b,0),coefficient=Array.from({length:5},(_,i)=>Number(!!(subset&(1<<i)))).reduce((a,b)=>a+b,0)%2?1:-1,key=components.join(','),old=out.get(key);if(old)old.coefficient+=coefficient;else out.set(key,{components,required,coefficient});}return Array.from(out.values()).filter(t=>t.coefficient);}
const pop=(v:number)=>{let n=0;while(v){v &= v-1;n++;}return n;};
export function oathMaskMass(mask:number,terms:GateTerm[],reg:number[],wild:number,q:number,scat:number[]=Array(5).fill(-2)){const k=pop(mask),base=wild**k*(1-wild)**(15-k),powers=Array.from({length:16},(_,n)=>reg.slice(0,7).reduce((s,p)=>s+p**n,0));let total=0;for(const t of terms){let mass=t.coefficient*base;for(let col=0;col<5;col++){let factor=0;if(scat[col]===-2){factor=(1-q)**3;for(let row=0;row<3;row++)if(!((mask|t.required)&(1<<(row*5+col))))factor+=q*(1-q)**row/(1-wild);}else if(scat[col]===-1)factor=(1-q)**3;else if(!((mask|t.required)&(1<<(scat[col]*5+col))))factor=q*(1-q)**scat[col]/(1-wild);mass*=factor;}for(const c of t.components)mass*=powers[pop(c)];total+=mass;}return Math.max(0,total);}
let cdf:Float64Array|undefined,total=0;
export function oathGateCdf(){if(cdf)return{cdf,total};const reg=oathRegular(M.baseZero,M.baseSword);cdf=new Float64Array(32768);for(let mask=1;mask<32768;mask++){total+=oathMaskMass(mask,oathMaskTerms(mask),reg,M.wild,M.q);cdf[mask]=total;}return{cdf,total};}
const select=(weights:number[],rng:()=>number)=>{const sum=weights.reduce((a,b)=>a+b,0);if(!(sum>0))throw Error('Oath conditional input has zero mass');let u=uniform(rng)*sum;for(let i=0;i<weights.length;i++){u-=weights[i];if(u<0)return i;}for(let i=weights.length-1;i>=0;i--)if(weights[i]>0)return i;throw Error('Oath gate mass invalid');};
function regGate(terms:GateTerm[],reg:number[],assigned:number[],powers:number[]){let total=0;for(const t of terms){let mass=t.coefficient;for(const c of t.components){let fixed=-1,left=0;for(let i=0;i<15;i++)if(c&(1<<i)){const n=assigned[i];if(n<0)left++;else if(n===7||fixed>=0&&fixed!==n){mass=0;break;}else fixed=n;}if(!mass)break;mass*=fixed<0?powers[left]:reg[fixed]**left;}total+=mass;}return Math.max(0,total);}
export function oathInputPurchase(id:string,bet:number,rng:()=>number){if(!BET_LEVELS.includes(bet))throw Error('Invalid Oath bet');const{cdf,total}=oathGateCdf(),u=uniform(rng)*total;let lo=1,hi=32767;while(lo<hi){const mid=(lo+hi)>>1;if(cdf[mid]>u)hi=mid;else lo=mid+1;}const mask=lo,terms=oathMaskTerms(mask),reg=oathRegular(M.baseZero,M.baseSword),scat=Array(5).fill(-2);for(let col=0;col<5;col++){const weights=[-1,0,1,2].map(row=>{scat[col]=row;return oathMaskMass(mask,terms,reg,M.wild,M.q,scat);});scat[col]=[-1,0,1,2][select(weights,rng)];}const scatMask=scat.reduce((m,row,col)=>m|(row<0?0:1<<(row*5+col)),0),valid=terms.filter(t=>!(t.required&scatMask)),assigned=Array(15).fill(-1),powers=Array.from({length:16},(_,n)=>reg.slice(0,7).reduce((s,p)=>s+p**n,0)),board=Array<string>(15);for(let cell=0;cell<15;cell++){if(mask&(1<<cell))board[cell]=id+'-wild';else if(scatMask&(1<<cell))board[cell]=id+'-scatter';else{const weights=reg.map((p,n)=>{assigned[cell]=n;return p*regGate(valid,reg,assigned,powers);});assigned[cell]=select(weights,rng);board[cell]=id+'-'+assigned[cell];}}return board;}
