export function frogUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error("Invalid Frog uniform");return u;}
export function frogOrdinary(h:number,rng:()=>number){const w=[5*h,6,7,8,10,12,14,16];let u=frogUniform(rng)*w.reduce((a,b)=>a+b,0);for(let k=0;k<8;k++){u-=w[k];if(u<0)return String(k);}return "7";}
