import {SevenJewelSlot,JEWEL_ID,JEWEL_PAYS} from './SevenJewelSlot';
import {SpinResult,Win} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
const jewelWeights=[5,6,7,8,10,12,14,16,2,4],jewelTotal=jewelWeights.reduce((a,b)=>a+b,0),jewelIds=Array.from({length:10},(_,i)=>JEWEL_ID+'-'+(i===8?'wild':i===9?'scatter':i)),jewelCodes=new Map(jewelIds.map((id,i)=>[id,i]));
/** Exact native highest line award, with stable ID lookup and numeric prefixes. */
export function numericJewelAwards(board:string[],bet:number,lines:readonly(readonly number[])[]=WOLF_LINES):Win[]{
 const codes=board.map(id=>jewelCodes.get(id)??-1),wins:Win[]=[];
 for(let index=0;index<lines.length;index++){
  const line=lines[index];let prefix=0;while(prefix<line.length&&codes[line[prefix]]===8)prefix++;
  const regular=prefix<line.length&&codes[line[prefix]]>=0&&codes[line[prefix]]<8?codes[line[prefix]]:-1,candidates=prefix>=3?(regular>0?[0,regular]:[0]):regular>=0?[regular]:[];let best:Win|undefined;
  for(const symbol of candidates){let count=0;for(const c of line){if(codes[c]!==symbol&&codes[c]!==8)break;count++;}if(count<3)continue;const multiplier=JEWEL_PAYS[symbol][count-3],amount=Math.round(bet*multiplier);if(!best||amount>best.amount)best={line:index,symbol:jewelIds[symbol],cells:line.slice(0,count),amount,multiplier};}
  if(best)wins.push(best);
 }return wins;
}
/** Display, collection, saved boxes, actual prizes and100-round purchase all
 * remain inherited from SevenJewelSlot. Only pure pick/evaluate are cached. */
export class SevenJewelOptimizedSlot extends SevenJewelSlot {
 pick(rng:()=>number){let roll=rng()*jewelTotal;for(let i=0;i<jewelWeights.length;i++){roll-=jewelWeights[i];if(roll<0)return jewelIds[i];}return jewelIds[jewelIds.length-1];}
 evaluate(board:string[],bet:number):SpinResult{
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!jewelCodes.has(s)))throw Error('Invalid jewel board');
  const wins=numericJewelAwards(board,bet);return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
}
