import {SpinResult,Win} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,randomIndex} from './TumbleCore';
import {PRISM_INPUTS,prismUniform,prismConditionalOpening} from './PrismNativeMath';
const prismSymbolCodes=new Map([...Array.from({length:6},(_,i)=>['prism-split-forge-'+i,i] as const),['prism-split-forge-wild',6] as const]);
export class PrismNativeSlot extends TumbleGame {
 private nativeFree=false;
 get waysPaytable(){return PRISM_INPUTS.paytable;}
 unit(symbol:number,count:number){return count<3?0:this.waysPaytable[symbol][Math.min(5,count)-3];}
 pick(rng:()=>number){const M=PRISM_INPUTS,p=this.nativeFree?M.freeHigh:M.paidHigh,gate=this.nativeFree?M.freeGate:M.paidGate,w=M.wild;let u=prismUniform(rng);if(u<gate)return this.id('scatter');u-=gate;if(u<w)return this.id('wild');u=(u-w)/(1-gate-w);return u<p?this.id(0):this.id(1+Math.min(4,Math.floor((u-p)/(1-p)*5)));}
 readonly columns=5;readonly rows=8;readonly hasBonus=true;
 readonly config=this.configFor('prism-split-forge','프리즘 분할 공방','PRISM SPLIT FORGE',['붉은 프리즘','황색 프리즘','초록 프리즘','청색 프리즘','보라 프리즘','흰 프리즘','분광 WILD','공방 문'],['0','1','2','3','4','5','wild','scatter'],'5릴 · 왼쪽3릴부터 Ways. 위 보조릴과 같은 심볼 당첨 시 해당 릴 칸 분할, 최대7칸. 보조릴 배수는 낙하마다 +1(최대7). 문3개: 무료6회, 무료 중 릴 배수 유지. 자체 분할 각색.');
 private prismTiles(heights:number[]){
  const tiles=[] as NonNullable<TumbleFrame['tiles']>;
  for(let col=0;col<5;col++)for(let row=0;row<heights[col];row++)tiles.push({cell:(8-heights[col]+row)*5+col,x:col+.5,y:1.25+(row+.5)*6.75/heights[col],w:1,h:6.75/heights[col]});
  return [...tiles,...[1,2,3].map(cell=>({cell,x:cell+.5,y:.5,w:1,h:1}))];
 }
 idleFrame(){
  const heights=[3,4,4,4,3],board=Array.from({length:this.columns*this.rows},()=>this.id('void'));
  for(let col=0;col<5;col++)for(let row=0;row<heights[col];row++)board[(8-heights[col]+row)*5+col]=this.id((col+row)%6);
  [1,2,3].forEach((cell,index)=>board[cell]=this.id(index));
  return{action:'state' as const,board,caption:'보조릴과 같은 색을 찾으세요',wins:[],cells:[],moves:[],badges:{1:'×1',2:'×1',3:'×1'},marks:[],tiles:this.prismTiles(heights)};
 }
 private prismWins(board:string[],top:string[],multipliers:number[],bet:number){
  const groups=Array.from({length:7},()=>Array.from({length:5},()=>[] as number[]));
  board.forEach((id,cell)=>{const code=prismSymbolCodes.get(id);if(code!==undefined)groups[code][cell%5].push(cell);});
  const wins:Win[]=[];for(let symbol=0;symbol<6;symbol++){
   const cells:number[]=[],counts:number[]=[];let m=1;
   for(let col=0;col<5;col++){const hits=groups[symbol][col].concat(groups[6][col]),extra=col>0&&col<4&&top[col-1]===this.id(symbol)?1:0;if(!hits.length&&!extra)break;counts.push(hits.length+extra);cells.push(...hits,...(extra?[col]:[]));m*=multipliers[col];}
   if(counts.length>=3)wins.push(this.prize(bet,this.waysPaytable[symbol][counts.length-3]*counts.reduce((n,c)=>n*c,1)*m,cells,this.id(symbol)));
  }return wins;
 }
 private run(bet:number,rng:()=>number,multipliers:number[],free:boolean,budget={remaining:bet*this.maxWin}){const saved=this.nativeFree;this.nativeFree=free;try{const heights=[3,4,4,4,3],top=[this.id(randomIndex(rng,6)),this.id(randomIndex(rng,6)),this.id(randomIndex(rng,6))];let board=this.draw(rng).map((s,c)=>Math.floor(c/5)>=8-heights[c%5]?s:this.id('void'));const frames:TumbleFrame[]=[],badges=()=>Object.fromEntries([1,2,3].map(c=>[c,'×'+multipliers[c]]));
  const visual=()=>this.prismTiles(heights);
  const shown=()=>{const b=[...board];top.forEach((s,i)=>{b[i+1]=s;});return b;};
  this.frame(frames,shown(),'land',free?'무료 공방 · 배수 유지':'보조릴과 같은 색을 찾으세요',{tiles:visual(),badges:badges()});let scatters=indices(board,this.bonusSymbol!).length;
  while(budget.remaining>0){
   const wins=this.prismWins(board,top,multipliers,bet);
   if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>c>=5));this.frame(frames,shown(),'win','분할 Ways 지급',{wins,cells:wins.flatMap(w=>w.cells),tiles:visual(),badges:badges()});
   budget.remaining-=wins.reduce((v,w)=>v+w.amount,0);if(budget.remaining<=0){this.frame(frames,shown(),'state','최대 지급 한도 도달',{tiles:visual(),badges:badges()});break;}
   for(let col=1;col<=3;col++)if(Array.from(remove).some(c=>c%5===col&&board[c]===top[col-1])&&heights[col]<7){heights[col]++;const c=(8-heights[col])*5+col;board[c]=this.id(randomIndex(rng,6));this.frame(frames,shown(),'transform',(col+1)+'릴 분할 · '+heights[col]+'칸',{cells:[c],tiles:visual(),badges:badges()});}
   const next=this.gravity(board,remove,rng);board=next.board;for(let col=1;col<=3;col++)multipliers[col]=Math.min(7,multipliers[col]+1);this.frame(frames,shown(),'drop','분할된 칸 낙하',{moves:next.moves,tiles:visual(),badges:badges()});scatters=Math.max(scatters,indices(board,this.bonusSymbol!).length);
  }return{round:this.round(bet,frames),scatters};}finally{this.nativeFree=saved;}
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const m=[1,1,1,1,1],budget={remaining:bet*this.maxWin},base=this.run(bet,rng,m,false,budget);if(base.scatters<3)return this.finish([base.round]);m.fill(1);const rounds=[base.round];for(let left=5;left>=0;left--){const next=this.run(bet,rng,m,true,budget);next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:6});}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const board=prismConditionalOpening(this,()=>prismUniform(rng)),triggerFrames:TumbleFrame[]=[],trigger=this.round(bet,[this.frame(triggerFrames,board,'land','공방 문 착지'),this.frame(triggerFrames,board,'state','공방 문 3개 · 무료 6회')]);
  const multipliers=[1,1,1,1,1],budget={remaining:bet*this.maxWin},rounds:SpinResult[]=[];
  for(let left=5;left>=0;left--){const next=this.run(bet,rng,multipliers,true,budget);next.round.freeSpinsRemaining=left;rounds.push(next.round);}
  return {...this.finish(rounds,{freeSpinsAwarded:6,bonusTriggerRound:trigger}),rounds};
 }
}
