import type {Cascade,SpinResult,Win} from './SlotMain';

/** Total-bet multipliers, 1–6 consecutive reels. See docs/slots/crypt-of-x.md. */
export const CRYPT_PAYS=[
 [0,0,.35,.8,1.5,2.5],[0,0,.25,.4,1,1.5],
 [0,0,.2,.3,.75,1.25],[0,0,.2,.3,.6,1.1],
 [0,0,.2,.25,.5,1],[0,0,.2,.25,.5,.9],
 [0,0,.15,.2,.4,.75],[0,0,.15,.2,.4,.7],[0,0,.15,.2,.4,.6],
 [0,0,.1,.15,.3,.6],[0,0,.1,.15,.3,.5],[0,0,.1,.15,.3,.5],
];
export interface CryptState {resurrected:number[];meter:number;legendMultiplier:number;}
export interface CryptEvent {
 kind:'split'|'nudge'|'resurrect'|'legend';cell:number;column:number;value:number;
 before:string[];after:string[];heights:number[];values:number[];
}
export interface CryptStage {
 opening:string[];heights:number[];events:CryptEvent[];afterEvents:CryptEvent[];
 meterBefore:number;meterAfter:number;resurrected:number[];legendBefore:number;legendAfter:number;
}
export interface CryptFeature {before:CryptState;after:CryptState;stages:CryptStage[];}
export interface CryptOptions {
 id:string;bet:number;rng:()=>number;pick:(column:number)=>string;reveal:()=>{symbol:string;count:2|3};
 free?:boolean;state?:CryptState;limit?:number;opening?:string[][];
}
export const newCryptState=():CryptState=>({resurrected:[],meter:0,legendMultiplier:1});
const copy=(state:CryptState):CryptState=>({...state,resurrected:[...state.resurrected]});
/** Six-row storage, bottom aligned: unused top cells are genuinely absent. */
export function cryptBoard(columns:string[][],id:string):string[]{
 return Array.from({length:36},(_,cell)=>columns[cell%6][Math.floor(cell/6)-(6-columns[cell%6].length)]??id+'-void');
}
export function cryptWays(id:string,columns:string[][],bet:number,wildMultipliers:number[],state:CryptState):Win[]{
 const wild=id+'-wild',wins:Win[]=[];
 const revived=new Set(state.resurrected.map(n=>id+'-'+n));
 // Index each reel once; preserve the original row order for every way.
 const matching=columns.map((column,col)=>{
  const groups=Array.from({length:12},()=>[] as number[]);
  for(let row=0;row<column.length;row++){
   const value=column[row],cell=(row+6-column.length)*6+col;
   if(value===wild||revived.has(value))for(const group of groups)group.push(cell);
   else{const symbol=Number(value.slice(id.length+1));if(Number.isInteger(symbol)&&symbol>=0&&symbol<12&&value===id+'-'+symbol)groups[symbol].push(cell);}
  }return groups;
 });
 for(let symbol=0;symbol<12;symbol++){
  if(state.resurrected.includes(symbol))continue;
  const cells:number[]=[],counts:number[]=[];let sum=0;
  for(let col=0;col<6;col++){
   const hits=matching[col][symbol];
   if(!hits.length)break;cells.push(...hits);counts.push(hits.length);
   if(wildMultipliers[col])sum+=wildMultipliers[col];
  }
  if(counts.length<3)continue;
  const multiplier=Math.max(1,sum)*(symbol===0?state.legendMultiplier:1),ways=counts.reduce((a,b)=>a*b,1);
  wins.push({line:-1,symbol:id+'-'+symbol,cells,amount:Math.round(bet*CRYPT_PAYS[symbol][counts.length-1]*ways*multiplier),multiplier});
 }
 return wins;
}
/** The feature owns its cascade state; it never enters the generic mark-cell engine. */
export function cryptRound(o:CryptOptions):SpinResult{
 const {id,bet}=o,state=copy(o.state??newCryptState()),before=copy(state),wild=id+'-wild',mystery=id+'-mystery';
 let columns=o.opening?o.opening.map(c=>[...c]):Array.from({length:6},(_,col)=>Array.from({length:4},()=>o.pick(col)));
 if(columns.length!==6||columns.some(c=>c.length<4||c.length>6))throw Error('Crypt needs six reels with four to six cells');
 if(o.free&&!columns.some(c=>c.includes(mystery))){
  // The published rule guarantees at least one xWays, not a fixed location.
  // Uniform placement is our distribution; the original strips are unpublished.
  let target=Math.floor(o.rng()*columns.reduce((total,column)=>total+column.length,0));
  for(const column of columns){if(target<column.length){column[target]=mystery;break;}target-=column.length;}
 }
 const cascades:Cascade[]=[],stages:CryptStage[]=[],wins:Win[]=[];
 let left=Math.max(0,o.limit??bet*27000),extra=0;const wildMultipliers=Array(6).fill(0);
 for(let index=0;;index++){
  if(index>=1024)throw Error('Crypt cascades did not converge');
  const opening=cryptBoard(columns,id),events:CryptEvent[]=[],afterEvents:CryptEvent[]=[],heights=columns.map(c=>c.length),values=Array(36).fill(0);
  for(let col=1;col<=4;col++)if(wildMultipliers[col])for(let row=6-columns[col].length;row<6;row++)values[row*6+col]=wildMultipliers[col];
  const event=(kind:CryptEvent['kind'],cell:number,value:number,prior:string[]):CryptEvent=>({kind,cell,column:cell%6,value,before:prior,after:cryptBoard(columns,id),heights:columns.map(c=>c.length),values:[...values]});
  // Resolve every mystery before nudging; expansion changes the distance to the floor.
  for(let col=0;col<6;col++)for(let row=0;row<columns[col].length;row++)if(columns[col][row]===mystery){
   const prior=cryptBoard(columns,id),cell=(row+6-columns[col].length)*6+col,reveal=o.reveal();
   const count=Math.min(reveal.count,7-columns[col].length);
   columns[col].splice(row,1,...Array(count).fill(reveal.symbol));
   events.push(event('split',cell,count,prior));row+=count-1;
  }
  for(let col=1;col<=4;col++){
   const row=columns[col].indexOf(wild);if(row<0||wildMultipliers[col])continue;
   const prior=cryptBoard(columns,id),value=columns[col].length-row,cell=(row+6-columns[col].length)*6+col;
   wildMultipliers[col]=value;columns[col].fill(wild);
   for(let r=6-columns[col].length;r<6;r++)values[r*6+col]=value;
   events.push(event('nudge',cell,value,prior));
  }
  const board=cryptBoard(columns,id),stageWins=cryptWays(id,columns,bet,wildMultipliers,state),meterBefore=state.meter,legendBefore=state.legendMultiplier;
  if(o.free)board.forEach((symbol,cell)=>{if(symbol===id+'-0')values[cell]=state.legendMultiplier;});
  for(const win of stageWins){win.amount=Math.min(left,win.amount);left-=win.amount;}
  const removed=new Set(stageWins.flatMap(w=>w.cells));
  if(o.free&&stageWins.length){
   if(stageWins.some(w=>w.symbol===id+'-0')){state.legendMultiplier++;afterEvents.push(event('legend',stageWins.find(w=>w.symbol===id+'-0')!.cells[0],state.legendMultiplier,board));}
   if(stageWins.some(w=>w.symbol!==id+'-0')&&state.resurrected.length<5){
    state.meter++;
    if(state.meter===4){state.meter=0;const next=[1,4,3,2,5].find(n=>!state.resurrected.includes(n))!;state.resurrected.push(next);extra+=2;afterEvents.push(event('resurrect',-1,next,board));}
   }
  }
  const stage:Cascade={board,wins:stageWins,payout:stageWins.reduce((n,w)=>n+w.amount,0),multiplier:Math.max(1,...stageWins.map(w=>w.multiplier||1)),symbolValues:values,cellMultipliers:values,nextMultipliers:values,drops:[],removedCells:[...Array.from(removed)]};
  cascades.push(stage);stages.push({opening,heights,events,afterEvents,meterBefore,meterAfter:state.meter,resurrected:[...state.resurrected],legendBefore,legendAfter:state.legendMultiplier});wins.push(...stageWins);
  if(!removed.size||left<=0)break;
  columns=columns.map((column,col)=>{
   if([...Array.from(removed)].some(cell=>cell%6===col))wildMultipliers[col]=0;
   const kept=column.map((symbol,row)=>({symbol,from:(row+6-column.length)*6+col})).filter(s=>!removed.has(s.from));
   const incoming=column.length-kept.length;
   return Array.from({length:column.length},(_,row)=>{
    const to=(row+6-column.length)*6+col,old=row>=incoming?kept[row-incoming]:null,symbol=old?.symbol??o.pick(col);
    stage.drops.push({from:old?.from??(row-incoming)*6+col,to,symbol});return symbol;
   });
  });
 }
 return{board:[...cascades[cascades.length-1]!.board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades,freeSpinsAdded:extra||undefined,symbolValues:cascades[cascades.length-1]!.symbolValues,cryptFeature:{before,after:copy(state),stages}};
}
