import {PRAIRIE_MODEL as M} from './PrairieBuffaloMath';
import {ExpansionSlot} from './ExpansionCore';
const regular=[5,6,7,8,10,12,14,16];
function uniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid prairie uniform');return u;}
export function prairieInputLaw(free=false){const wild=free?M.freeWild:M.baseWild,gate=free?M.freeGate:M.baseGate,q=(1-gate)**.25;return {wild,gate,q,scatter:(78+wild)*(1-q)/q};}
function plain(slot:ExpansionSlot,rng:()=>number,wild:number){let roll=uniform(rng)*(78+wild);for(let n=0;n<8;n++){roll-=regular[n];if(roll<0)return slot.id(n);}return slot.id('wild');}
/** Native row-major weighted draw, at most one scatter on each reel. */
export function prairieBoard(slot:ExpansionSlot,rng:()=>number,free=false){const law=prairieInputLaw(free),board:string[]=[],seen=Array(6).fill(false),total=78+law.wild+law.scatter;
 for(let cell=0;cell<24;cell++){let roll=uniform(rng)*(seen[cell%6]?78+law.wild:total),id=slot.id('wild');for(let n=0;n<8;n++){roll-=regular[n];if(roll<0){id=slot.id(n);break;}}if(roll>=0){roll-=law.wild;if(roll>=0){id=slot.id('scatter');seen[cell%6]=true;}}board.push(id);}return board;
}
export function prairiePurchaseLaw(){const {gate,q}=prairieInputLaw(),masks=Array.from({length:64},(_,mask)=>{const count=Array.from({length:6},(_,c)=>Number(!!(mask&(1<<c)))).reduce((s,v)=>s+v,0);return {mask,count,mass:count>=3?gate**count*(1-gate)**(6-count):0};}).filter(v=>v.mass>0),trigger=masks.reduce((s,m)=>s+m.mass,0);return {masks,trigger,rowWeights:[1,q,q*q,q*q*q]};}
const law=prairiePurchaseLaw();
/** Conditional native entrance input, independent of payout. Each reel is
 * drawn once: qualifying mask, geometric first scatter row, plain labels. */
export function prairiePurchaseBoard(slot:ExpansionSlot,rng:()=>number){let roll=uniform(rng)*law.trigger,mask=law.masks[law.masks.length-1].mask;for(const m of law.masks){roll-=m.mass;if(roll<0){mask=m.mask;break;}}const board:string[]=Array(24),total=law.rowWeights.reduce((s,w)=>s+w,0);
 for(let col=0;col<6;col++){let scatter=-1;if(mask&(1<<col)){let roll=uniform(rng)*total;scatter=3;for(let row=0;row<4;row++){roll-=law.rowWeights[row];if(roll<0){scatter=row;break;}}}for(let row=0;row<4;row++)board[row*6+col]=row===scatter?slot.id('scatter'):plain(slot,rng,M.baseWild);}return board;
}
