import {Node,Graphics,Color,UITransform,Label,EditBox,Font,BlockInputEvents} from 'cc';
import {addModalBackdrop} from './ModalBackdrop';
import {bindButtonFeedback} from './ButtonFeedback';
import {canBuyBonus,BONUS_COST_MULTIPLIER} from '../slots/BonusBuy';
import {simulationSlot,simulationCount,runMathSimulation,MathStats,SimulationMode} from '../services/SlotMathSimulation';

/** Local diagnostic UI: never receives a player, wallet, storage, or live slot. */
export class SlotMathPopup{
 readonly root:Node;private running=false;private cancelled=false;private mode:SimulationMode='normal';
 constructor(parent:Node,width:number,height:number,contentWidth:number,font:Font|null,id:string,title:string,onClose:()=>void){
  const root=this.root=new Node('Slot math simulator');root.layer=parent.layer;parent.addChild(root);addModalBackdrop(root,width,height,'Math simulation dim');
  const card=new Node('Math simulation panel');card.layer=root.layer;root.addChild(card);const scale=Math.min((contentWidth-48)/600,(height-64)/760,1);card.setScale(scale,scale,1);card.addComponent(UITransform).setContentSize(600,760);card.addComponent(BlockInputEvents);
  const g=card.addComponent(Graphics);g.fillColor=new Color('#29394a');g.roundRect(-300,-380,600,760,18);g.fill();g.strokeColor=new Color('#e8cc84');g.lineWidth=3;g.stroke();
  const node=(name:string,x:number,y:number,w:number,h:number)=>{const n=new Node(name);n.layer=root.layer;card.addChild(n);n.setPosition(x,y);n.addComponent(UITransform).setContentSize(w,h);return n;};
  const label=(value:string,x:number,y:number,w=548,h=36,size=22)=>{const n=node(value,x,y,w,h),l=n.addComponent(Label);l.string=value;l.font=font;l.fontSize=size;l.lineHeight=size+6;l.color=new Color('#fff1cc');l.overflow=Label.Overflow.SHRINK;l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;n.getComponent(UITransform)!.setContentSize(w,h);return l;};
  const button=(value:string,x:number,y:number,w:number,action:()=>void)=>{const n=node(value,x,y,w,48),bg=n.addComponent(Graphics);bg.fillColor=new Color('#486278');bg.roundRect(-w/2,-24,w,48,10);bg.fill();const l=label(value,x,y,w-12,40,21);bindButtonFeedback(n,action);return l;};
  const input=(name:string,x:number,y:number,value:string)=>{const n=node(name,x,y,244,48);n.active=false;const bg=n.addComponent(Graphics);bg.fillColor=new Color('#f1eedc');bg.roundRect(-122,-24,244,48,8);bg.fill();const edit=n.addComponent(EditBox),t=new Node('Input text');t.layer=root.layer;n.addChild(t);t.addComponent(UITransform).setContentSize(224,44);t.getComponent(UITransform)!.setAnchorPoint(0,1);const l=t.addComponent(Label);l.color=new Color('#233644');l.fontSize=24;l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;edit.textLabel=l;edit.inputMode=EditBox.InputMode.NUMERIC;edit.maxLength=7;n.active=true;edit.string=value;l.string=value;l.fontSize=24;l.color=new Color('#233644');l.overflow=Label.Overflow.CLAMP;t.getComponent(UITransform)!.setContentSize(224,44);return edit;};
  label('슬롯 수학 시뮬레이션',0,340,450,42,28);label(title,0,295,544,38,23);
  label('유저 머니·저장 데이터 미사용 / 별도 가상 계산',0,255,544,30,18);
  const slot=simulationSlot(id),purchase=canBuyBonus(slot);
  let normalLabel:Label,buyLabel:Label;const refreshMode=()=>{normalLabel.string=this.mode==='normal'?'● 일반':'일반';buyLabel.string=!purchase?'바이보너스 미지원':this.mode==='purchase'?'● 바이보너스':'바이보너스';};
  normalLabel=button('● 일반',-136,205,252,()=>{if(!this.running){this.mode='normal';refreshMode();}});buyLabel=button(purchase?'바이보너스':'바이보너스 미지원',136,205,252,()=>{if(!this.running&&purchase){this.mode='purchase';refreshMode();}});
  label('시뮬레이션 횟수',-136,158,250,30,20);label('가상 1회 베팅',136,158,250,30,20);
  const count=input('Simulation count',-136,115,'1000'),bet=input('Simulation virtual bet',136,115,String(slot.bets.includes(100)?100:slot.bets[0]));
  label('횟수 1~1,000,000 / 바이보너스 비용 = 베팅 ×'+BONUS_COST_MULTIPLIER,0,70,544,36,17);
  label('일반: 자연 보너스 포함 · 구매: 보너스 전체가 1회\n선택형 피처는 엔진 기본 선택 / 누적 상태는 새로 시작',0,23,544,58,17);
  const status=label('횟수와 가상 베팅을 입력한 뒤 실행하세요.',0,-39,544,46,20);
  const result=label('당첨률 · 순이익 발생률 · RTP\n가상 총 투입 / 총 지급 / 손익',0,-168,544,196,23);
  const n=(v:number)=>v.toLocaleString('en-US'),show=(s:MathStats)=>{status.string=(this.cancelled?'중단 요청 · ':'계산 중 · ')+n(s.completed)+' / '+n(s.requested)+'회';result.string=`당첨률 ${s.completed?(s.hits/s.completed*100).toFixed(2):'0.00'}% (${n(s.hits)}회)\n순이익 발생률 ${s.completed?(s.profits/s.completed*100).toFixed(2):'0.00'}%\nRTP ${s.moneyIn?(s.moneyOut/s.moneyIn*100).toFixed(2):'0.00'}%\n투입 ${n(s.moneyIn)} / 지급 ${n(s.moneyOut)}\n손익 ${n(s.moneyOut-s.moneyIn)} / 최대 지급 ${n(s.maxPayout)}`;};
  button('실행',-180,-306,164,()=>{if(this.running)return;let samples:number,wager:number;try{samples=simulationCount(count.string);wager=Number(bet.string);if(!slot.bets.includes(wager))throw Error('허용 베팅: '+slot.bets.join(', '));}catch(e){status.string=(e as Error).message;return;}
   this.running=true;this.cancelled=false;count.enabled=bet.enabled=false;status.string='계산 시작…';result.string='';
   void runMathSimulation(id,this.mode,samples,wager,{cancelled:()=>this.cancelled||!root.isValid,onProgress:s=>{if(root.isValid)show(s);}}).then(s=>{if(root.isValid){show(s);status.string=(s.cancelled?'중단':'완료')+' · '+n(s.completed)+' / '+n(s.requested)+'회';}}).catch(e=>{if(root.isValid)status.string='계산 실패: '+(e as Error).message;}).finally(()=>{this.running=false;if(root.isValid)count.enabled=bet.enabled=true;});
  });
  button('중단',0,-306,164,()=>{if(this.running){this.cancelled=true;status.string='현재 계산이 끝나면 중단합니다.';}});
  button('닫기',180,-306,164,()=>{this.destroy();onClose();});
  label('당첨률: 지급 > 0 · 순이익: 지급 > 비용 · RTP: 지급 ÷ 투입',0,-350,548,26,15);
 }
 destroy(){this.cancelled=true;if(this.root.isValid)this.root.destroy();}
}
