export function starlitCastAudit(params:URLSearchParams){const slot=new StarlitCastSlot(),actor=Number(params.get('audit-actor')||0);if(!Number.isInteger(actor)||actor<0||actor>=5)throw Error('Invalid cast audit actor');slot.selection=actor;const outcome=params.get('audit-outcome')||'rank-up',all=(CAST_WITNESSES as Record<string,Record<string,{seed:number;before:readonly number[];after:readonly number[];payout:number}>>)[actor],w=all[outcome]||all['rank-up'];slot.demoSpin=bet=>{slot.setProgress({[slot.config.id+':'+bet]:[...w.before]});const r=slot.spin(bet,expansionRng(w.seed));if(bet===100&&(r.payout!==w.payout||JSON.stringify(r.castFeature!.after)!==JSON.stringify(w.after)))throw Error('Stale cast witness');return r;};if(outcome==='all-stars')slot.demoSpin=bet=>{slot.setProgress({[slot.config.id+':'+bet]:[...all['mature-near-complete'].before]});return slot.spin(bet,()=>1-Number.EPSILON);};if(outcome==='highest-lines')slot.demoSpin=bet=>{slot.setProgress({});return slot.spin(bet,()=>0);};return slot;}
