import {conditionalReelEntrance} from './SequentialReelEntry';
import {SpinResult,Win} from './SlotMain';
import {Social2230LineSlot,socialPresentation,awardLines,sumResult,packRounds} from './Social2230Rules';
import {WOLF_LINES} from './WolfRules';
import {validateSocialBoard} from './Social1921Rules';
export const CROSSROADS_FREE_SPINS=8;
/** Fixed local symbol weights; awards always come from the paytable. */
export const CROSSROADS_MODEL={"baseHigh":3.3602446408360267,"baseWild":2.5023626319481993,"freeWild":26.906718946863748};
export const CROSSROADS_JACKPOTS=[2,3,4,5,6,8,10,12,15,20] as const;
export interface CrossroadsPlayback {
 mode:'base'|'trigger'|'free'|'wheel';left:Win[];right:Win[];
 remaining?:number;wildMultipliers?:{cell:number;multiplier:number}[];
 wheel?:{segments:number[];stops:number[];awards:Win[]};
}
export class FrostFlameSlot extends Social2230LineSlot {
 readonly hasBonus=true;readonly paylines=WOLF_LINES.slice(0,10);readonly bonusCalibrationKey='frost-flame-crossroads:fire-ice-v2';
 get bonusSymbol(){return this.config.id+'-wild';}
 readonly presentation=socialPresentation('불꽃은 왼쪽부터 · 서리는 오른쪽부터','양방향 라인 당첨');
 readonly config=this.namedConfig('frost-flame-crossroads','서리와 불꽃 교차로','FROST AND FLAME CROSSROADS',['불꽃 횃불','얼음 결정','용 비늘 방패','서리 왕관','화산돌','눈꽃 깃털','불씨 랜턴','얼음 열쇠','교차 문장 WILD'],'10개 경로를 왼쪽과 오른쪽에서 각각 판정합니다.\n같은 5칸 당첨은 한 번만 지급. 서로 다른 끝의 당첨은 둘 다 지급.\nWILD 3개 이상이면 무료 8회, 배수 WILD, 10칸 슈퍼 잭팟 휠에 진입합니다.\n무료 회전 중 양방향 동시 당첨 횟수에 따라 잭팟 휠을 최대 3회 돌립니다.','#263d52','#aee4f5');
 constructor(){super();this.config.description=this.config.description.replace('25라인','10라인');}
 private lineWins(board:string[],bet:number,reverse=false){return awardLines(this.config,board,bet,this.pays,reverse,this.paylines);}
 evaluate(board:string[],bet:number):SpinResult{
  validateSocialBoard(this.config,board,bet,this.bets,15);const left=this.lineWins(board,bet),right=this.lineWins(board,bet,true).filter(w=>!left.some(l=>l.line===w.line&&l.symbol===w.symbol&&l.cells.length===w.cells.length&&l.cells.every(c=>w.cells.includes(c))));
  return sumResult({board:[...board],bet,payout:0,wins:[...left,...right],crossroadsFeature:{mode:'base',left,right},presentation:this.presentation});
 }
 private board(rng:()=>number,free=false){
  const pool=this.config.symbols,out:string[]=[];for(let cell=0;cell<15;cell++){const col=cell%5,options=pool.filter(symbol=>symbol.id!==this.bonusSymbol||!out.some((id,c)=>c%5===col&&id===this.bonusSymbol)),weights=options.map(symbol=>symbol.id===this.bonusSymbol?(free?CROSSROADS_MODEL.freeWild:CROSSROADS_MODEL.baseWild):symbol.weight*(!free&&this.config.symbols.indexOf(symbol)===0?CROSSROADS_MODEL.baseHigh:1));let roll=rng()*weights.reduce((n,w)=>n+w,0),index=0;for(;index<options.length;index++){roll-=weights[index];if(roll<0)break;}out.push(options[Math.min(index,options.length-1)].id);}return out;
 }
 private freeRound(bet:number,rng:()=>number,remaining:number){
  const round=this.evaluate(this.board(rng,true),bet),wildMultipliers=round.board.flatMap((symbol,cell)=>symbol===this.bonusSymbol?[{cell,multiplier:2+Math.floor(rng()*3)}]:[]);
  for(const win of round.wins){const multiplier=wildMultipliers.filter(w=>win.cells.includes(w.cell)).reduce((best,w)=>Math.max(best,w.multiplier),1);if(multiplier>1){win.amount*=multiplier;win.multiplier=(win.multiplier||win.amount/bet/multiplier)*multiplier;}}
  round.crossroadsFeature={...round.crossroadsFeature!,mode:'free',remaining,wildMultipliers};round.freeSpinsRemaining=remaining;round.roundLabel='FREE SPINS · 남은 '+remaining+'회';return sumResult(round);
 }
 private wheelRound(board:string[],bet:number,rng:()=>number,spins:number){
  const stops=Array.from({length:spins},()=>Math.floor(rng()*CROSSROADS_JACKPOTS.length)),awards=stops.map((stop,index):Win=>({line:-80-index,symbol:this.bonusSymbol,cells:[],amount:bet*CROSSROADS_JACKPOTS[stop],multiplier:CROSSROADS_JACKPOTS[stop]}));
  return sumResult({board:[...board],bet,payout:0,wins:awards,roundLabel:'SUPER JACKPOT WHEEL',crossroadsFeature:{mode:'wheel',left:[],right:[],wheel:{segments:[...CROSSROADS_JACKPOTS],stops,awards}},presentation:this.presentation});
 }
 private bonus(base:SpinResult,rng:()=>number,includeBase:boolean){
  const free:SpinResult[]=[];let dualHits=0;
  for(let spin=0;spin<CROSSROADS_FREE_SPINS;spin++){const round=this.freeRound(base.bet,rng,CROSSROADS_FREE_SPINS-spin-1);if(round.crossroadsFeature!.left.length&&round.crossroadsFeature!.right.length)dualHits++;free.push(round);}
  const wheelSpins=1+(dualHits>=2?1:0)+(dualHits>=4?1:0),wheel=this.wheelRound(free[free.length-1].board,base.bet,rng,wheelSpins),rounds=includeBase?[base,...free,wheel]:[...free,wheel];
  return packRounds(rounds,{freeSpinsAwarded:CROSSROADS_FREE_SPINS,featureName:'FIRE & ICE SUPER JACKPOTS',presentation:this.presentation});
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.evaluate(this.board(rng),bet);if(base.board.filter(symbol=>symbol===this.bonusSymbol).length<this.bonusTriggerCount)return base;base.crossroadsFeature!.mode='trigger';return this.bonus(base,rng,true);}
 private purchaseEntrance?:ReturnType<typeof conditionalReelEntrance>;
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const weights=this.config.symbols.slice(0,8).map((s,i)=>s.weight*(i===0?CROSSROADS_MODEL.baseHigh:1)),sum=weights.reduce((a,b)=>a+b,0);this.purchaseEntrance??=conditionalReelEntrance(Array.from({length:5},()=>({regular:sum,wild:CROSSROADS_MODEL.baseWild,scatter:0})),1,3,false);const board=this.purchaseEntrance(rng).map(role=>{if(role===1)return this.bonusSymbol;let roll=rng()*sum;for(let i=0;i<8;i++){roll-=weights[i];if(roll<0)return this.config.id+'-'+i;}return this.config.id+'-7';});
  const trigger:SpinResult={board,bet,wins:[],payout:0,roundLabel:'BONUS TRIGGER',crossroadsFeature:{mode:'trigger',left:[],right:[]},presentation:this.presentation},result=this.bonus(trigger,rng,false);result.bonusTriggerRound=trigger;return result;
 }
 demoSpin(bet:number){const id=this.config.id,b=Array.from({length:15},(_,i)=>id+'-'+(i+Math.floor(i/5))%8);b[5]=b[6]=b[7]=id+'-0';b[2]=b[3]=b[4]=id+'-1';return this.evaluate(b,bet);}
}
