import {nativeClusterWins} from './NativeClusterEvaluator';
import {cloneSlotData,SpinResult,Win,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,randomIndex} from './TumbleCore';
import {BURIED_INPUTS as M,buriedUniform,BuriedInput} from './BuriedNativeMath';
const buriedPools=new WeakMap<BuriedInput,BuriedInput&{id:string;ids:string[];weights:number[]}>();
export class BuriedNativeSlot extends TumbleGame {
 readonly columns=6;readonly rows=6;readonly hasBonus=true;readonly bonusChoiceCount=3;
 clusters(board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=this.threshold):Win[]{return nativeClusterWins(this,board,bet,multiplier,neighbors,minimum);}
 private nativePhase=-1;
 pick(rng:()=>number=Math.random){const p=this.nativePhase<0?M.paid:M.free[this.nativePhase],id=this.config.id;let pool=buriedPools.get(p);if(!pool||pool.id!==id||pool.high!==p.high||pool.wild!==p.wild){const rest=1-p.wild,weights=[rest*p.high,...Array(5).fill(rest*(1-p.high)/5),p.wild],ids=weights.map((_,i)=>this.id(i===6?'wild':i));pool={...p,id,ids,weights};buriedPools.set(p,pool);}let u=buriedUniform(rng);for(let i=0;i<pool.weights.length;i++){u-=pool.weights[i];if(u<0)return pool.ids[i];}return pool.ids[pool.weights.findLastIndex(v=>v>0)];}
 unit(symbol:number,count:number){return count<5?0:symbol===0?M.highPrizes[count-5]:super.unit(symbol,count);}
 readonly config=this.configFor('buried-gate-chambers','묻힌 문 세 갈래','BURIED GATE CHAMBERS',['붉은 토기','금빛 인장','초록 잎','청색 항아리','보라 부적','흰 유물','탐험 WILD','봉인 돌'],['0','1','2','3','4','5','wild','stone'],'6×6 · 연결5개 · 유료 봉인 돌'+M.paidStoneCount+'개. 당첨 옆 봉인 돌 파괴·보드 개방. 돌을 모두 없애면 3경로 선택: 8회×1 / 5회×2 / 3회×4. 무료 중 완전 개방 +2회(총30회). 무료 각 회전은 새 봉인 돌3개. 구매는 독립적으로 같은 세 무료 경로에서 시작. 붉은 토기는 개수별 별도 지급표.');
 private roll(bet:number,rng:()=>number,multiplier:number,stoneCount:number,input?:string[],phase=-1){const old=this.nativePhase;this.nativePhase=phase;try{return this.nativeRoll(bet,rng,multiplier,stoneCount,input);}finally{this.nativePhase=old;}}
 private nativeRoll(bet:number,rng:()=>number,multiplier:number,stoneCount:number,input?:string[]){
  let board=input?[...input]:this.draw(rng);if(!input){board=board.map(s=>s===this.id('stone')?this.id(randomIndex(rng,6)):s);const cells=Array.from({length:36},(_,c)=>c);for(let n=0;n<stoneCount;n++){const at=randomIndex(rng,cells.length);board[cells.splice(at,1)[0]]=this.id('stone');}}
  const frames:TumbleFrame[]=[];this.frame(frames,board,'land','봉인 돌 '+indices(board,this.id('stone')).length+'개 · ×'+multiplier);
  let spent=0;for(let step=0;spent<bet*this.maxWin;step++){if(step>=100000)throw Error('Buried cascade did not settle');const wins=this.clusters(board,bet,multiplier);if(!wins.length)break;spent+=wins.reduce((a,w)=>a+w.amount,0);const removed=new Set(wins.flatMap(w=>w.cells)),stones=indices(board,this.id('stone')).filter(c=>adjacent(c,6,36).some(n=>removed.has(n)));
   this.frame(frames,board,'win','당첨 지급 후 인접 봉인 해체',{wins,cells:Array.from(removed)});stones.forEach(c=>removed.add(c));if(stones.length)this.frame(frames,board,'transform','봉인 돌 '+stones.length+'개 파괴',{cells:stones});
   const next=this.gravity(board,removed,rng,new Set(indices(board,this.id('stone')).filter(c=>!removed.has(c))));board=next.board.map(s=>s===this.id('stone')?this.id(randomIndex(rng,6)):s);
   // Preserve unbroken stones; random incoming stones become regular symbols.
   for(const c of indices(frames[frames.length-1].board,this.id('stone')))if(!removed.has(c))board[c]=this.id('stone');next.moves.forEach(m=>m.symbol=board[m.to]);
   this.frame(frames,board,'drop','돌 사이로 유물 낙하',{moves:next.moves});if(spent>=bet*this.maxWin)this.frame(frames,board,'state','최대 지급 한도 도달');
  }return{round:this.round(bet,frames),clear:!board.includes(this.id('stone'))};
 }
 play(board:string[],bet:number,rng:()=>number){this.check(board,bet);const base=this.roll(bet,rng,1,0,board);return this.complete(base,bet,rng);}
 private complete(base:{round:SpinResult;clear:boolean},bet:number,rng:()=>number){if(!base.clear)return this.finish([base.round]);
  const results=[0,1,2].map(choice=>{const rounds=[cloneSlotData(base.round)],initial=[8,5,3][choice],multiplier=[1,2,4][choice];let left=initial,awarded=left;
   while(left>0){left--;const next=this.roll(bet,rng,multiplier,3,undefined,choice),extra=next.clear?Math.min(2,30-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:initial});});
  return{...results[0],featureChoices:{title:'세 갈래 문',labels:['8회 · ×1','5회 · ×2','3회 · ×4'],results,defaultIndex:0}};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.complete(this.roll(bet,rng,1,M.paidStoneCount),bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // Each free path starts with its own freshly drawn three-stone board.
  // The discarded qualifying paid spin supplies no state to these paths.
  const frames:TumbleFrame[]=[];this.frame(frames,this.draw(rng),'state','보너스 구매 · 봉인 문 개방 · 세 경로 선택');const trigger=this.round(bet,frames);
  const results=[0,1,2].map(choice=>{const rounds:SpinResult[]=[],initial=[8,5,3][choice],multiplier=[1,2,4][choice];let left=initial,awarded=left;
   while(left>0){left--;const next=this.roll(bet,rng,multiplier,3,undefined,choice),extra=next.clear?Math.min(2,30-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return {...this.finish(rounds,{freeSpinsAwarded:initial,bonusTriggerRound:trigger}),rounds};});
  return {...results[0],featureChoices:{title:'세 갈래 문',labels:['8회 · ×1','5회 · ×2','3회 · ×4'],results,defaultIndex:0}};
 }
}
