import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {KITTEN_ART,KittenTurn,kittenSymbol as symbol,kittenSequence} from './KittenFeature';
export class KittenPreviewSlot extends SlotMain {
 constructor(private readonly fixture='yarn'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 get bonusSymbol(){return symbol('golden_paw');}
 readonly config:SlotConfig={id:'caesar-cat-palace',title:'털실 다락방',subtitle:'YARN ATTIC',tag:'전용 털실 체험',color:'#3b4054',accent:'#b7d8cf',description:'초록 털실 · 바구니 상금 증가\n빨강 털실 · 릴 세트 두 배\n파랑 털실 · 리스핀 4회\n각 릴의 당첨과 바구니 보상 합산',symbols:KITTEN_ART.map(art=>({id:symbol(art),name:art==='cat_bed'?'WILD':art.replace(/_/g,' '),color:'#b7d8cf',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('caesar-cat-palace-'.length);if(![...KITTEN_ART,'yarn_basket'].includes(name))throw Error('Unknown Kitten art');return 'slot-art-delivered-v1/caesar-cat-palace/v03/'+name;}
 spin():SpinResult{throw Error('Kitten first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const blank=()=>Array.from({length:15},(_,i)=>symbol(KITTEN_ART[(i+i%5)%10]));
  if(this.fixture==='no-win')return{bet,board:blank(),wins:[],payout:0};
  const initial=[blank()],opening=blank();opening[2]=symbol('green_yarn');opening[7]=symbol('red_yarn');opening[12]=symbol('blue_yarn');
  const turns:KittenTurn[]=[{boards:[opening],wins:[[]],green:{set:0,cell:2,amount:bet*3},red:{set:0,cell:7,newBoards:[blank()]},blue:{set:0,cell:12}}];
  for(let index=0;index<4;index++){
   const a=blank(),b=blank();if(index===0)[5,6,7].forEach(cell=>{a[cell]=symbol('attic_cat');b[cell]=symbol('milk_bottle');});
   turns.push({boards:[a,b],wins:index===0?[[{line:-1,symbol:symbol('attic_cat'),amount:bet,cells:[5,6,7]}],[{line:-1,symbol:symbol('milk_bottle'),amount:bet*2,cells:[5,6,7]}]]:[[],[]]});
  }
  return kittenSequence(initial,turns,bet);
 }
}
