import {BlockInputEvents,Color,Font,Graphics,Label,Mask,Node,Sprite,SpriteFrame,Tween,UITransform,tween} from 'cc';
import {bindButtonFeedback,buttonFace} from './ButtonFeedback';
import {i18n} from '../services/Localization';

/** Reference sequence: horizontal numbered wagons, stop, then number-only collection.
 * This view consumes an already calculated before/after pair; it never selects a prize. */
export class TrainMultiplierOverlay {
 private finishers=new Set<()=>void>();
 private stopRolling:(()=>void)|null=null;
 private offset=0;
 private cars:Node[]=[];
 private bank:Label;
 private stop:Node;
 private viewport:Node;
 private pitch:number;
 private carHeight:number;
 private panelX:number;
 private panelY:number;
 private width:number;
 constructor(readonly node:Node,screenWidth:number,screenHeight:number,panelArt:SpriteFrame,wagonArt:SpriteFrame,private font:Font|null,
  private before:number,private after:number,copy:{title:string;stop:string;applied:string}){
  node.addComponent(BlockInputEvents);
  const shade=node.addComponent(Graphics);shade.fillColor=new Color(0,0,0,128);shade.rect(0,-screenHeight,screenWidth,screenHeight);shade.fill();
  const w=this.width=Math.min(624,screenWidth-72),h=480,x=this.panelX=(screenWidth-w)/2,y=this.panelY=Math.max(130,screenHeight*.45-h/2);
  panelArt.insetLeft=20;panelArt.insetRight=20;panelArt.insetTop=18;panelArt.insetBottom=18;
  this.sprite('Train stop generated panel',node,x,y,w,h,panelArt).getComponent(Sprite)!.type=Sprite.Type.SLICED;
  this.label('Train stop title',copy.title,node,x+24,y+39,w-48,34,24,'#ffe3a0');
  const bankFace=this.child('Train multiplier medallion',node,x+w/2-36,y+80,72,72),bankInk=bankFace.addComponent(Graphics);
  bankInk.fillColor=new Color('#d9ac50');bankInk.circle(36,-36,36);bankInk.fill();bankInk.fillColor=new Color('#23466b');bankInk.circle(36,-36,30);bankInk.fill();
  this.bank=this.label('Train multiplier bank','×'+before,node,x+w*.3,y+89,w*.4,54,40,'#fff0a1');
  this.viewport=this.child('Train wagon viewport',node,x+20,y+163,w-40,236);this.viewport.addComponent(Mask).type=Mask.Type.GRAPHICS_RECT;
  const cw=(w-40)*.86;this.carHeight=cw*wagonArt.originalSize.height/wagonArt.originalSize.width;this.pitch=cw+16;
  for(let i=-1;i<=1;i++){
   const car=this.sprite('Train numbered passenger wagon',this.viewport,0,0,cw,this.carHeight,wagonArt);car.getComponent(UITransform)!.setAnchorPoint(.5,.5);
   car.setPosition((w-40)/2+i*this.pitch,-118);
   this.label('Train wagon multiplier',after>before?'×'+(after-before):'×'+before,car,-cw*.16,-this.carHeight*.025-24,cw*.32,48,34,'#173968');
   this.cars.push(car);
  }
  this.stop=this.child('Train STOP button',node,x+w*.3,y+405,w*.4,50);buttonFace(this.stop,'#e6c273','#fff0b3',true,false);
  this.label('Train STOP caption',copy.stop,this.stop,6,2,w*.4-12,46,24,'#263449');
  bindButtonFeedback(this.stop,()=>this.stopRolling?.(),{requireLiveNode:true});
  this.stop.on('train-applied',()=>{const label=this.stop.getChildByName('Train STOP caption')?.getComponent(Label);if(label)label.string=copy.applied;});
  this.place(this.pitch);
 }
 private child(name:string,parent:Node,x:number,y:number,w:number,h:number){const n=new Node(name);n.layer=parent.layer;parent.addChild(n);const t=n.addComponent(UITransform);t.setAnchorPoint(0,1);t.setContentSize(w,h);n.setPosition(x,-y);return n;}
 private sprite(name:string,parent:Node,x:number,y:number,w:number,h:number,frame:SpriteFrame){const n=this.child(name,parent,x,y,w,h),s=n.addComponent(Sprite);s.sizeMode=Sprite.SizeMode.CUSTOM;s.spriteFrame=frame;return n;}
 private label(name:string,text:string,parent:Node,x:number,y:number,w:number,h:number,size:number,ink:string){
  const n=this.child(name,parent,x,y,w,h),l=n.addComponent(Label);l.string=text;l.font=this.font;if(!this.font)l.fontFamily=i18n.fontFamily;l.fontSize=size;l.lineHeight=size*1.15;l.color=new Color(ink);l.isBold=!this.font;l.enableWrapText=false;l.overflow=Label.Overflow.SHRINK;l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;n.getComponent(UITransform)!.setContentSize(w,h);return l;
 }
 private place(offset:number){this.offset=offset;this.cars.forEach((car,i)=>{if(car.isValid)car.setPosition((this.width-40)/2+(i-1)*this.pitch+offset,-118);});}
 private animate(seconds:number,draw:(t:number)=>void,stoppable=false){
  return new Promise<void>(resolve=>{
   const clock={t:0};let done=false;
   const finish=()=>{if(done)return;done=true;clearTimeout(watchdog);Tween.stopAllByTarget(clock);this.finishers.delete(finish);if(this.stopRolling===finish)this.stopRolling=null;resolve();};
   const watchdog=setTimeout(()=>{if(this.node.isValid)draw(1);finish();},(seconds+.5)*1000);
   this.finishers.add(finish);if(stoppable)this.stopRolling=finish;
   tween(clock).to(seconds,{t:1},{easing:stoppable?'linear':'quadOut',onUpdate:()=>{if(!this.node.isValid){finish();return;}draw(clock.t);}}).call(finish).start();
  });
 }
 async play(onStage?:(stage:string)=>Promise<void>|void){
  await onStage?.('rolling');await this.animate(.9,t=>this.place(this.pitch*(1-t)),true);if(!this.node.isValid)return;
  const from=this.offset;await this.animate(.35,t=>this.place(from*(1-t)));this.stop.active=false;
  await onStage?.('stopped');await this.animate(.3,()=>{});if(!this.node.isValid)return;
  const gain=this.after-this.before;
  if(gain>0){
   const source=this.cars[1].getChildByName('Train wagon multiplier')!;source.active=false;
   const number=this.label('Train collected multiplier','+'+gain,this.node,this.panelX+this.width/2-48,this.panelY+254,96,54,40,'#ffe79e');
   const start=number.node.position.clone(),destination=this.bank.node.position.clone();
   await onStage?.('collecting');await this.animate(.45,t=>{if(number.node.isValid)number.node.setPosition(start.x+(destination.x+this.width*.2-48-start.x)*t,start.y+(destination.y-start.y)*t+Math.sin(Math.PI*t)*26);});
   if(number.node.isValid)number.node.destroy();
  }
  if(!this.node.isValid)return;
  this.bank.string='×'+this.after;this.stop.active=true;this.stop.emit('train-applied');await onStage?.('applied');await this.animate(.7,()=>{});
 }
 destroy(){for(const finish of Array.from(this.finishers))finish();if(this.node.isValid){this.node.removeFromParent();this.node.destroy();}}
}
