import {ExpansionSlot,Geometry,expansionCells as cells} from './ExpansionCore';
import {FROG_MODEL as M,frogUniform,frogOrdinary} from './FrogRefinedMath';
export class FrogRefinedSlot extends ExpansionSlot {
 private drawingFree=false;
 private grid(bet:number,rng:()=>number,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid Frog bet');const free=this.drawingFree,q=free?M.freeGate:M.gate,w=free?M.freeWild:M.baseWild,h=(free?M.freeHighByBet:M.highByBet)[bet],board=Array.from({length:15},()=>{const regular=frogOrdinary(h,rng);return this.id(frogUniform(rng)<w?'wild':regular);});let flags=0;
  if(conditional){const choices:{mask:number;mass:number}[]=[];let total=0;for(let mask=0;mask<32;mask++){const n=mask.toString(2).replace(/0/g,'').length;if(n<3)continue;const mass=q**n*(1-q)**(5-n);choices.push({mask,mass});total+=mass;}let roll=frogUniform(rng)*total;flags=choices[choices.length-1].mask;for(const v of choices){roll-=v.mass;if(roll<0){flags=v.mask;break;}}}else for(let c=0;c<5;c++)if(frogUniform(rng)<q)flags|=1<<c;
  for(let c=0;c<5;c++)if(flags>>c&1)board[Math.floor(frogUniform(rng)*3)*5+c]=this.id('scatter');return board;
 }
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(g.columns!==5||g.rows!==3)throw Error('Invalid Frog geometry');return this.grid(bet,rng);}

 private pondRound(board:string[],bet:number,rng:()=>number){
  const wilds=cells(board,this.id('wild')),after=[...board],moves:{from:number;to:number;symbol:string}[]=[],frames=[this.frame(board,'reels','개구리 WILD 착지')];
  if(wilds.length>=2){
   frames.push(this.frame(board,'trigger','개구리 두 마리 · 연못 점유 확대',wilds));
   for(const c of wilds)for(const to of [c%5>0?c-1:-1,c%5<4?c+1:-1,c>=5?c-5:-1,c<10?c+5:-1])if(to>=0&&after[to]!==this.id('scatter')){
    if(after[to]!==this.id('wild'))moves.push({from:c,to,symbol:this.id('wild')});after[to]=this.id('wild');
   }
   if(moves.length)frames.push(this.frame(after,'move','개구리 발자국 → 이웃 연못',moves.map(m=>m.to),{moves,moveMode:'copy'}));
   frames.push(this.frame(after,'effect','개구리 WILD 점유 '+cells(after,this.id('wild')).length+'/15',moves.map(m=>m.to)));
  }
  frames.push(this.hit(after,bet,'연못 점유 후 라인 지급'));
  if(cells(after,this.id('wild')).length===15)frames.push(this.frame(after,'trigger','연못 전칸 점유 · 왕관 보상',Array.from({length:15},(_,i)=>i),{actor:{symbol:this.id('2'),cells:[7]}}),this.prize(after,bet,50,Array.from({length:15},(_,i)=>i),'왕관 상금'));
  return this.finish([this.round(bet,frames)]);
 }
 play(board:string[],bet:number,rng:()=>number){const base=this.pondRound(board,bet,rng),gates=cells(board,this.id('scatter'));if(gates.length<3)return base;return this.freePond(base,bet,rng,gates);}
 private freePond(base:ReturnType<FrogRefinedSlot['pondRound']>,bet:number,rng:()=>number,gates:number[]){const saved=this.drawingFree;this.drawingFree=true;try{return this.freeFromRound(base,bet,rng,8,b=>this.pondRound(b,bet,rng),gates);}finally{this.drawingFree=saved;}}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.grid(bet,rng,true),base=this.pondRound(board,bet,rng);base.wins=[];base.payout=0;for(const f of base.expansionFeature!.frames)f.wins=[];return this.purchaseFromResult(this.freePond(base,bet,rng,cells(board,this.id('scatter'))));}
}
