import{ballroomInputBoard,ballroomInputTarget}from'./MidnightBallroomInput';
import {Win} from './SlotMain';
import {Social2230LineSlot,socialPresentation,sumResult} from './Social2230Rules';
import {socialSeed} from './Social1921Rules';
export interface BallroomPlayback {before:number[];after:number[];collected:number[];success:boolean;expired:boolean;award?:Win;}
export class MidnightBallroomSlot extends Social2230LineSlot {
 readonly presentation=socialPresentation('네 번의 기회 안에 초대장 과제','시계 과제 진행');
 readonly config=this.namedConfig('midnight-ballroom','열두시 무도회','MIDNIGHT BALLROOM',['가면 초대장','수정 구두','시계탑','호박 마차','은빛 부채','장갑','촛대','리본','춤추는 빛 WILD'],'슬롯 전용 과제: 4회 안에 지정 심볼 6개 수집.\n일반 라인 지급 후 과제 성공 시 베팅 ×3 추가.\n성공·기회 소진 뒤 새 과제로 교체. 무당첨도 수집 가능.\n진행은 베팅별 저장. 실시간 제한 대신 회전 수를 쓰는 자체 규칙.','#34314c','#d8b8de');
 protected draw(bet:number,rng:()=>number){return this.evaluate(ballroomInputBoard(this.config.id,bet,rng),bet);}
 spin(bet:number,rng:()=>number=Math.random){
  const r=this.draw(bet,rng),raw=this.state(bet,[0,0,4]),before=raw.length===3&&raw[0]<8&&raw[1]<6&&raw[2]>=1&&raw[2]<=4?raw:[0,0,4];
  const collected=r.board.flatMap((id,c)=>id===this.config.id+'-'+before[0]?[c]:[]),progress=before[1]+collected.length,remaining=before[2]-1,success=progress>=6,expired=!success&&remaining===0;
  let award:Win|undefined;if(success){award={line:-1,symbol:this.config.id+'-'+before[0],cells:collected,amount:bet*3,multiplier:3};r.wins.push(award);}
  const after=success||expired?[ballroomInputTarget(bet,rng),0,4]:[before[0],progress,remaining];
  r.ballroomFeature={before,after,collected,success,expired,award};r.progressUpdate=this.update(bet,after);return sumResult(r);
 }
 demoSpin(bet:number){const previous=this.progress;try{this.progress={[this.config.id+':'+bet]:[0,3,3]};return this.spin(bet,socialSeed(1657405714));}finally{this.progress=previous;}}
}
