import type {Win} from './SlotMain';
import type {TumbleGame} from './TumbleCore';
const codebooks=new WeakMap<TumbleGame,Map<string,number>>(),rectangles=new Map<string,number[][]>(),custom=new WeakMap<(c:number)=>number[],Map<number,number[][]>>();
/** Same component traversal and prize arithmetic as TumbleCore.connected.
 * Caches describe IDs/neighbors only; never contain player state or outcomes. */
export function nativeClusterWins(slot:TumbleGame,board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=slot.threshold):Win[]{
 let book=codebooks.get(slot);if(!book){book=new Map(Array.from({length:slot.regularCount},(_,s)=>[slot.id(s),s]));if(slot.wild)book.set(slot.wild,slot.regularCount);codebooks.set(slot,book);}
 let links:number[][];
 if(neighbors){let lengths=custom.get(neighbors);if(!lengths){lengths=new Map();custom.set(neighbors,lengths);}links=lengths.get(board.length)!;if(!links){links=Array.from({length:board.length},(_,c)=>neighbors(c));lengths.set(board.length,links);}}
 else{const key=slot.columns+'/'+board.length;links=rectangles.get(key)!;if(!links){links=Array.from({length:board.length},(_,c)=>[c-slot.columns,c+slot.columns,...(c%slot.columns?[c-1]:[]),...(c%slot.columns<slot.columns-1?[c+1]:[])].filter(n=>n>=0&&n<board.length));rectangles.set(key,links);}}
 const codes=board.map(id=>book!.get(id)??-1),wild=slot.regularCount,wins:Win[]=[];
 for(let symbol=0;symbol<slot.regularCount;symbol++){
  const seen=new Uint8Array(board.length);
  for(let cell=0;cell<board.length;cell++)if(!seen[cell]&&(codes[cell]===symbol||codes[cell]===wild)){
   const stack=[cell],group:number[]=[];seen[cell]=1;let regular=false;
   while(stack.length){const at=stack.pop()!;group.push(at);if(codes[at]===symbol)regular=true;for(const n of links[at])if(!seen[n]&&(codes[n]===symbol||codes[n]===wild)){seen[n]=1;stack.push(n);}}
   if(regular&&group.length>=minimum)wins.push({line:-1,symbol:slot.id(symbol),cells:group,amount:bet*slot.unit(symbol,group.length)*multiplier,multiplier});
  }
 }
 return wins;
}
