import {cloneSlotData,SpinResult,Win} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,randomIndex} from './TumbleCore';
import {createGlyphClusterEvaluator} from './GlyphNativeCluster';
import {GLYPH_INPUTS,glyphSymbol,glyphBinomial,glyphUniform} from './GlyphNativeMath';
export class GlyphNativeSlot extends TumbleGame {
 private inputPhase=0;private purchasing=false;
 private clusterEvaluator?:ReturnType<typeof createGlyphClusterEvaluator>;
 clusters(board:string[],bet:number,multiplier=1,neighbors?:((c:number)=>number[]),minimum=5):Win[]{if(neighbors||minimum!==5)return super.clusters(board,bet,multiplier,neighbors,minimum);this.clusterEvaluator??=createGlyphClusterEvaluator(Array.from({length:6},(_,j)=>this.id(j)),this.wild!, (j,n)=>this.unit(j,n));return this.clusterEvaluator(board,bet,multiplier);}
 pick(rng:()=>number=Math.random){return this.id(glyphSymbol(this.inputPhase,rng));}
 private conditional(rng:()=>number,minimum=3){const board=Array.from({length:30},()=>this.id(glyphSymbol(0,rng,true))),q=GLYPH_INPUTS.paidGate;const mass=Array.from({length:31},(_,n)=>n<minimum?0:glyphBinomial(30,n,q));let u=glyphUniform(rng)*mass.reduce((a,b)=>a+b,0),count=30;for(let i=minimum;i<=30;i++){u-=mass[i];if(u<0){count=i;break;}}const cells=Array.from({length:30},(_,i)=>i);for(let i=0;i<count;i++){const j=i+Math.floor(glyphUniform(rng)*(30-i));[cells[i],cells[j]]=[cells[j],cells[i]];board[cells[i]]=this.id('scatter');}return board;}
 prepareBonusPurchase(bet:number,rng:()=>number){const saved=this.purchasing;this.purchasing=true;try{return this.rawSpin(bet,rng);}finally{this.purchasing=saved;this.inputPhase=0;}}

 readonly columns=6;readonly rows=5;readonly hasBonus=true;readonly bonusChoiceCount=2;
 readonly config=this.configFor('glyph-archive','문양 보관소','GLYPH ARCHIVE',['태양 문양','달 문양','연꽃 문양','물결 문양','날개 문양','모래 문양','서기관 WILD','봉인 지도'],['0','1','2','3','4','5','wild','scatter'],'6×5 · 연결5개. 문양 위치에서 심볼을 기록하고 종료 후 해당 위치 변환→추가 낙하. 지도3개: 무료7회, 위치 고정/심볼 고정 선택. 지도4개: 둘 다. 무료 지도마다 +1(총30회).');
 private run(bet:number,rng:()=>number,state:{positions:Set<number>;symbols:Map<number,string>},mode:number,free:boolean,opening?:string[]){this.inputPhase=free?mode+1:0;let board=opening?[...opening]:this.draw(rng);const frames:TumbleFrame[]=[];if(!free||mode===1)state.positions=new Set([randomIndex(rng,30),randomIndex(rng,30),randomIndex(rng,30)]);if(!free||mode===0)state.symbols.clear();
  const heldAtStart=free&&mode!==0?Array.from(state.symbols.keys()):[];for(const [c,s]of state.symbols)board[c]=s;
  for(const c of state.positions)if(board[c]!==this.bonusSymbol)state.symbols.set(c,board[c]);
  const count=indices(board,this.bonusSymbol!).length;let transformed=false,raw=0;
  this.frame(frames,board,'land',free?['문양 위치 유지','기록 심볼 유지','위치+심볼 유지'][mode]:'문양 기록',{stationary:heldAtStart,marks:Array.from(state.positions),badges:Object.fromEntries(Array.from(state.symbols).map(([c])=>[c,'기록']))});
  while(true){
   const pinned=free&&mode!==0?new Set(state.symbols.keys()):new Set<number>();const wins=this.clusters(board,bet).filter(w=>w.cells.some(c=>!pinned.has(c)));if(wins.length){const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>!pinned.has(c)));this.frame(frames,board,'win','문양 클러스터 지급',{wins,cells:Array.from(remove),marks:Array.from(state.positions)});raw+=wins.reduce((n,w)=>n+w.amount,0);if(raw>=bet*this.maxWin)break;const next=this.gravity(board,remove,rng,pinned);board=next.board;this.frame(frames,board,'drop','기록 사이로 낙하',{moves:next.moves,marks:Array.from(state.positions)});continue;}
   if(transformed)break;transformed=true;const cells:number[]=[];for(const c of state.positions){const symbol=state.symbols.get(c);if(symbol&&board[c]!==symbol){board[c]=symbol;cells.push(c);}}if(!cells.length)break;this.frame(frames,board,'transform','스핀 종료 · 기록 문양 복원 후 재판정',{cells,marks:Array.from(state.positions)});
  }return{round:this.round(bet,frames),count};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');try{const state={positions:new Set<number>(),symbols:new Map<number,string>()},base=this.run(bet,rng,state,0,false,this.purchasing?this.conditional(rng):undefined);if(this.purchasing){base.round.wins=[];base.round.payout=0;for(const f of base.round.tumbleFeature!.frames)f.wins=[];}if(base.count<3)return this.finish([base.round]);
  const results=[0,1].map(choice=>{const local={positions:new Set(state.positions),symbols:new Map(state.symbols)},rounds=[cloneSlotData(base.round)];let left=7,awarded=7;
   while(left>0){left--;const next=this.run(bet,rng,local,base.count>=4?2:choice,true),extra=Math.min(next.count,30-awarded);left+=extra;awarded+=extra;next.round.freeSpinsRemaining=left;next.round.freeSpinsAdded=extra||undefined;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:7});});
  const result={...results[0],featureChoices:{title:base.count>=4?'슈퍼 문양 · 두 효과 유지':'문양 보관 방식',labels:['위치 유지','심볼 유지'],results,defaultIndex:0}};if(!this.purchasing)return result;const extract=(r:SpinResult)=>{const rounds=r.rounds!.slice(1),trigger=this.purchaseTrigger(base.round);return{...this.finish(rounds,{freeSpinsAwarded:7,bonusTriggerRound:trigger}),rounds};},choices=result.featureChoices.results.map(extract);return{...choices[0],featureChoices:{...result.featureChoices,results:choices}}; }finally{this.inputPhase=0;}
 }
}

