/** Legal rare conditional entry+10extra witness for source tests/isolated visual QA only. */
export function frogStoryZeroExtraTape(bet:number){const regular=(free:boolean,col:number)=>{const z=free?M.freeZeroByBet[bet]:M.baseZeroByBet[bet],rest=[6,7,8,10,12,14,16],pool=[z,...rest.map(v=>(1-z-M.wild)*v/73),M.wild],symbol=col%4;return pool.slice(0,symbol).reduce((a,b)=>a+b,0)+pool[symbol]/2;},entry=[0];for(let col=0;col<5;col++){entry.push(.1,(1+M.page)/2,.1);for(let row=0;row<3;row++)entry.push(regular(false,col));}const free=(extra:boolean)=>{const tape=[];for(let col=0;col<5;col++){tape.push(extra&&col<3?M.freeGate/2:(1+M.freeGate)/2,.1);for(let row=0;row<3;row++)tape.push(regular(true,col));}return tape;};return[...entry,...free(true),...Array.from({length:19},()=>free(false)).flat()];}

