/** Genuine saved paid-prefix state; rare explicit zero+10tape is not a natural witness. */
export function frogStoryInputAudit(id:string,params:URLSearchParams){if(id!=='frog-story-chapters')return;const s=new FrogStorySlot(EXPANSION_SPECS.find(q=>q.id===id)!),outcome=params.get('audit-outcome')||'',key=({'no-win':'empty','multi-win':'multi','bonus':'normalfree'}as Record<string,string>)[outcome]||outcome,w=FROG_STORY_WITNESSES[key];if(w){const spin=(bet:number)=>{const state=w.progress[id+':100']||[0,0];s.setProgress({[id+':'+bet]:[...state]});const r=s.spin(bet,expansionRng(w.seed));if(bet===100&&(r.payout!==w.payout||(r.rounds?.length||1)!==w.roundCount))throw Error('Stale FrogStory paid-prefix witness');return r;};s.demoSpin=spin;s.bonusDemoSpin=spin;}if(outcome==='zero-extra'){const raw=s.prepareBonusPurchase.bind(s);s.prepareBonusPurchase=(bet,_rng)=>{const tape=frogStoryZeroExtraTape(bet);let n=0;const r=raw(bet,()=>{if(n>=tape.length)throw Error('FrogStory rare input tape exhausted');return tape[n++];});if(n!==531||r.payout!==0||r.rounds!.length!==20)throw Error('Stale FrogStory rare zero-extra fixture');return r;};}return s;}
