import{MidnightBallroomSlot}from'./MidnightBallroomSlot';
import{expansionRng}from'./ExpansionCore';
import{BALLROOM_INPUTS}from'./MidnightBallroomMath';
export const BALLROOM_WITNESSES={"no-win":{"seed":25355961,"sequenceIndex":0,"before":[0,0,4],"after":[0,3,3],"payout":0,"collected":3,"success":false,"expired":false},"mission-progress":{"seed":25355961,"sequenceIndex":0,"before":[0,0,4],"after":[0,3,3],"payout":0,"collected":3,"success":false,"expired":false},"mission-success":{"seed":1657405714,"sequenceIndex":1,"before":[0,3,3],"after":[5,0,4],"payout":460,"collected":4,"success":true,"expired":false},"multi-win":{"seed":1993949666,"sequenceIndex":2,"before":[5,0,4],"after":[5,2,3],"payout":120,"collected":2,"success":false,"expired":false},"single-win":{"seed":2569326112,"sequenceIndex":5,"before":[6,0,4],"after":[6,3,3],"payout":40,"collected":3,"success":false,"expired":false},"mission-last-success":{"seed":689259196,"sequenceIndex":10,"before":[5,4,1],"after":[0,0,4],"payout":300,"collected":2,"success":true,"expired":false},"mission-expire":{"seed":1439648253,"sequenceIndex":17,"before":[7,3,1],"after":[7,0,4],"payout":40,"collected":1,"success":false,"expired":true},"mission-empty-expire":{"seed":4025608239,"sequenceIndex":25,"before":[7,0,1],"after":[4,0,4],"payout":0,"collected":0,"success":false,"expired":true}} as const;
/** QA replays actually observed continuous quest states and input seeds. */
export function midnightBallroomAudit(params:URLSearchParams){const slot=new MidnightBallroomSlot(),outcome=params.get('audit-outcome')||'mission-success',w=(BALLROOM_WITNESSES as Record<string,{seed:number;before:readonly number[];after:readonly number[];payout:number}>)[outcome];
 if(w)slot.demoSpin=bet=>{slot.setProgress({[slot.config.id+':'+bet]:[...w.before]});const r=slot.spin(bet,expansionRng(w.seed));if(bet===100&&(r.payout!==w.payout||JSON.stringify(r.ballroomFeature!.after)!==JSON.stringify(w.after)))throw Error('Stale Ballroom witness '+outcome);return r;};
 if(outcome==='highest')slot.demoSpin=bet=>{slot.setProgress({});const v=BALLROOM_INPUTS.find(r=>r.bet===bet)!;return slot.spin(bet,()=>v.regularZero/2);};return slot;
}
