/** Fixed paid/free categorical board inputs; original bingo point tables unchanged. */
export const RABBIT_INPUTS:{paidGate:number;freeGate:number;wild:number;paidBall:number;freeBall:number;freeHigh:number;highByBet:Record<number,number>}={"paidGate":0.03,"freeGate":0.01,"wild":0.005,"paidBall":0.005675,"freeBall":0.2351,"freeHigh":0.35,"highByBet":{"20":0.43298593312144473,"30":0.4402523436376581,"40":0.4351107487046637,"50":0.4395244675140828,"70":0.4376656185442054,"100":0.4384049847968945,"150":0.4362995407890259,"200":0.4371331501474288,"250":0.43715256278889647,"300":0.4366901941669771,"350":0.4367754412145296,"400":0.4371331501474288,"450":0.4371433628513234,"500":0.4368734540302167,"600":0.4371331501474288,"700":0.4369432313622751,"800":0.4371331501474288,"900":0.43698542510814287,"1000":0.4371331501474288,"2000":0.4371331501474288,"3000":0.43713315014742893,"4000":0.4371331501474288,"5000":0.43713315014742893,"6000":0.43713315014742893,"7000":0.43713315014742904,"8000":0.4371331501474288,"9000":0.43713315014742893,"10000":0.43713315014742893}};
export function rabbitUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Rabbit RNG');return u;}
export function rabbitNativeBoard(id:string,bet:number,rng:()=>number,free=false,conditional=false){
 const M=RABBIT_INPUTS,high=free?M.freeHigh:M.highByBet[bet];if(!Number.isFinite(high))throw Error('Invalid Rabbit wager');const gate=free?M.freeGate:M.paidGate,ball=free?M.freeBall:M.paidBall;
 const flags=Array(5).fill(false);if(conditional){let total=0;const list:{mask:number;mass:number}[]=[];for(let mask=0;mask<32;mask++){let n=0;for(let col=0;col<5;col++)n+=mask>>col&1;if(n<3)continue;const mass=gate**n*(1-gate)**(5-n);list.push({mask,mass});total+=mass;}let roll=rabbitUniform(rng)*total,chosen=list[list.length-1].mask;for(const item of list){roll-=item.mass;if(roll<0){chosen=item.mask;break;}}flags.forEach((_,col)=>flags[col]=!!(chosen>>col&1));}else flags.forEach((_,col)=>flags[col]=rabbitUniform(rng)<gate);
 const rows=flags.map(flag=>flag?Math.floor(rabbitUniform(rng)*5):-1),roles=['coin','double','wheel','jackpot'],weights=[4,.3,.15,.04],sum=4.49;
 return Array.from({length:25},(_,cell)=>{if(rows[cell%5]===Math.floor(cell/5))return id+'-scatter';let u=rabbitUniform(rng);
  if(u<ball){let roll=u/ball*sum;for(let n=0;n<4;n++){roll-=weights[n];if(roll<0)return id+'-'+roles[n];}return id+'-jackpot';}u=(u-ball)/(1-ball);
  if(u<M.wild)return id+'-wild';u=(u-M.wild)/(1-M.wild);if(u<high)return id+'-0';return id+'-'+(1+Math.min(6,Math.floor((u-high)/(1-high)*7)));
 });
}
