// Original strips are unpublished. These are explicit local distributions;
// bonus reels have a separate distribution, never presented as original RTP.
export class RhinoRefinedSlot extends SlotMain {
 readonly columns=6;readonly rows=8;readonly bets=[...BET_LEVELS];readonly paylines:number[][]=[];
 readonly maxWin=RHINO_MAX_WIN;readonly hasBonus=true;readonly usesReferencePayouts=true;
 readonly bonusCalibrationKey='rhino-grand-ways:variable-tumble-v1';
 readonly bonusChoiceCount=4;
 get bonusSymbol(){return rhinoSymbol(11);}get bonusTriggerCount(){return 4;}
 get unlockPriceTenths(){return 1000;}
 readonly config:SlotConfig={id:'rhino-grand-ways',title:'라이노 그랜드 웨이즈',subtitle:'RHINO GRAND WAYS',tag:'가변 릴 · 누적 배수',color:'#43543b',accent:'#e5ba64',description:'가변 6릴 · 상단 4칸\n당첨 심볼 제거 후 연쇄 낙하\n금화 4개 이상 → 프리스핀 선택\n보너스 당첨마다 다음 배수 +1\n금화 3개 이상 재등장 시 +5회',symbols:RHINO_ART.map((name,i)=>({id:rhinoSymbol(i),name:['치타','고릴라','악어','하이에나','홍학','A','K','Q','J','10','코뿔소 WILD','금화 SCATTER'][i],color:'#e5ba64',weight:BASE[i]||0,payout:RHINO_PAYS[i]?.[6]||0}))};
 displayBoard:RhinoBoard={columns:[[0,5],[1,6],[2,7],[3,8],[4,9],[5,6]],top:[6,7,8,9]};
 get cellViews(){return rhinoLayout(this.displayBoard);}
 flat(board:RhinoBoard){return rhinoFlatBoard(board);}
 artResource(id:string){const index=this.config.symbols.findIndex(s=>s.id===id);if(index<0)throw Error('Unknown Rhino art');return 'slot-art-delivered-v1/rhino-grand-ways/v07/'+RHINO_ART[index];}
 private inputCache=new Map<string,{key:string;weights:number[];sum:number}>();
 private inputPool(free:boolean,top=false,choice=0,entryCount=4){
  const high=free?(entryCount===4?RHINO_MODEL.freeHigh[choice]:RHINO_MODEL.freeExtraHigh[choice][entryCount-5]):RHINO_MODEL.baseHigh,wild=top?(free?4:2):0,id=`${free}:${top}:${choice}:${entryCount}`,key=`${high}:${wild}`;
  let pool=this.inputCache.get(id);if(!pool||pool.key!==key){const weights=[...BASE.map((w,i)=>w*(i===0?high:1)),wild];pool={key,weights,sum:weights.reduce((a,b)=>a+b,0)};this.inputCache.set(id,pool);}
  return pool;
 }
 private pickPool(rng:()=>number,pool:{weights:number[];sum:number}){
  let n=rng()*pool.sum;for(let i=0;i<pool.weights.length;i++){n-=pool.weights[i];if(n<0)return i;}return 9;
 }
 private ordinary(rng:()=>number,free:boolean,top=false,choice=0,entryCount=4){
  return this.pickPool(rng,this.inputPool(free,top,choice,entryCount));
 }
 private board(rng:()=>number,free:boolean,choice=0,entryCount=4):RhinoBoard{
  // Every reel gets one scatter opportunity and at most one scatter. Height
  // is sampled independently. No fixed winning boards or outcome rejection.
  const heights=RHINO_HEIGHTS.map((w,i)=>w*(i>0&&!free?RHINO_MODEL.baseTall:1)),sum=heights.reduce((a,b)=>a+b,0);
  const mainPool=this.inputPool(free,false,choice,entryCount),topPool=this.inputPool(free,true,choice,entryCount);
  const columns=Array.from({length:6},()=>{let roll=rng()*sum,height=7;for(let i=0;i<6;i++){roll-=heights[i];if(roll<0){height=i+2;break;}}return Array.from({length:height},()=>this.pickPool(rng,mainPool));});
  const top=Array.from({length:4},()=>this.pickPool(rng,topPool));
  columns.forEach((column,col)=>{if(rng()<(free?RHINO_MODEL.freeScatter:RHINO_MODEL.baseScatter)){const count=column.length+(col>0&&col<5?1:0),cell=Math.floor(rng()*count);if(cell===column.length)top[col-1]=11;else column[cell]=11;}});
  return {columns,top};
 }
 private refill(board:RhinoBoard,removed:number[],rng:()=>number,free:boolean,choice=0,entryCount=4):RhinoRefill{
  // Persistent scatters cannot be duplicated by a later tumble. Incoming top
  // cells may cross reel boundaries; scatter entry is confined to fresh spins.
  const mainPool=this.inputPool(free,false,choice,entryCount),topPool=this.inputPool(free,true,choice,entryCount);
  return{columns:board.columns.map((column,col)=>column.filter((_,row)=>removed.includes(col*7+row)).map(()=>this.pickPool(rng,mainPool))),top:board.top.filter((_,i)=>removed.includes(42+i)).map(()=>this.pickPool(rng,topPool))};
 }
 private round(bet:number,rng:()=>number,multiplier?:number,budget=bet*this.maxWin,opening?:RhinoBoard,choice=0,entryCount=4){return rhinoRound(opening||this.board(rng,multiplier!==undefined,choice,entryCount),bet,(board,removed)=>this.refill(board,removed,rng,multiplier!==undefined,choice,entryCount),budget,multiplier);}
 private withBonus(base:SpinResult,rng:()=>number){
  const last=base.rhinoFeature!.stages.slice(-1)[0],count=rhinoScatterCount(last.board);
  if(count<4||base.payout>=base.bet*this.maxWin)return base;
  const packages=rhinoChoices(count),selected=rhinoMysteryChoice(rng);
  const choices=packages.map((_,index)=>rhinoSequence(cloneSlotData(base),index,(multiplier,budget)=>this.round(base.bet,rng,multiplier,budget,undefined,index,count)));
  const option=packages[selected],mystery=rhinoSequence(cloneSlotData(base),selected,(multiplier,budget)=>this.round(base.bet,rng,multiplier,budget,undefined,selected,count));
  mystery.featureName=`${option.spins}회 · 시작 ×${option.multiplier}`;choices.push(mystery);
  return {...choices[0],featureChoices:{title:'프리스핀을 선택하세요',labels:[...packages.map(option=>`${option.spins}회 · 시작 ×${option.multiplier}`),'MYSTERY'],results:choices,defaultIndex:0}};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{if(!this.bets.includes(bet))throw Error('Invalid Rhino bet');return this.withBonus(this.round(bet,rng),rng);}
 demoSpin(bet:number){return this.spin(bet);}
 /** A four-gold-coin entry is landed by the existing variable-reel renderer.
  * No paid spin/cascade is sampled or rejected to find a purchase gate. */
 prepareBonusPurchaseMode(bet:number,choice:number,rng:()=>number):SpinResult{
  if(!this.bets.includes(bet)||!Number.isInteger(choice)||choice<0||choice>3)throw Error('Invalid Rhino purchase');
  const requestedChoice=choice;choice=choice===3?rhinoMysteryChoice(rng):choice;
  const board=this.board(rng,false);board.columns=board.columns.map(c=>c.map(s=>s===11?9:s));board.top=board.top.map(s=>s===11?9:s);
  const reels=[0,1,2,3,4,5];for(let i=0;i<4;i++){const j=i+Math.floor(rng()*(6-i));[reels[i],reels[j]]=[reels[j],reels[i]];const col=reels[i],height=board.columns[col].length,cell=Math.floor(rng()*(height+(col>0&&col<5?1:0)));if(cell===height)board.top[col-1]=11;else board.columns[col][cell]=11;}
  const base:SpinResult={bet,board:this.flat(board),wins:[],payout:0,rhinoFeature:{limit:bet*this.maxWin,termination:'no-win',stages:[{board,multiplier:1,nextMultiplier:1,wins:[],rawPayout:0,payout:0,end:'no-win'}]}};
  const natural=rhinoSequence(base,choice,(multiplier,budget)=>this.round(bet,rng,multiplier,budget,undefined,choice)),rounds=natural.rounds!.slice(1);
  const result={...natural,rounds,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((sum,r)=>sum+r.payout,0),bonusTriggerRound:base};
  if(requestedChoice===3){const option=rhinoChoices(4)[choice];result.featureName=`${option.spins}회 · 시작 ×${option.multiplier}`;}return result;
 }
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{
  const results=[0,1,2,3].map(choice=>this.prepareBonusPurchaseMode(bet,choice,rng)),packages=rhinoChoices(4);
  return{...results[0],featureChoices:{title:'프리스핀을 선택하세요',labels:[...packages.map(option=>`${option.spins}회 · 시작 ×${option.multiplier}`),'MYSTERY'],results,defaultIndex:0}};
 }
 bonusDemoSpin(bet:number){
  if(!this.bets.includes(bet))throw Error('Invalid Rhino bet');let seed=92465;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  const opening=this.board(rng,false);for(let col=0;col<4;col++){opening.columns[col]=opening.columns[col].map(n=>n===11?9:n);opening.columns[col][0]=11;}opening.top=opening.top.map(n=>n===11?9:n);
  return this.withBonus(this.round(bet,rng,undefined,bet*this.maxWin,opening),rng);
 }
}
