   if(landed.length){fs.push(this.frame(raw,'trigger','안전모 위치 확인',landed,{houseLevels:before},g));landed.forEach(c=>levels[c]=Math.min(3,levels[c]+1));fs.push(this.frame(raw,'effect','짚 → 나무 → 벽돌 프레임',landed,{houseLevels:levels.slice(0,rows*5)},g));}
