   const added=landed.length>=3&&awarded<120?1:0;if(added){left++;awarded++;fs.push(this.frame(raw,'trigger','안전모 3개 이상 · 무료 +1회',landed,{houseLevels:levels.slice(0,rows*5)},g));}
   if(added&&rows<6){rows++;raw.push(...Array(5).fill(''));fs.push(this.frame(raw,'expand','새 집 공간 '+rows+'행 · 프레임 보존',[],{houseLevels:levels.slice(0,rows*5)},{columns:5,rows}));}
