import{gapUniform,gapRestLabel}from'./GapInputBoard';
/** IID base labels conditioned only on at least six bomb cells. */
export function fuseConditionalBoard(id:string,q:number,high:number,wild:number,rng:()=>number){
 const options=[];let total=0;for(let n=6;n<=15;n++){let c=1;for(let k=1;k<=n;k++)c*= (16-k)/k;const mass=c*q**n*(1-q)**(15-n);options.push({n,mass});total+=mass;}let roll=gapUniform(rng)*total,count=15;for(const o of options){roll-=o.mass;if(roll<0){count=o.n;break;}}
 const board=[];for(let cell=0;cell<15;cell++){const bomb=gapUniform(rng)<count/(15-cell);if(bomb)count--;board.push(id+'-'+(bomb?'0':gapRestLabel(high,wild,gapUniform(rng))));}return board;
}
