import {FelineDoubleSlot} from './FelineDoubleSlot';import {EXPANSION_SPECS} from './ExpansionCatalog';
/** Actual before-call seeds from full paid-spin prefixes, offline QA only. */
export const FELINE_AUDIT_SEEDS:Record<string,number>={empty:235739002,multi:11455961,double:11455961,four:1281654897,free:2683200712};
export function felineAudit(params:URLSearchParams){const slot=new FelineDoubleSlot(EXPANSION_SPECS.find(s=>s.id==='feline-double-trails')!),outcome=params.get('audit-feline-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=FELINE_AUDIT_SEEDS[kind];if(initial!==undefined){const spin=(bet:number)=>{let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const r=slot.spin(bet,rng);if(kind==='free'&&(r.rounds?.length!==11||r.freeSpinsAwarded!==10))throw Error('Stale feline free witness');if(kind==='four'&&!r.wins.some(w=>w.symbol===slot.id('scatter')&&w.amount===2*bet))throw Error('Stale feline four-paw witness');return r;};slot.demoSpin=spin;if(kind==='free')slot.bonusDemoSpin=spin;}return slot;}
