import{CAST_INPUTS}from'./StarlitCastMath';
export function castInputBoard(id:string,bet:number,rng:()=>number){const v=CAST_INPUTS.find(r=>r.bet===bet);if(!v)throw Error('Invalid cast wager');const p=[v.regularZero,...[6,7,8,10,12,14].map(n=>(1-v.regularZero-v.rare-v.wild-v.stars)*n/57),v.rare,v.wild,v.stars];return Array.from({length:15},()=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid cast uniform');let mass=0,n=9;for(let i=0;i<10;i++){mass+=p[i];if(u<mass){n=i;break;}}return id+'-'+(n===8?'wild':n===9?'scatter':n);});}
